class MedianFinder {
public:
    MedianFinder() {}

    void addNum(int num) {
        nums.push_back(num);
        sort(nums.begin(), nums.end());
        int size = nums.size();

        if (size % 2 == 0) {
            nums[size / 2] = num;
        } else {
            nums[size / 2] = num;
        }
    }

    double findMedian() {
        sort(nums.begin(), nums.end());
        int size = nums.size();

        if (size % 2 == 0) {
            return (nums[size / 2] + nums[size / 2 - 1]) / 2.0;
        } else {
            return nums[size / 2];
        }
    }
};

#include <iostream>

int guess(int num) {
    if (num > n) return -1;
    else if (num < n) return 1;
    else return 0;
}

class Solution {
public:
    int guessNumber(int n) {
        while (true) {
            int guess = guess(n);
            if (guess == 0) return n;
            n = guess;
        }
    }
};

