        if (visited.find(index) != visited.end()) {
            return vector<int>();
        }

        // Mark the current cell as visited
        visited[index] = 1;

        // Flip the cell and return the index
        matrix[index] = !matrix[index];
        return vector<int>({index});
    }

    void reset() {
        // Reset the matrix to all zeros
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                matrix[i][j] = 0;
            }
        }
    }
};

