class MyQueue {
    Stack<Integer> frontStack;
    Stack<Integer> rearStack;

    public MyQueue() {
        frontStack = new Stack<>();
        rearStack = new Stack<>();
    }

    public void push(int x) {
        rearStack.push(x);
    }

    public int pop() {
        if (frontStack.isEmpty()) {
            while (!rearStack.isEmpty()) {
                frontStack.push(rearStack.pop());
            }
        }
        return frontStack.pop();
    }

    public int peek() {
        if (frontStack.isEmpty()) {
            while (!rearStack.isEmpty()) {
                frontStack.push(rearStack.pop());
            }
        }
        return frontStack.peek();
    }

    public boolean empty() {
        return frontStack.isEmpty() && rearStack.isEmpty();
    }
}

class MedianFinder {
    double leftMedian, rightMedian;

    public MedianFinder() {
    }

    public void addNum(int num) {
        if (num < leftMedian) {
            if (leftMedian == 0) {
                leftMedian = num;
            } else {
                if (rightMedian == 0) {
                    if (num < leftMedian) {
                        leftMedian = num;
                    } else {
                        rightMedian = num;
                    }
            }
        }
    }

    public double findMedian() {
        if (leftMedian == 0 && rightMedian == 0) {
            return 0.0;
        } else if (leftMedian == 0) {
            return leftMedian;
        } else if (rightMedian == 0) {
            return rightMedian;
        } else {
            if (leftMedian > rightMedian) {
                double median = (leftMedian + rightMedian) / 2.0;
            } else {
                double median = leftMedian;
            }
            return median;
        }
    }
}

class AllOne {
    Map<String, Integer> map = new HashMap<>();

    public AllOne() {
    }

    public void inc(String key) {
        if (!map.containsKey(key)) {
            map.put(key, 1);
        } else {
            int count = map.get(key);
            map.put(key, count + 1);
        }
    }

    public void dec(String key) {
        if (!map.containsKey(key)) {
            throw new RuntimeException("Key not found");
        }
        int count = map.get(key);
        if (count == 1) {
            map.remove(key);
        } else {
            map.put(key, count - 1);
        }
    }

    public String getMaxKey() {
        return Collections.max(map.keySet(), Collections.reverseOrder()).toString();
    }

    public String getMinKey() {
        return Collections.min(map.keySet(), Collections.reverseOrder()).toString();
    }
}

