class Solution {
    public String reformatNumber(String number) {
        String output = "";
        String[] parts = number.split(" ");
        for (String part : parts) {
            StringBuilder sb = new StringBuilder();
            int length = part.length();
            while (length >= 4) {
                sb.append(part);
                length -= 4;
            }
            output += sb.reverse() + "-";
        }
        return output;
    }
}

class Solution {
    public int maxTaskAssign(int[] tasks, int[] workers, int pills, int strength) {
        int result = 0;
        for (int i = 0; i < tasks.length; i++) {
            int workerIndex = findMaxWorkerIndex(workers, tasks[i], strength);
            result = Math.max(result, assignTaskAndUsePill(tasks[i], workers[workerIndex], pills);
        }
        return result;
    }

    private int findMaxWorkerIndex(int[] workers, int taskStrength, int strength) {
        int maxIndex = -1;
        for (int i = 0; i < workers.length; i++) {
            if (workers[i] >= taskStrength) {
                maxIndex = i;
            }
        }
        return maxIndex;
    }

    private int assignTaskAndUsePill(int taskStrength, int workerStrength, int pills) {
        int result = 0;
        for (int i = 0; i < pills; i++) {
            result = Math.max(result, assignTask(taskStrength, workerStrength);
        }
        return result;
