class Codec:
    def serialize(self, root: Optional[TreeNode]) -> str:
        s = []
        self.serialize_helper(root, s)
        return ''.join(s)

    def deserialize(self, data: str) -> Optional[TreeNode]:
        root = None
        self.deserialize_helper(data, root)
        return root

    def serialize_helper(self, node, s):
        if node is None:
            s.append('#')
        else:
            s.append(str(node.val))
            self.serialize_helper(node.left, s)
            self.serialize_helper(node.right, s)

    def deserialize_helper(self, data, root):
        if not data:
            return root

        if data == '#':
            return None

        root.val = int(data)
        root.left = self.deserialize_helper(data[1:len(data)-1, root)
        root.right = self.deserialize_helper(data[-1], root)

class LFUCache:
    def __init__(self, capacity):
        self.cache = {}
        self.count = {}
        for i in range(capacity):
            self.cache[i] = (0, 0)

    def get(self, key):
        if key not in self.cache:
            return -1
        count, value = self.cache[key]
        self.cache[key] = (count + 1, value)
        self.count[key] = count + 1
        return value

    def put(self, key, value):
        if key in self.cache:
            del self.cache[key]
        else:
            count, value = self.cache[key]
            self.cache[key] = (count + 1, value)
            self.count[key] = count + 1
            return value

