class Solution:
    def countOfAtoms(self, formula: str) -> str:
        result = []
        stack = []
        for char in formula:
            if char == '(':
                stack.append(char)
            elif char == ')':
                while stack and stack[-1] != '(':
                    stack.pop()
            else:
                element = {}
                while stack and stack[-1] != '(':
                    element[stack.pop()] = 1
                while stack:
                    element[stack.pop()] += 1
                result.append(element)
        return ''.join(sorted(result))

class Solution:
    def splitIntoFibonacci(self, num: str) -> List[int]:
        n = len(num)
        result = []
        for i in range(n):
            if num[i] == '0':
                continue
            if i == 0 or i == 1:
                result.append(int(num[i]))
            elif num[i - 1] == '0':
                continue
            elif num[i - 1] == num[i]:
                result.append(int(num[i - 1]) + int(num[i]))
            else:
                result.append(int(num[i - 1]) + int(num[i]) + int(num[i + 1]))
        return result

