def numberOfStableArrays(zero, one, limit):
    total = 0
    for i in range(zero, zero+one+1):
        for j in range(one+1):
            for k in range(limit+1):
                total += calculateStableArrays(i, j, k) % (10**9 + 7)
    return total

def calculateStableArrays(i, j, k):
    if i == 0 or j == 0 or k == 0:
        return 0
    if i == 1 and j == 1 and k == 1:
        return 2
    return calculateStableArrays(i-1, j, k) + calculateStableArrays(i, j-1, k) + calculateStableArrays(i, j, k-1) + calculateStableArrays(i-1, j-1, k) + calculateStableArrays(i-1, j, k-1) + calculateStableArrays(i-1, j-1, k) % (10**9 + 7)

class Solution:
    def maxStability(self, n: int, edges: List[List[int]], k: int) -> int:
        graph = {}
        for edge in edges:
            graph[edge[0]] = graph.get(edge[0], 0) + edge[1] + edge[2]
            graph[edge[1]] = graph.get(edge[1], 0) + edge[1] + edge[2]

        max_stability = float('-inf')
        for i in range(n):
            for j in range(i+1, n):
                if graph[i] + graph[j] <= k:
                    max_stability = max(max_stability, graph[i] + graph[j])
        return max_stability

