class Solution {
public:
    bool isValid(string s) {
        if (s.size() % 2 != 0) return false;
        std::unordered_map<char, char> m;
        m[')'] = '(';
        m['}'] = '{';
        m[']'] = '[';
        std::stack<char> stk;
        for (char c : s) {
            if (c == '(' || c == '{' || c == '[') {
                stk.push(c);
            } else {
                if (stk.empty()) return false;
                char top = stk.top();
                stk.pop();
                if (m[c] != top) {
                    return false;
                }
            }
        }
        return stk.empty();
    }
};

