class Solution {
public:
    int calculate(string s) {
        vector<int> numbers;
        vector<char> ops;
        string current_number;

        for (char c : s) {
            if (c == ' ') {
                if (!current_number.empty()) {
                    numbers.push_back(stoi(current_number));
                    current_number.clear();
                }
            } else if (isdigit(c)) {
                current_number += c;
            } else {
                if (!current_number.empty()) {
                    numbers.push_back(stoi(current_number));
                    current_number.clear();
                }
                ops.push_back(c);
            }
        }
        if (!current_number.empty()) {
            numbers.push_back(stoi(current_number));
        }

        int i = 0;
        while (i < ops.size()) {
            if (ops[i] == '*' || ops[i] == '/') {
                int a = numbers[i];
                int b = numbers[i + 1];
                int res;
                if (ops[i] == '*') {
                    res = a * b;
                } else {
                    res = a / b;
                }
                numbers.erase(numbers.begin() + i + 1);
                numbers[i] = res;
                ops.erase(ops.begin() + i);
            } else {
                i++;
            }
        }

        int result = numbers[0];
        for (int j = 0; j < ops.size(); j++) {
            if (ops[j] == '+') {
                result += numbers[j + 1];
            } else {
                result -= numbers[j + 1];
            }
        }

        return result;
    }
};

#include <stack>

class MyQueue {
private:
    std::stack<int> inStack;
    std::stack<int> outStack;

public:
    MyQueue() {}

    void push(int x) {
        inStack.push(x);
    }

    int pop() {
        if (outStack.empty()) {
            while (!inStack.empty()) {
                int temp = inStack.top();
                inStack.pop();
                outStack.push(temp);
            }
        }
        int top = outStack.top();
        outStack.pop();
        return top;
    }

    int peek() {
        if (outStack.empty()) {
            while (!inStack.empty()) {
                int temp = inStack.top();
                inStack.pop();
                outStack.push(temp);
            }
        }
        return outStack.top();
    }

    bool empty() {
        return inStack.empty() && outStack.empty();
    }
};

