#include <queue>
#include <vector>

using namespace std;

class MedianFinder {
private:
    priority_queue<int> low; // max-heap for the lower half
    priority_queue<int, vector<int>, greater<int>> high; // min-heap for the upper half

public:
    MedianFinder() {}

    void addNum(int num) {
        low.push(num);
        if (!high.empty() && low.top() > high.top()) {
            int val = low.top();
            low.pop();
            high.push(val);
        }
        // Balance the heaps
        if (low.size() > high.size() + 1) {
            int val = low.top();
            low.pop();
            high.push(val);
        } else if (high.size() > low.size()) {
            int val = high.top();
            high.pop();
            low.push(val);
        }
    }

    double findMedian() {
        if ((low.size() + high.size()) % 2 == 0) {
            return (low.top() + high.top()) / 2.0;
        } else {
            return low.top();
        }
    }
};

