struct DigitInfo {
    char digit;
    char unique_char;
    map<char, int> letters;
};

class Solution {
public:
    string originalDigits(string s) {
        map<char, int> freq;
        for (char c : s) {
            freq[c]++;
        }

        vector<DigitInfo> digitInfos = {
            {'0', 'z', {{'z',1}, {'e',1}, {'r',1}, {'o',1}}},
            {'2', 'w', {{'t',1}, {'w',1}, {'o',1}}},
            {'4', 'u', {{'f',1}, {'o',1}, {'u',1}, {'r',1}}},
            {'6', 'x', {{'s',1}, {'i',1}, {'x',1}}},
            {'8', 'g', {{'e',1}, {'i',1}, {'g',1}, {'h',1}, {'t',1}}},
            {'3', 'h', {{'t',1}, {'h',1}, {'r',1}, {'e',2}}},
            {'5', 'f', {{'f',1}, {'i',1}, {'v',1}, {'e',1}}},
            {'7', 's', {{'s',1}, {'e',1}, {'v',1}, {'n',1}}},
            {'1', 'o', {{'o',1}, {'n',1}, {'e',1}}},
            {'9', 'i', {{'n',2}, {'i',1}, {'e',1}}}
        };

        string result;

        for (const auto& info : digitInfos) {
            char unique = info.unique_char;
            if (freq[unique] == 0) continue;
            int count = freq[unique];
            result += string(count, info.digit);

            for (const auto& letter : info.letters) {
                char c = letter.first;
                int cnt = letter.second;
                freq[c] -= count * cnt;
            }
        }

        return result;
    }
};

