using namespace std;

class Solution {
public:
    bool canTransform(string start, string result) {
        vector<int> s_pos, res_pos;
        string s_filter, res_filter;

        for (int i = 0; i < start.size(); ++i) {
            if (start[i] == 'L' || start[i] == 'R') {
                s_filter += start[i];
                s_pos.push_back(i);
            }
        }

        for (int i = 0; i < result.size(); ++i) {
            if (result[i] == 'L' || result[i] == 'R') {
                res_filter += result[i];
                res_pos.push_back(i);
            }
        }

        if (s_filter != res_filter) {
            return false;
        }

        for (int i = 0; i < s_filter.size(); ++i) {
            if (s_filter[i] == 'L') {
                if (res_pos[i] > s_pos[i]) {
                    return false;
                }
            } else {
                if (res_pos[i] < s_pos[i]) {
                    return false;
                }
            }
        }

        return true;
    }
};

#include <queue>
#include <set>
#include <tuple>
using namespace std;

class Solution {
public:
    int racecar(int target) {
        queue<tuple<long long, int, int>> q;
        set<pair<long long, int>> visited;

        q.push({0, 1, 0});
        visited.insert({0, 1});

        while (!q.empty()) {
            auto current = q.front();
            q.pop();
            long long pos = get<0>(current);
            int speed = get<1>(current);
            int steps = get<2>(current);

            if (pos == target) {
                return steps;
            }

            // Apply 'A' command
            long long new_pos = pos + speed;
            int new_speed = speed * 2;

            // Prune conditions for 'A'
            if ((speed > 0 && new_pos > target) || (speed < 0 && new_pos < target)) {
                // Skip this state as it cannot reach target
            } else {
                if (visited.find({new_pos, new_speed}) == visited.end()) {
                    visited.insert({new_pos, new_speed});
                    q.push({new_pos, new_speed, steps + 1});
                }
            }

            // Apply 'R' command
            int new_speed_r = (speed > 0) ? -1 : 1;
            long long new_pos_r = pos;

            if (visited.find({new_pos_r, new_speed_r}) == visited.end()) {
                visited.insert({new_pos_r, new_speed_r});
                q.push({new_pos_r, new_speed_r, steps + 1});
            }
        }

        return -1; // The problem guarantees a solution, so this line is theoretically unreachable
    }
};

#include <vector>
#include <queue>
using namespace std;

class Solution {
public:
    bool canVisitAllRooms(vector<vector<int>>& rooms) {
        int n = rooms.size();
        vector<bool> visited(n, false);
        queue<int> q;
        q.push(0);
        visited[0] = true;

        while (!q.empty()) {
            int current = q.front();
            q.pop();
            for (int key : rooms[current]) {
                if (!visited[key]) {
                    visited[key] = true;
                    q.push(key);
                }
            }
        }

        for (int i = 0; i < n; ++i) {
            if (!visited[i]) {
                return false;
            }
        }
        return true;
    }
};

