class Solution {
public:
    bool backspaceCompare(string s, string t) {
        string res_s, res_t;
        for (char c : s) {
            if (c == '#') {
                if (!res_s.empty()) {
                    res_s.pop_back();
                }
            } else {
                res_s.push_back(c);
            }
        }
        for (char c : t) {
            if (c == '#') {
                if (!res_t.empty()) {
                    res_t.pop_back();
                }
            } else {
                res_t.push_back(c);
            }
        }
        return res_s == res_t;
    }
};

