class Solution {
public:
    int superEggDrop(int k, int n) {
        vector<int> dp(k + 1, 0);
        int m = 0;
        while (dp[k] < n) {
            m++;
            for (int i = k; i >= 1; i--) {
                dp[i] += dp[i - 1] + 1;
            }
        }
        return m;
    }
};

#include <vector>
#include <unordered_set>
#include <algorithm>

using namespace std;

vector<long long> generate_powers(int base, int bound) {
    vector<long long> res;
    if (base == 1) {
        res.push_back(1);
        return res;
    }
    long long current = 1;
    res.push_back(current);
    while (true) {
        current *= base;
        if (current > bound) {
            break;
        }
        res.push_back(current);
    }
    return res;
}

vector<int> powerfulIntegers(int x, int y, int bound) {
    vector<long long> A = generate_powers(x, bound);
    vector<long long> B = generate_powers(y, bound);

    unordered_set<int> result;

    for (long long a : A) {
        if (a > bound) continue;
        int target = bound - a;
        if (target < 1) continue;

        auto it = upper_bound(B.begin(), B.end(), target);
        int idx = it - B.begin() - 1;

        if (idx >= 0) {
            for (int j = 0; j <= idx; ++j) {
                long long s = a + B[j];
                if (s <= bound) {
                    result.insert(s);
                }
            }
        }
    }

    return vector<int>(result.begin(), result.end());
}

#include <vector>
#include <numeric>
#include <algorithm>

using namespace std;

class Solution {
public:
    int shipWithinDays(vector<int>& weights, int days) {
        int total = accumulate(weights.begin(), weights.end(), 0);
        int maxWeight = *max_element(weights.begin(), weights.end());

        int low = maxWeight;
        int high = total;
        int answer = total;

        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (canShip(mid, weights, days)) {
                answer = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }

        return answer;
    }

private:
    bool canShip(int capacity, const vector<int>& weights, int days) {
        if (weights.empty()) return true;
        int daysNeeded = 1;
        int currentLoad = weights[0];

        for (size_t i = 1; i < weights.size(); ++i) {
            if (currentLoad + weights[i] > capacity) {
                daysNeeded++;
                currentLoad = weights[i];
            } else {
                currentLoad += weights[i];
            }
        }

        return daysNeeded <= days;
    }
};

#include <vector>
#include <algorithm>

using namespace std;

class Solution {
public:
    string smallestEquivalentString(string s1, string s2, string baseStr) {
        vector<int> parent(26);
        vector<int> rank(26);
        vector<char> min_char(26);

        for (int i = 0; i < 26; ++i) {
            parent[i] = i;
            rank[i] = 1;
            min_char[i] = 'a' + i;
        }

        for (int i = 0; i < s1.size(); ++i) {
            char c1 = s1[i];
            char c2 = s2[i];
            int idx1 = c1 - 'a';
            int idx2 = c2 - 'a';

            // Find root of idx1
            int root1 = idx1;
            while (parent[root1] != root1) {
                root1 = parent[root1];
            }

            // Find root of idx2
            int root2 = idx2;
            while (parent[root2] != root2) {
                root2 = parent[root2];
            }

            if (root1 != root2) {
                if (rank[root1] > rank[root2]) {
                    swap(root1, root2);
                }
                parent[root1] = root2;
                if (rank[root1] == rank[root2]) {
                    rank[root2]++;
                }
                if (min_char[root1] < min_char[root2]) {
                    min_char[root2] = min_char[root1];
                }
            }
        }

        string result;
        for (char c : baseStr) {
            int idx = c - 'a';
            int root = idx;
            while (parent[root] != root) {
                root = parent[root];
            }
            result += min_char[root];
        }

        return result;
    }
};

#include <string>
using namespace std;

class Solution {
public:
    string gcdOfStrings(string str1, string str2) {
        int len1 = str1.size();
        int len2 = str2.size();

        int g = gcd(len1, len2);

        for (int d = g; d >= 1; --d) {
            if (g % d != 0) continue;

            string x = str1.substr(0, d);
            bool valid = true;

            // Check for str1
            int m = x.size();
            if (len1 % m != 0) {
                valid = false;
            } else {
                for (int i = 0; i < len1; i += m) {
                    if (str1.substr(i, m) != x) {
                        valid = false;
                        break;
                    }
                }
            }

            if (!valid) continue;

            // Check for str2
            if (len2 % m != 0) {
                valid = false;
            } else {
                for (int i = 0; i < len2; i += m) {
                    if (str2.substr(i, m) != x) {
                        valid = false;
                        break;
                    }
                }
            }

            if (valid) {
                return x;
            }
        }

        return "";
    }
};

