class Solution {
public:
    vector<int> maxDepthAfterSplit(string seq) {
        vector<int> result(seq.size());
        stack<int> stk;
        int a_depth = 0, b_depth = 0;

        for (int i = 0; i < seq.size(); ++i) {
            if (seq[i] == '(') {
                if (a_depth <= b_depth) {
                    stk.push(0);
                    a_depth++;
                } else {
                    stk.push(1);
                    b_depth++;
                }
            } else {
                int assign = stk.top();
                stk.pop();
                result[i] = assign;
                if (assign == 0) {
                    a_depth--;
                } else {
                    b_depth--;
                }
            }
        }
        return result;
    }
};

#include <vector>
#include <queue>
using namespace std;

class Solution {
public:
    vector<int> shortestAlternatingPaths(int n, vector<vector<int>>& redEdges, vector<vector<int>>& blueEdges) {
        vector<vector<int>> red(n), blue(n);
        for (auto& e : redEdges) red[e[0]].push_back(e[1]);
        for (auto& e : blueEdges) blue[e[0]].push_back(e[1]);

        vector<vector<int>> dist(n, vector<int>(2, -1));
        vector<int> ans(n, -1);
        ans[0] = 0;

        queue<tuple<int, int, int>> q;
        for (int v : red[0]) {
            if (dist[v][0] == -1) {
                dist[v][0] = 1;
                q.push({v, 0, 1});
            }
        }
        for (int v : blue[0]) {
            if (dist[v][1] == -1) {
                dist[v][1] = 1;
                q.push({v, 1, 1});
            }
        }

        while (!q.empty()) {
            auto [u, c, d] = q.front();
            q.pop();
            if (c == 0) {
                for (int v : blue[u]) {
                    if (dist[v][1] == -1 || dist[v][1] > d + 1) {
                        dist[v][1] = d + 1;
                        q.push({v, 1, d + 1});
                    }
                }
            } else {
                for (int v : red[u]) {
                    if (dist[v][0] == -1 || dist[v][0] > d + 1) {
                        dist[v][0] = d + 1;
                        q.push({v, 0, d + 1});
                    }
                }
            }
        }

        for (int i = 0; i < n; ++i) {
            if (i == 0) continue;
            int d0 = dist[i][0], d1 = dist[i][1];
            ans[i] = (d0 == -1 && d1 == -1) ? -1 : min(d0, d1);
        }
        return ans;
    }
};

