        stack<string> stk;
        string current;
        for (char c : s) {
            if (c == '(') {
                stk.push(current);
                current.clear();
            } else if (c == ')') {
                string prev = stk.top();
                stk.pop();
                reverse(current.begin(), current.end());
                current = prev + current;
            } else {
                current += c;
            }
        }
        return current;
    }
};

