using namespace std;

class CombinationIterator {
public:
    CombinationIterator(string characters, int combinationLength) {
        generateCombinations(characters, combinationLength);
    }

    string next() {
        string res = combinations[index];
        index++;
        return res;
    }

    bool hasNext() {
        return index < combinations.size();
    }

private:
    vector<string> combinations;
    int index = 0;

    void generateCombinations(string chars, int k) {
        vector<string> result;
        backtrack(chars, 0, k, "", result);
        combinations = result;
    }

    void backtrack(string& chars, int start, int remaining, string current, vector<string>& result) {
        if (remaining == 0) {
            result.push_back(current);
            return;
        }
        for (int i = start; i <= chars.size() - remaining; ++i) {
            current += chars[i];
            backtrack(chars, i + 1, remaining - 1, current, result);
            current.pop_back();
        }
    }
};

#include <string>
#include <vector>
#include <unordered_map>

using namespace std;

class Solution {
public:
    int maxFreq(string s, int maxLetters, int minSize, int maxSize) {
        int globalMax = 0;
        int n = s.size();

        for (int L = minSize; L <= maxSize; ++L) {
            if (L > n) continue;

            unordered_map<string, int> freqMap;
            vector<int> freq(26, 0);
            int unique = 0;

            // Initialize the first window
            for (int i = 0; i < L; ++i) {
                char c = s[i];
                if (freq[c - 'a'] == 0) {
                    unique++;
                }
                freq[c - 'a']++;
            }

            int currentMax = 0;
            if (unique <= maxLetters) {
                string substr = s.substr(0, L);
                freqMap[substr] = 1;
                currentMax = 1;
            }

            // Slide the window
            for (int i = L; i < n; ++i) {
                // Remove the leftmost character
                char left = s[i - L];
                if (freq[left - 'a'] == 1) {
                    unique--;
                }
                freq[left - 'a']--;

                // Add the new right character
                char right = s[i];
                if (freq[right - 'a'] == 0) {
                    unique++;
                }
                freq[right - 'a']++;

                // Check if current window is valid
                if (unique <= maxLetters) {
                    string substr = s.substr(i - L + 1, L);
                    freqMap[substr]++;
                    if (freqMap[substr] > currentMax) {
                        currentMax = freqMap[substr];
                    }
                }
            }

            if (currentMax > globalMax) {
                globalMax = currentMax;
            }
        }

        return globalMax;
    }
};

