class Solution {
public:
    int numberOfSubstrings(string s) {
        int n = s.size();
        int total = n * (n + 1) / 2;

        auto count_substrings = [](const string& s, const string& allowed) {
            int res = 0;
            int current_run = 0;
            for (char c : s) {
                if (allowed.find(c) != string::npos) {
                    current_run++;
                } else {
                    res += current_run * (current_run + 1) / 2;
                    current_run = 0;
                }
            }
            res += current_run * (current_run + 1) / 2;
            return res;
        };

        int missing_a = count_substrings(s, "bc");
        int missing_b = count_substrings(s, "ac");
        int missing_c = count_substrings(s, "ab");

        int missing_ab = count_substrings(s, "c");
        int missing_ac = count_substrings(s, "b");
        int missing_bc = count_substrings(s, "a");

        int invalid = (missing_a + missing_b + missing_c) - (missing_ab + missing_ac + missing_bc);
        return total - invalid;
    }
};

#include <unordered_map>
using namespace std;

class Solution {
public:
    int findTheLongestSubstring(string s) {
        unordered_map<int, int> mask_map;
        mask_map[0] = -1;
        int current_mask = 0;
        int max_len = 0;
        int n = s.size();
        for (int i = 0; i < n; ++i) {
            char c = s[i];
            if (c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u') {
                int bit;
                switch(c) {
                    case 'a': bit = 0; break;
                    case 'e': bit = 1; break;
                    case 'i': bit = 2; break;
                    case 'o': bit = 3; break;
                    case 'u': bit = 4; break;
                    default: continue;
                }
                current_mask ^= (1 << bit);
            }
            if (mask_map.find(current_mask) != mask_map.end()) {
                int len = i - mask_map[current_mask];
                if (len > max_len) {
                    max_len = len;
                }
            } else {
                mask_map[current_mask] = i;
            }
        }
        return max_len;
    }
};

