            for (char c : s) {
                if (c != '0') {
                    freq[c]++;
                }
            }
            bool valid = true;
            for (char c : s) {
                if (c == '0') {
                    valid = false;
                    break;
                }
                int d = c - '0';
                if (freq[c] != d) {
                    valid = false;
                    break;
                }
            }
            if (valid) {
                return x;
            }
        }
    }
};

