using namespace std;

class Solution {
public:
    int maxTaskAssign(vector<int>& tasks, vector<int>& workers, int pills, int strength) {
        sort(tasks.begin(), tasks.end());
        sort(workers.begin(), workers.end());

        int n = tasks.size();
        int m = workers.size();
        int i = n - 1;
        int j = m - 1;
        int count = 0;
        int pills_used = 0;

        while (i >= 0 && j >= 0) {
            if (workers[j] >= tasks[i]) {
                count++;
                i--;
                j--;
            } else if (pills_used < pills) {
                if (workers[j] + strength >= tasks[i]) {
                    count++;
                    i--;
                    j--;
                    pills_used++;
                } else {
                    j--;
                }
            } else {
                j--;
            }
        }

        return count;
    }
};

#include <vector>
#include <unordered_set>
#include <unordered_map>
#include <algorithm>

using namespace std;

class Solution {
public:
    vector<int> findAllPeople(int n, vector<vector<int>>& meetings, int firstPerson) {
        unordered_set<int> secret;
        secret.insert(0);
        secret.insert(firstPerson);

        unordered_map<int, vector<pair<int, int>>> timeMeetings;
        for (const auto& m : meetings) {
            int time = m[2];
            timeMeetings[time].emplace_back(m[0], m[1]);
        }

        vector<int> times;
        for (const auto& [t, _] : timeMeetings) {
            times.push_back(t);
        }
        sort(times.begin(), times.end());

        for (int t : times) {
            const auto& edges = timeMeetings[t];

            unordered_map<int, int> parent;
            for (const auto& edge : edges) {
                int x = edge.first;
                int y = edge.second;
                parent[x] = x;
                parent[y] = y;
            }

            for (const auto& edge : edges) {
                int x = edge.first;
                int y = edge.second;
                unionDSU(x, y, parent);
            }

            unordered_set<int> infected_roots;
            for (const auto& [node, _] : parent) {
                if (secret.count(node)) {
                    int root = findDSU(node, parent);
                    infected_roots.insert(root);
                }
            }

            for (const auto& [node, _] : parent) {
                int root = findDSU(node, parent);
                if (infected_roots.count(root)) {
                    secret.insert(node);
                }
            }
        }

        return vector<int>(secret.begin(), secret.end());
    }

private:
    int findDSU(int x, unordered_map<int, int>& parent) {
        if (parent[x] != x) {
            parent[x] = findDSU(parent[x], parent);
        }
        return parent[x];
    }

    void unionDSU(int x, int y, unordered_map<int, int>& parent) {
        int rootX = findDSU(x, parent);
        int rootY = findDSU(y, parent);
        if (rootX != rootY) {
            parent[rootX] = rootY;
        }
    }
};

#include <vector>
#include <algorithm>

using namespace std;

class Solution {
public:
    int kIncreasing(vector<int>& arr, int k) {
        int res = 0;
        for (int group = 0; group < k; ++group) {
            vector<int> group_elements;
            for (int i = group; i < static_cast<int>(arr.size()); i += k) {
                group_elements.push_back(arr[i]);
            }
            int lnds = computeLNDS(group_elements);
            res += group_elements.size() - lnds;
        }
        return res;
    }

private:
    int computeLNDS(const vector<int>& group) {
        vector<int> tails;
        for (int num : group) {
            auto it = upper_bound(tails.begin(), tails.end(), num);
            if (it == tails.end()) {
                tails.push_back(num);
            } else {
                *it = num;
            }
        }
        return tails.size();
    }
};

