        int t_counts[26] = {0};
        int s_counts[26] = {0};

        for (char c : target) {
            t_counts[c - 'a']++;
        }

        for (char c : s) {
            s_counts[c - 'a']++;
        }

        int res = INT_MAX;
        for (int i = 0; i < 26; ++i) {
            if (t_counts[i] == 0) continue;
