using namespace std;

class Solution {
public:
    long long repairCars(vector<int>& ranks, int cars) {
        int r_max = *max_element(ranks.begin(), ranks.end());
        long long low = 0;
        long long high = (long long) cars * cars * r_max;

        while (low < high) {
            long long mid = low + (high - low) / 2;
            long long total = 0;

            for (int r : ranks) {
                double val = static_cast<double>(mid) / r;
                int x = static_cast<int>(sqrt(val));
                total += x;
                if (total >= cars) break;
            }

            if (total >= cars) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }

        return low;
    }
};

#include <unordered_map>
#include <algorithm>

class Solution {
public:
    int maximumCostSubstring(string s, string chars, vector<int>& vals) {
        unordered_map<char, int> char_values;
        for (int i = 0; i < chars.size(); ++i) {
            char_values[chars[i]] = vals[i];
        }

        int current_max = 0;
        int max_so_far = 0;

        for (char c : s) {
            int value;
            if (char_values.find(c) != char_values.end()) {
                value = char_values[c];
            } else {
                value = c - 'a' + 1;
            }

            current_max = std::max(value, current_max + value);
            max_so_far = std::max(max_so_far, current_max);
        }

        return max_so_far;
    }
};

#include <vector>
#include <algorithm>
using namespace std;

class Solution {
public:
    long long maximumTripletValue(vector<int>& nums) {
        int n = nums.size();
        if (n < 3) return 0;

        vector<long long> left_max(n, LLONG_MIN);
        vector<long long> left_min(n, LLONG_MAX);

        for (int j = 1; j < n; j++) {
            for (int i = 0; i < j; i++) {
                long long diff = nums[i] - nums[j];
                if (diff > left_max[j]) {
                    left_max[j] = diff;
                }
                if (diff < left_min[j]) {
                    left_min[j] = diff;
                }
            }
        }

        vector<long long> right_max(n, LLONG_MIN);
        vector<long long> right_min(n, LLONG_MAX);

        for (int j = n - 2; j >= 0; j--) {
            right_max[j] = max(nums[j + 1], right_max[j + 1]);
            right_min[j] = min(nums[j + 1], right_min[j + 1]);
        }

        long long max_val = 0;

        for (int j = 1; j < n - 1; j++) {
            long long a = left_max[j] * right_max[j];
            long long b = left_max[j] * right_min[j];
            long long c = left_min[j] * right_max[j];
            long long d = left_min[j] * right_min[j];

            long long current_max = max({a, b, c, d});
            if (current_max > max_val) {
                max_val = current_max;
            }
        }

        return max_val > 0 ? max_val : 0;
    }
};

#include <vector>
#include <string>
#include <climits>
#include <algorithm>
using namespace std;

class Solution {
public:
    int minimumChanges(string s, int k) {
        int n = s.size();
        if (n == 0) return 0;

        // Precompute cost[a][b] for all substrings s[a..b]
        vector<vector<int>> cost(n, vector<int>(n, 0));
        for (int a = 0; a < n; a++) {
            for (int b = a; b < n; b++) {
                int len = b - a + 1;
                vector<int> divisors = get_divisors(len);
                int min_cost = INT_MAX;
                for (int d : divisors) {
                    if (d >= len) continue;
                    int current_cost = 0;
                    for (int group_start = 0; group_start < d; group_start++) {
                        string group;
                        for (int i = group_start; i < len; i += d) {
                            group += s[a + i];
                        }
                        int changes = 0;
                        int m = group.size();
                        for (int i = 0; i < m / 2; i++) {
                            if (group[i] != group[m - 1 - i]) {
                                changes++;
                            }
                        }
                        current_cost += changes;
                    }
                    if (current_cost < min_cost) {
                        min_cost = current_cost;
                    }
                }
                cost[a][b] = (min_cost == INT_MAX) ? 0 : min_cost;
            }
        }

        // Initialize DP table
        vector<vector<int>> dp(n + 1, vector<int>(k + 1, INT_MAX));
        dp[0][0] = 0;

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= k; j++) {
                for (int l = j - 1; l < i; l++) {
                    if (dp[l][j - 1] != INT_MAX) {
                        int current_cost = dp[l][j - 1] + cost[l][i - 1];
                        if (current_cost < dp[i][j]) {
                            dp[i][j] = current_cost;
                        }
                    }
                }
            }
        }

        return dp[n][k];
    }

private:
    vector<int> get_divisors(int len) {
        vector<int> res;
        if (len == 1) {
            return res;
        }
        for (int d = 1; d < len; d++) {
            if (len % d == 0) {
                res.push_back(d);
            }
        }
        return res;
    }
};

#include <string>
#include <algorithm>

using namespace std;

class Solution {
public:
    int findMinimumOperations(string s1, string s2, string s3) {
        int len1 = s1.size();
        int len2 = s2.size();
        int len3 = s3.size();

        int min_len = min({len1, len2, len3});

        for (int L = min_len; L >= 1; L--) {
            if (len1 < L || len2 < L || len3 < L) continue;
            string sub1 = s1.substr(len1 - L, L);
            string sub2 = s2.substr(len2 - L, L);
            string sub3 = s3.substr(len3 - L, L);

            if (sub1 == sub2 && sub2 == sub3) {
                return (len1 - L) + (len2 - L) + (len3 - L);
            }
        }
        return -1;
    }
};

