class Solution {
public:
    long long minimumSteps(string s) {
        int n = s.size();
        vector<int> rightZero(n + 1, 0);
        for (int i = n - 1; i >= 0; --i) {
            rightZero[i] = rightZero[i + 1] + (s[i] == '0');
        }
        long long res = 0;
        for (int i = 0; i < n; ++i) {
            if (s[i] == '1') {
                res += rightZero[i + 1];
            }
        }
        return res;
    }
};

#include <queue>
#include <unordered_set>
#include <vector>

using namespace std;

class Solution {
public:
    int minimumOperationsToMakeEqual(int x, int y) {
        if (x == y) return 0;

        queue<pair<int, int>> q;
        unordered_set<int> visited;

        q.push({x, 0});
        visited.insert(x);

        while (!q.empty()) {
            auto [current, steps] = q.front();
            q.pop();

            vector<int> nexts;
            nexts.push_back(current + 1);
            nexts.push_back(current - 1);

            if (current % 5 == 0) {
                nexts.push_back(current / 5);
            }
            if (current % 11 == 0) {
                nexts.push_back(current / 11);
            }

            for (int next : nexts) {
                if (next == y) {
                    return steps + 1;
                }
                if (visited.find(next) == visited.end()) {
                    visited.insert(next);
                    q.push({next, steps + 1});
                }
            }
        }

        return -1; // This line is theoretically unreachable
    }
};

#include <vector>
#include <algorithm>
using namespace std;

class Solution {
public:
    vector<int> beautifulIndices(string s, string a, string b, int k) {
        vector<int> A, B;
        int len_a = a.size();
        int len_b = b.size();

        // Collect all starting indices for a
        for (int i = 0; i <= s.size() - len_a; ++i) {
            if (s.substr(i, len_a) == a) {
                A.push_back(i);
            }
        }

        // Collect all starting indices for b
        for (int i = 0; i <= s.size() - len_b; ++i) {
            if (s.substr(i, len_b) == b) {
                B.push_back(i);
            }
        }

        vector<int> res;
        for (int i : A) {
            int low = i - k;
            int high = i + k;
            auto it = lower_bound(B.begin(), B.end(), low);
            if (it != B.end() && *it <= high) {
                res.push_back(i);
            }
        }

        return res;
    }
};

#include <vector>
#include <algorithm>
#include <string>

using namespace std;

class Solution {
public:
    vector<int> beautifulIndices(string s, string a, string b, int k) {
        vector<int> A = findOccurrences(s, a);
        vector<int> B = findOccurrences(s, b);

        vector<int> result;
        for (int i : A) {
            int left = i - k;
            int right = i + k;
            auto it = lower_bound(B.begin(), B.end(), left);
            if (it != B.end() && *it <= right) {
                result.push_back(i);
            }
        }
        return result;
    }

private:
    static vector<int> computeLPS(const string& pattern) {
        int m = pattern.size();
        vector<int> lps(m, 0);
        int length = 0;
        for (int i = 1; i < m; ++i) {
            while (length > 0 && pattern[i] != pattern[length]) {
                length = lps[length - 1];
            }
            if (pattern[i] == pattern[length]) {
                length++;
                lps[i] = length;
            } else {
                lps[i] = 0;
            }
        }
        return lps;
    }

    static vector<int> findOccurrences(const string& text, const string& pattern) {
        vector<int> occurrences;
        int n = text.size();
        int m = pattern.size();
        if (m == 0 || n < m) return occurrences;

        vector<int> lps = computeLPS(pattern);
        int i = 0, j = 0;
        while (i < n) {
            if (text[i] == pattern[j]) {
                i++;
                j++;
                if (j == m) {
                    occurrences.push_back(i - j);
                    j = lps[j - 1];
                }
            } else {
                if (j != 0) {
                    j = lps[j - 1];
                } else {
                    i++;
                }
            }
        }
        return occurrences;
    }
};

#include <vector>

using namespace std;

class Solution {
public:
    int numberOfStableArrays(int zero, int one, int limit) {
        const int MOD = 1e9 + 7;
        vector<vector<vector<vector<int>>>> dp(zero + 1, vector<one + 1, vector<2, vector<int>>>(2, vector<int>(limit + 2, 0)));

        if (zero > 0) {
            dp[1][0][0][1] = 1;
        }
        if (one > 0) {
            dp[0][1][1][1] = 1;
        }

        for (int z = 0; z <= zero; ++z) {
            for (int o = 0; o <= one; ++o) {
                for (int d = 0; d < 2; ++d) {
                    for (int r = 1; r <= limit; ++r) {
                        if (dp[z][o][d][r] == 0) continue;

                        // Try adding 0
                        if (z < zero) {
                            if (d == 0) {
                                int new_r = r + 1;
                                if (new_r <= limit) {
                                    dp[z + 1][o][0][new_r] = (dp[z + 1][o][0][new_r] + dp[z][o][d][r]) % MOD;
                                }
                            } else {
                                dp[z + 1][o][0][1] = (dp[z + 1][o][0][1] + dp[z][o][d][r]) % MOD;
                            }
                        }

                        // Try adding 1
                        if (o < one) {
                            if (d == 1) {
                                int new_r = r + 1;
                                if (new_r <= limit) {
                                    dp[z][o + 1][1][new_r] = (dp[z][o + 1][1][new_r] + dp[z][o][d][r]) % MOD;
                                }
                            } else {
                                dp[z][o + 1][1][1] = (dp[z][o + 1][1][1] + dp[z][o][d][r]) % MOD;
                            }
                        }
                    }
                }
            }
        }

        int result = 0;
        for (int d = 0; d < 2; ++d) {
            for (int r = 1; r <= limit; ++r) {
                result = (result + dp[zero][one][d][r]) % MOD;
            }
        }
        return result;
    }
};

#include <string>

using namespace std;

class Solution {
public:
    int minStartingIndex(string s, string pattern) {
        int n = s.size();
        int m = pattern.size();
        for (int i = 0; i <= n - m; ++i) {
            int mismatches = 0;
            for (int j = 0; j < m; ++j) {
                if (s[i + j] != pattern[j]) {
                    ++mismatches;
                    if (mismatches > 1) {
                        break;
                    }
                }
            }
            if (mismatches <= 1) {
                return i;
            }
        }
        return -1;
    }
};

#include <vector>
using namespace std;

class Solution {
public:
    int numberOfWays(int n, int x, int y) {
        const int MOD = 1000000007;
        static bool initialized = false;
        if (!initialized) {
            fact.resize(1001);
            fact[0] = 1;
            for (int i = 1; i <= 1000; ++i) {
                fact[i] = fact[i-1] * i % MOD;
            }
            inv_fact.resize(1001);
            inv_fact[1000] = mod_pow(fact[1000], MOD-2, MOD);
            for (int i = 999; i >= 0; --i) {
                inv_fact[i] = inv_fact[i+1] * (i+1) % MOD;
            }
            stir.resize(1001, vector<long long>(1001, 0));
            stir[0][0] = 1;
            for (int i = 1; i <= 1000; ++i) {
                for (int j = 1; j <= i; ++j) {
                    stir[i][j] = (j * stir[i-1][j] + stir[i-1][j-1]) % MOD;
                }
            }
            initialized = true;
        }
        long long res = 0;
        int max_m = min(x, n);
        for (int m = 1; m <= max_m; ++m) {
            if (x < m) continue;
            long long comb = fact[x] * inv_fact[m] % MOD;
            comb = comb * inv_fact[x - m] % MOD;
            long long s = stir[n][m];
            long long term = comb * s % MOD;
            term = term * fact[m] % MOD;
            long long y_pow = mod_pow(y, m, MOD);
            term = term * y_pow % MOD;
            res = (res + term) % MOD;
        }
        return res % MOD;
    }

    static long long mod_pow(long long base, int exponent, int mod) {
        long long result = 1;
        base = base % mod;
        while (exponent > 0) {
            if (exponent % 2 == 1) {
                result = (result * base) % mod;
            }
            base = (base * base) % mod;
            exponent /= 2;
        }
        return result;
    }

private:
    static vector<long long> fact;
    static vector<long long> inv_fact;
    static vector<vector<long long>> stir;
};

