#include <vector>
#include <string>

using namespace std;

class Solution {
public:
    int countWinningSequences(string s) {
        const int MOD = 1000000007;
        const int OFFSET = 1000;
        const int MAX_DIFF = 2000;

        vector<vector<int>> current_dp(4, vector<int>(MAX_DIFF + 1, 0));
        current_dp[0][OFFSET] = 1; // Initial state: 0 rounds, no last move, difference 0

        for (char a : s) {
            vector<vector<int>> next_dp(4, vector<int>(MAX_DIFF + 1, 0));

            for (int last_move = 0; last_move < 4; ++last_move) {
                for (int d_offset = 0; d_offset <= MAX_DIFF; ++d_offset) {
                    if (current_dp[last_move][d_offset] == 0) continue;
                    int count = current_dp[last_move][d_offset];
                    int d = d_offset - OFFSET;

                    for (int b = 1; b <= 3; ++b) {
                        if (last_move != 0 && b == last_move) continue;

                        int delta = 0;
                        if (a == 'F') {
                            if (b == 1) delta = 0;
                            else if (b == 2) delta = 1;
                            else delta = -1;
                        } else if (a == 'W') {
                            if (b == 1) delta = -1;
                            else if (b == 2) delta = 0;
                            else delta = 1;
                        } else { // a == 'E'
                            if (b == 1) delta = 1;
                            else if (b == 2) delta = -1;
                            else delta = 0;
                        }

                        int new_d = d + delta;
                        if (new_d < -OFFSET || new_d > OFFSET) continue;
                        int new_d_offset = new_d + OFFSET;

                        next_dp[b][new_d_offset] = (next_dp[b][new_d_offset] + count) % MOD;
                    }
                }
            }
            current_dp = next_dp;
        }

        int result = 0;
        for (int b = 1; b <= 3; ++b) {
            for (int d_offset = OFFSET + 1; d_offset <= MAX_DIFF; ++d_offset) {
                result = (result + current_dp[b][d_offset]) % MOD;
            }
        }
        return result;
    }
};

#include <vector>
#include <string>
#include <algorithm>

using namespace std;

class Solution {
public:
    int possibleStringCount(string word, int k) {
        const int MOD = 1e9 + 7;
        vector<int> runs;
        char prev = word[0];
        int count = 1;
        for (size_t i = 1; i < word.size(); ++i) {
            if (word[i] == prev) {
                count++;
            } else {
                runs.push_back(count);
                prev = word[i];
                count = 1;
            }
        }
        runs.push_back(count);

        int sum_runs = 0;
        for (int ni : runs) {
            sum_runs += ni;
        }
        if (sum_runs < k) {
            return 0;
        }

        int total = 1;
        for (int ni : runs) {
            total = (total * ni) % MOD;
        }

        vector<int> dp(k, 0);
        dp[0] = 1;

        for (int ni : runs) {
            vector<int> new_dp(k, 0);
            vector<int> prefix(k, 0);
            prefix[0] = dp[0];
            for (int i = 1; i < k; ++i) {
                prefix[i] = (prefix[i-1] + dp[i]) % MOD;
            }
            for (int s = 1; s < k; ++s) {
                int max_m = min(ni, s);
                int low = s - max_m;
                if (low < 0) low = 0;
                int sum_ways = (prefix[s-1] - (low > 0 ? prefix[low-1] : 0)) % MOD;
                new_dp[s] = sum_ways;
            }
            dp = new_dp;
        }

        int invalid = 0;
        for (int i = 0; i < k; ++i) {
            invalid = (invalid + dp[i]) % MOD;
        }

        int ans = (total - invalid) % MOD;
        if (ans < 0) ans += MOD;
        return ans;
    }
};

