#include <stack>
#include <algorithm>
using namespace std;

class Solution {
public:
    string resultingString(string s) {
        stack<char> stk;
        for (char c : s) {
            if (!stk.empty()) {
                char top = stk.top();
                if ((abs(c - top) == 1) || (c == 'a' && top == 'z') || (c == 'z' && top == 'a')) {
                    stk.pop();
                    continue;
                }
            }
            stk.push(c);
        }
        string result;
        while (!stk.empty()) {
            result += stk.top();
            stk.pop();
        }
        reverse(result.begin(), result.end());
        return result;
    }
};

#include <vector>
#include <queue>
#include <tuple>
#include <bitset>
#include <limits>
using namespace std;

class Solution {
public:
    double minTime(int n, int k, int m, vector<int>& time, vector<double>& mul) {
        if (n == 0) return 0.0;
        if (k == 0) return -1.0;

        int initial_bitmask = (1 << n) - 1;
        priority_queue<tuple<double, int, int>, vector<tuple<double, int, int>>, greater<tuple<double, int, int>>> heap;
        heap.push(make_tuple(0.0, initial_bitmask, 0));

        vector<vector<double>> dist(1 << n, vector<double>(m, numeric_limits<double>::infinity()));
        dist[initial_bitmask][0] = 0.0;

        double best = -1.0;

        while (!heap.empty()) {
            auto [current_time, bitmask, stage] = heap.top();
            heap.pop();

            if (best != -1.0 && current_time >= best) {
                continue;
            }

            if (bitmask == 0) {
                best = current_time;
                continue;
            }

            for (int group_mask = 1; group_mask < (1 << n); ++group_mask) {
                if ((group_mask & bitmask) != group_mask) {
                    continue;
                }
                int s = __builtin_popcount(group_mask);
                if (s < 1 || s > k) {
                    continue;
                }

                int max_time = 0;
                for (int i = 0; i < n; ++i) {
                    if (group_mask & (1 << i)) {
                        if (time[i] > max_time) {
                            max_time = time[i];
                        }
                    }
                }

                double crossing_time = max_time * mul[stage];
                int new_stage_after_crossing = (stage + static_cast<int>(crossing_time)) % m;
                int new_bitmask_after_crossing = bitmask & (~group_mask);

                if (new_bitmask_after_crossing == 0) {
                    if (current_time + crossing_time < best || best == -1.0) {
                        best = current_time + crossing_time;
                    }
                    continue;
                }

                for (int i = 0; i < n; ++i) {
                    if (group_mask & (1 << i)) {
                        double return_time = time[i] * mul[new_stage_after_crossing];
                        int new_stage_after_return = (new_stage_after_crossing + static_cast<int>(return_time)) % m;
                        int new_bitmask_after_return = new_bitmask_after_crossing | (1 << i);

                        double total_time = current_time + crossing_time + return_time;

                        if (total_time < dist[new_bitmask_after_return][new_stage_after_return]) {
                            dist[new_bitmask_after_return][new_stage_after_return] = total_time;
                            heap.push(make_tuple(total_time, new_bitmask_after_return, new_stage_after_return));
                        }
                    }
                }
            }
        }

        return (best != -1.0) ? best : -1.0;
    }
};

#include <vector>
#include <tuple>
#include <algorithm>

using namespace std;

class Solution {
public:
    int maxStability(int n, vector<vector<int>>& edges, int k) {
        int low = 1;
        int high = 2 * 100000; // Maximum possible strength after upgrade
        int answer = -1;

        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (check(mid, n, edges, k)) {
                answer = mid;
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }

        return answer;
    }

private:
    bool check(int S, int n, vector<vector<int>>& edges, int k) {
        DSU dsu(n);
        int must_count = 0;

        for (auto& edge : edges) {
            int u = edge[0];
            int v = edge[1];
            int s = edge[2];
            int must = edge[3];

            if (must == 1) {
                if (s < S) {
                    return false;
                }
                if (dsu.find(u) == dsu.find(v)) {
                    return false; // Cycle detected
                }
                dsu.union_nodes(u, v);
                must_count++;
            }
        }

        if (must_count > n - 1) {
            return false;
        }

        int c = dsu.count_components();
        if (c == 1) {
            return true;
        }

        vector<tuple<int, int, int>> optional;
        for (auto& edge : edges) {
            int u = edge[0];
            int v = edge[1];
            int s = edge[2];
            int must = edge[3];

            if (must == 0) {
                if (s >= S) {
                    optional.emplace_back(u, v, 0);
                } else if (2 * s >= S) {
                    optional.emplace_back(u, v, 1);
                }
            }
        }

        sort(optional.begin(), optional.end(), [](const tuple<int, int, int>& a, const tuple<int, int, int>& b) {
            return get<2>(a) < get<2>(b);
        });

        int upgrades_used = 0;
        int edges_added = 0;

        for (auto& e : optional) {
            int u = get<0>(e);
            int v = get<1>(e);
            int cost = get<2>(e);

            if (dsu.find(u) != dsu.find(v)) {
                dsu.union_nodes(u, v);
                upgrades_used += cost;
                edges_added++;

                if (edges_added == c - 1) {
                    break;
                }
            }
        }

        return edges_added == c - 1 && upgrades_used <= k;
    }

    class DSU {
    private:
        vector<int> parent;
        vector<int> rank;
        int components;

    public:
        DSU(int n) {
            parent.resize(n);
            rank.resize(n, 0);
            components = n;
            for (int i = 0; i < n; ++i) {
                parent[i] = i;
            }
        }

        int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }

        void union_nodes(int x, int y) {
            int x_root = find(x);
            int y_root = find(y);
            if (x_root == y_root) {
                return;
            }
            if (rank[x_root] < rank[y_root]) {
                parent[x_root] = y_root;
            } else {
                parent[y_root] = x_root;
                if (rank[x_root] == rank[y_root]) {
                    rank[x_root]++;
                }
            }
            components--;
        }

        int count_components() {
            return components;
        }
    };
};

