    static string convertToBase(int num, int base) {
        if (num == 0) {
            return "0";
        }
        string result;
        while (num > 0) {
            int remainder = num % base;
            char c;
            if (remainder < 10) {
                c = '0' + remainder;
            } else {
                c = 'A' + (remainder - 10);
            }
            result = c + result;
            num = num / base;
        }
        return result;
    }
