#include <vector>
#include <builtin>
using namespace std;

class Solution {
public:
    vector<int> popcountDepth(vector<long long>& nums, vector<vector<long long>>& queries) {
        vector<int> depths;
        for (auto x : nums) {
            depths.push_back(computeDepth(x));
        }
        SegmentTree st(depths);
        vector<int> ans;
        for (auto& q : queries) {
            if (q[0] == 1) {
                int l = q[1], r = q[2], k = q[3];
                ans.push_back(st.query(l, r, k));
            } else {
                int idx = q[1];
                long long val = q[2];
                int old_depth = depths[idx];
                int new_depth = computeDepth(val);
                depths[idx] = new_depth;
                st.update(idx, old_depth, new_depth);
            }
        }
        return ans;
    }

private:
    int computeDepth(long long x) {
        if (x == 1) return 0;
        int depth = 0;
        while (x != 1) {
            x = __builtin_popcountll(x);
            depth++;
        }
        return depth;
    }

    class SegmentTree {
    public:
        SegmentTree(const vector<int>& depths) {
            n = depths.size();
            size = 1;
            while (size < n) {
                size <<= 1;
            }
            tree.resize(2 * size, vector<int>(MAX_DEPTH, 0));
            for (int i = 0; i < n; ++i) {
                tree[size + i][depths[i]]++;
            }
            for (int i = size - 1; i >= 1; --i) {
                for (int d = 0; d < MAX_DEPTH; ++d) {
                    tree[i][d] = tree[2*i][d] + tree[2*i+1][d];
                }
            }
        }

        void update(int idx, int old_d, int new_d) {
            idx += size;
            tree[idx][old_d]--;
            tree[idx][new_d]++;
            idx >>= 1;
            while (idx >= 1) {
                for (int d = 0; d < MAX_DEPTH; ++d) {
                    tree[idx][d] = tree[2*idx][d] + tree[2*idx+1][d];
                }
                idx >>= 1;
            }
        }

        int query(int l, int r, int k) {
            int res = 0;
            l += size;
            r += size;
            while (l <= r) {
                if (l % 2 == 1) {
                    res += tree[l][k];
                    l++;
                }
                if (r % 2 == 0) {
                    res += tree[r][k];
                    r--;
                }
                l >>= 1;
                r >>= 1;
            }
            return res;
        }

    private:
        int size;
        vector<vector<int>> tree;
        static const int MAX_DEPTH = 60;
    };
};

import java.util.Stack;
import java.util.HashMap;

class Solution {
    public boolean isValid(String s) {
        Stack<Character> stack = new Stack<>();
        HashMap<Character, Character> map = new HashMap<>();
        map.put(')', '(');
        map.put('}', '{);
        map.put(']', '[');

        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '(' || c == '{' || c == '[') {
                stack.push(c);
            } else {
                if (stack.isEmpty()) {
                    return false;
                }
                char top = stack.pop();
                if (map.get(c) != top) {
                    return false;
                }
            }
        }
        return stack.isEmpty();
    }
}

import java.util.PriorityQueue;
import java.util.Comparator;

class Solution {
    public ListNode mergeKLists(ListNode[] lists) {
        if (lists == null || lists.length == 0) {
            return null;
        }

        PriorityQueue<ListNode> heap = new PriorityQueue<>(Comparator.comparingInt(l -> l.val));

        for (ListNode list : lists) {
            if (list != null) {
                heap.add(list);
            }
        }

        ListNode dummy = new ListNode(0);
        ListNode current = dummy;

        while (!heap.isEmpty()) {
            ListNode smallest = heap.poll();
            current.next = smallest;
            current = current.next;

            if (smallest.next != null) {
                heap.add(smallest.next);
            }
        }

        return dummy.next;
    }
}

