class Solution {
    public int nthUglyNumber(int n) {
        PriorityQueue<Integer> heap = new PriorityQueue<>();
        HashSet<Integer> seen = new HashSet<>();

        heap.add(1);
        seen.add(1);

        int result = 0;
        for (int i = 1; i <= n; i++) {
            result = heap.poll();
            int next2 = result * 2;
            if (!seen.contains(next2)) {
                heap.add(next2);
                seen.add(next2);
            }
            int next3 = result * 3;
            if (!seen.contains(next3)) {
                heap.add(next3);
                seen.add(next3);
            }
            int next5 = result * 5;
            if (!seen.contains(next5)) {
                heap.add(next5);
                seen.add(next5);
            }
        }
        return result;
    }
}

import java.util.PriorityQueue;

class MedianFinder {

    private PriorityQueue<Integer> lower; // max-heap implemented as min-heap with negatives
    private PriorityQueue<Integer> higher; // min-heap

    public MedianFinder() {
        lower = new PriorityQueue<>();
        higher = new PriorityQueue<>();
    }

    public void addNum(int num) {
        if (lower.isEmpty() || num <= -lower.peek()) {
            lower.add(-num);
        } else {
            higher.add(num);
        }

        // Balance the heaps
        if (lower.size() > higher.size() + 1) {
            int maxLower = -lower.poll();
            higher.add(maxLower);
        } else if (higher.size() > lower.size()) {
            int minHigher = higher.poll();
            lower.add(-minHigher);
        }
    }

    public double findMedian() {
        int total = lower.size() + higher.size();
        if (total % 2 == 1) {
            return (double) (-lower.peek());
        } else {
            double a = -lower.peek();
            double b = higher.peek();
            return (a + b) / 2.0;
        }
    }
}

import java.util.*;

class Solution {
    public List<String> removeInvalidParentheses(String s) {
        Queue<String> queue = new LinkedList<>();
        Set<String> visited = new HashSet<>();
        List<String> result = new ArrayList<>();

        queue.add(s);
        visited.add(s);

        boolean found = false;

        while (!queue.isEmpty()) {
            int size = queue.size();
            for (int i = 0; i < size; i++) {
                String current = queue.poll();
                if (isValid(current)) {
                    result.add(current);
                    found = true;
                } else {
                    for (int j = 0; j < current.length(); j++) {
                        if (current.charAt(j) == '(' || current.charAt(j) == ')') {
                            String newStr = current.substring(0, j) + current.substring(j + 1);
                            if (!visited.contains(newStr)) {
                                visited.add(newStr);
                                queue.add(newStr);
                            }
                        }
                    }
                }
            }
            if (found) {
                break;
            }
        }

        return result;
    }

    private boolean isValid(String s) {
        int balance = 0;
        for (char c : s.toCharArray()) {
            if (c == '(') {
                balance++;
            } else if (c == ')') {
                balance--;
                if (balance < 0) {
                    return false;
                }
            }
        }
        return balance == 0;
    }
}

