            if (node.next != null) {
                node.next.prev = node.prev;
            } else {
                tail = node.prev;
            }
        }
        Node removeLast() {
            Node last = tail;
            if (last != null) {
                if (last.prev != null) {
                    last.prev.next = null;
                    tail = last.prev;
                } else {
                    head = null;
                    tail = null;
                }
            }
            return last;
        }
        boolean isEmpty() {
            return head == null;
        }
    }

    private HashMap<Integer, Node> keyToNode;
    private HashMap<Integer, DoublyLinkedList> freqToNodes;
    private TreeSet<Integer> frequencies;
    private int capacity;

    public LFUCache(int capacity) {
        this.capacity = capacity;
        keyToNode = new HashMap<>();
        freqToNodes = new HashMap<>();
        frequencies = new TreeSet<>();
    }

    public int get(int key) {
        if (!keyToNode.containsKey(key)) {
            return -1;
        }
        Node node = keyToNode.get(key);
        int value = node.value;
        int oldFreq = node.frequency;
        node.frequency++;
        int newFreq = node.frequency;

        DoublyLinkedList oldList = freqToNodes.get(oldFreq);
        oldList.remove(node);
        if (oldList.isEmpty()) {
            freqToNodes.remove(oldFreq);
            frequencies.remove(oldFreq);
        }

        DoublyLinkedList newList = freqToNodes.get(newFreq);
        if (newList == null) {
            newList = new DoublyLinkedList();
            freqToNodes.put(newFreq, newList);
            frequencies.add(newFreq);
        }
        newList.addFirst(node);

        return value;
    }

    public void put(int key, int value) {
        if (capacity == 0) return;

        if (keyToNode.containsKey(key)) {
            Node node = keyToNode.get(key);
            node.value = value;
            int oldFreq = node.frequency;
            node.frequency++;
            int newFreq = node.frequency;

            DoublyLinkedList oldList = freqToNodes.get(oldFreq);
            oldList.remove(node);
            if (oldList.isEmpty()) {
                freqToNodes.remove(oldFreq);
                frequencies.remove(oldFreq);
            }

            DoublyLinkedList newList = freqToNodes.get(newFreq);
            if (newList == null) {
                newList = new DoublyLinkedList();
                freqToNodes.put(newFreq, newList);
                frequencies.add(newFreq);
            }
            newList.addFirst(node);
        } else {
            if (keyToNode.size() >= capacity) {
                int minFreq = frequencies.first();
                DoublyLinkedList minList = freqToNodes.get(minFreq);
                Node lruNode = minList.removeLast();
                keyToNode.remove(lruNode.key);
                if (minList.isEmpty()) {
                    freqToNodes.remove(minFreq);
                    frequencies.remove(minFreq);
                }
            }

            Node newNode = new Node(key, value, 1);
            keyToNode.put(key, newNode);
            DoublyLinkedList newList = freqToNodes.get(1);
            if (newList == null) {
                newList = new DoublyLinkedList();
                freqToNodes.put(1, newList);
                frequencies.add(1);
            }
            newList.addFirst(newNode);
        }
    }
}

import java.util.HashSet;
import java.util.Random;

class Solution {

    private int m;
    private int n;
    private HashSet<Integer> flippedIdx;
    private Random rand;

    public Solution(int m, int n) {
        this.m = m;
        this.n = n;
        this.flippedIdx = new HashSet<>();
        this.rand = new Random();
    }

    public int[] flip() {
        while (true) {
            int idx = rand.nextInt(m * n);
            if (!flippedIdx.contains(idx)) {
                flippedIdx.add(idx);
                int i = idx / n;
                int j = idx % n;
                return new int[]{i, j};
            }
        }
    }

    public void reset() {
        flippedIdx.clear();
    }
}

import java.util.Random;
import java.util.Arrays;

class Solution {

    private int[] prefix;
    private int totalSum;
    private Random random;

    public Solution(int[] w) {
        random = new Random();
        int n = w.length;
        prefix = new int[n + 1];
        prefix[0] = 0;
        for (int i = 0; i < n; i++) {
            prefix[i + 1] = prefix[i] + w[i];
        }
        totalSum = prefix[n];
    }

    public int pickIndex() {
        int r = random.nextInt(totalSum);
        int idx = Arrays.binarySearch(prefix, r);
        if (idx >= 0) {
            return idx;
        } else {
            int insertionPoint = (-idx) - 1;
            return insertionPoint - 1;
        }
    }
}

