class Solution {
    public List<List<String>> findDuplicate(String[] paths) {
        Map<String, List<String>> contentMap = new HashMap<>();
        for (String path : paths) {
            String[] dirAndFiles = path.split(" ", 2);
            String directory = dirAndFiles[0];
            String[] fileStrings = dirAndFiles[1].split(" ");
            for (String fileStr : fileStrings) {
                String[] parts = fileStr.split("\\(", 2);
                String filename = parts[0];
                String content = parts[1].substring(0, parts[1].length() - 1);
                String fullPath = directory + "/" + filename;
                contentMap.computeIfAbsent(content, k -> new ArrayList<>()).add(fullPath);
            }
        }
        List<List<String>> result = new ArrayList<>();
        for (List<String> list : contentMap.values()) {
            if (list.size() >= 2) {
                result.add(list);
            }
        }
        return result;
    }
}

class Solution {
    public int minSteps(int n) {
        if (n == 1) {
            return 0;
        }
        int sum = 0;
        for (int i = 2; i * i <= n; i++) {
            while (n % i == 0) {
                sum += i;
                n /= i;
            }
        }
        if (n > 1) {
            sum += n;
        }
        return sum;
    }
}

import java.util.HashMap;
import java.util.Map;

class Solution {
    public boolean isPossible(int[] nums) {
        Map<Integer, Integer> freq = new HashMap<>();
        for (int num : nums) {
            freq.put(num, freq.getOrDefault(num, 0) + 1);
        }

        Map<Integer, Integer> count = new HashMap<>();

        for (int x : nums) {
            if (freq.get(x) == 0) {
                continue;
            }

            if (count.containsKey(x - 1) && count.get(x - 1) > 0) {
                count.put(x - 1, count.get(x - 1) - 1);
                count.put(x, count.getOrDefault(x, 0) + 1);
                freq.put(x, freq.get(x) - 1);
            } else {
                if (freq.getOrDefault(x, 0) > 0 &&
                    freq.getOrDefault(x + 1, 0) > 0 &&
                    freq.getOrDefault(x + 2, 0) > 0) {

                    freq.put(x, freq.get(x) - 1);
                    freq.put(x + 1, freq.get(x + 1) - 1);
                    freq.put(x + 2, freq.get(x + 2) - 1);
                    count.put(x + 2, count.getOrDefault(x + 2, 0) + 1);
                } else {
                    return false;
                }
            }
        }

        return true;
    }
}

import java.util.HashSet;
import java.util.Set;

class Solution {
    public int flipLights(int n, int presses) {
        Set<String> states = new HashSet<>();

        for (int b1 = 0; b1 <= 1; b1++) {
            for (int b2 = 0; b2 <= 1; b2++) {
                for (int b3 = 0; b3 <= 1; b3++) {
                    for (int b4 = 0; b4 <= 1; b4++) {
                        int s = b1 + b2 + b3 + b4;
                        if (s > presses || (s % 2) != (presses % 2)) {
                            continue;
                        }
                        StringBuilder sb = new StringBuilder();
                        for (int j = 1; j <= n; j++) {
                            int flips = 0;
                            if (b1 == 1) flips++;
                            if (b2 == 1 && j % 2 == 0) flips++;
                            if (b3 == 1 && j % 2 == 1) flips++;
                            if (b4 == 1 && (j - 1) % 3 == 0) flips++;
                            sb.append(flips % 2 == 0 ? '1' : '0');
                        }
                        states.add(sb.toString());
                    }
                }
            }
        }
        return states.size();
    }
}

import java.util.Collections;

class Solution {
    public int repeatedStringMatch(String a, String b) {
        // Check if b is a substring of a
        if (a.contains(b)) {
            return 1;
        }

        int lenA = a.length();
        int lenB = b.length();

        // Calculate the minimal number of repetitions needed
        int kMin = (lenB + lenA - 1) / lenA;

        // Check for kMin repetitions
        String s = repeat(a, kMin);
        if (s.contains(b)) {
            return kMin;
        }

        // Check for kMin + 1 repetitions
        s = repeat(a, kMin + 1);
        if (s.contains(b)) {
            return kMin + 1;
        }

        // If not found in either case
        return -1;
    }

    // Helper method to repeat a string k times
    private String repeat(String s, int times) {
        if (times <= 0) {
            return "";
        }
        return String.join("", Collections.nCopies(times, s));
    }
}

import java.util.ArrayList;
import java.util.List;

class Solution {
    public int countBinarySubstrings(String s) {
        List<int[]> groups = new ArrayList<>();
        if (s.isEmpty()) return 0;

        char prev = s.charAt(0);
        int count = 1;

        for (int i = 1; i < s.length(); i++) {
            if (s.charAt(i) == prev) {
                count++;
            } else {
                groups.add(new int[]{count, prev == '0' ? 0 : 1});
                prev = s.charAt(i);
                count = 1;
            }
        }
        groups.add(new int[]{count, prev == '0' ? 0 : 1});

        int total = 0;
        for (int i = 0; i < groups.size() - 1; i++) {
            int[] current = groups.get(i);
            int[] next = groups.get(i + 1);
            if (current[1] != next[1] && current[0] == next[0]) {
                total += current[0];
            }
        }

        return total;
    }
}

import java.util.PriorityQueue;

class KthLargest {
    private PriorityQueue<Integer> heap;
    private int k;

    public KthLargest(int k, int[] nums) {
        this.k = k;
        heap = new PriorityQueue<>();
        for (int num : nums) {
            heap.add(num);
        }
        while (heap.size() > k) {
            heap.poll();
        }
    }

    public int add(int val) {
        heap.add(val);
        if (heap.size() > k) {
            heap.poll();
        }
        return heap.peek();
    }
}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

class MyCalendarThree {

    private List<Integer> starts = new ArrayList<>();
    private List<Integer> ends = new ArrayList<>();
    private int maxK = 0;

    public MyCalendarThree() {

    }

    public int book(int startTime, int endTime) {
        if (starts.isEmpty()) {
            starts.add(startTime);
            ends.add(endTime);
            maxK = 1;
            return 1;
        }

        int insertionPointA = Arrays.binarySearch(starts, endTime);
        int A;
        if (insertionPointA >= 0) {
            A = insertionPointA;
        } else {
            A = (-insertionPointA) - 1;
        }

        int insertionPointB = Arrays.binarySearch(ends, startTime);
        int B;
        if (insertionPointB >= 0) {
            B = insertionPointB + 1;
        } else {
            B = (-insertionPointB) - 1;
        }

        int currentK = A - B + 1;
        if (currentK > maxK) {
            maxK = currentK;
        }

        int indexS = Arrays.binarySearch(starts, startTime);
        if (indexS >= 0) {
            indexS++;
        } else {
            indexS = (-indexS) - 1;
        }
        starts.add(indexS, startTime);

        int indexE = Arrays.binarySearch(ends, endTime);
        if (indexE >= 0) {
            indexE++;
        } else {
            indexE = (-indexE) - 1;
        }
        ends.add(indexE, endTime);

        return maxK;
    }
}

import java.util.*;

class Solution {
    public int racecar(int target) {
        Queue<int[]> queue = new LinkedList<>();
        queue.add(new int[] {0, 1, 0});

        Map<Integer, Set<Integer>> visited = new HashMap<>();
        visited.put(0, new HashSet<>(Collections.singleton(1)));

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int pos = current[0];
            int speed = current[1];
            int steps = current[2];

            if (pos == target) {
                return steps;
            }

            // Apply 'A' command
            int newPosA = pos + speed;
            int newSpeedA = speed * 2;
            if (!visited.containsKey(newPosA) || !visited.get(newPosA).contains(newSpeedA)) {
                if (newPosA == target) {
                    return steps + 1;
                }
                if (!visited.containsKey(newPosA)) {
                    visited.put(newPosA, new HashSet<>());
                }
                visited.get(newPosA).add(newSpeedA);
                queue.add(new int[] {newPosA, newSpeedA, steps + 1});
            }

            // Apply 'R' command
            int newSpeedR = speed > 0 ? -1 : 1;
            int newPosR = pos;
            if (!visited.containsKey(newPosR) || !visited.get(newPosR).contains(newSpeedR)) {
                if (!visited.containsKey(newPosR)) {
                    visited.put(newPosR, new HashSet<>());
                }
                visited.get(newPosR).add(newSpeedR);
                queue.add(new int[] {newPosR, newSpeedR, steps + 1});
            }
        }

        return -1; // Should not reach here as per problem constraints
    }
}

import java.util.ArrayList;
import java.util.List;

class Solution {
    public List<List<Integer>> largeGroupPositions(String s) {
        List<List<Integer>> result = new ArrayList<>();
        if (s == null || s.isEmpty()) {
            return result;
        }

        int currentStart = 0;
        char currentChar = s.charAt(0);

        for (int i = 1; i < s.length(); i++) {
            if (s.charAt(i) != currentChar) {
                int end = i - 1;
                int length = i - currentStart;
                if (length >= 3) {
                    List<Integer> group = new ArrayList<>();
                    group.add(currentStart);
                    group.add(end);
                    result.add(group);
                }
                currentStart = i;
                currentChar = s.charAt(i);
            }
        }

        // Process the last group
        int end = s.length() - 1;
        int length = end - currentStart + 1;
        if (length >= 3) {
            List<Integer> group = new ArrayList<>();
            group.add(currentStart);
            group.add(end);
            result.add(group);
        }

        return result;
    }
}

