class Solution {
    public boolean canVisitAllRooms(List<List<Integer>> rooms) {
        int n = rooms.size();
        boolean[] visited = new boolean[n];
        Queue<Integer> queue = new LinkedList<>();
        queue.add(0);
        visited[0] = true;

        while (!queue.isEmpty()) {
            int current = queue.poll();
            for (int key : rooms.get(current)) {
                if (!visited[key]) {
                    visited[key] = true;
                    queue.add(key);
                }
            }
        }

        for (int i = 0; i < n; i++) {
            if (!visited[i]) {
                return false;
            }
        }
        return true;
    }
}

import java.util.ArrayList;
import java.util.List;

class Solution {
    public List<Integer> splitIntoFibonacci(String num) {
        int len = num.length();
        for (int i = 1; i <= len - 2; i++) {
            String aStr = num.substring(0, i);
            if (aStr.length() > 1 && aStr.charAt(0) == '0') {
                continue;
            }
            long aLong;
            try {
                aLong = Long.parseLong(aStr);
            } catch (NumberFormatException e) {
                continue;
            }
            if (aLong > Integer.MAX_VALUE || aLong < Integer.MIN_VALUE) {
                continue;
            }
            int a = (int) aLong;

            for (int j = 1; j <= len - i - 1; j++) {
                int bEnd = i + j;
                if (bEnd > len) {
                    break;
                }
                String bStr = num.substring(i, bEnd);
                if (bStr.length() > 1 && bStr.charAt(0) == '0') {
                    continue;
                }
                long bLong;
                try {
                    bLong = Long.parseLong(bStr);
                } catch (NumberFormatException e) {
                    continue;
                }
                if (bLong > Integer.MAX_VALUE || bLong < Integer.MIN_VALUE) {
                    continue;
                }
                int b = (int) bLong;

                List<Integer> result = new ArrayList<>();
                result.add(a);
                result.add(b);
                int pos = bEnd;
                int prev1 = a;
                int prev2 = b;
                boolean valid = true;

                while (pos < len) {
                    long sum = (long) prev1 + (long) prev2;
                    if (sum > Integer.MAX_VALUE) {
                        valid = false;
                        break;
                    }
                    int sumInt = (int) sum;
                    String sumStr = Integer.toString(sumInt);
                    if (num.startsWith(sumStr, pos)) {
                        result.add(sumInt);
                        prev1 = prev2;
                        prev2 = sumInt;
                        pos += sumStr.length();
                    } else {
                        valid = false;
                        break;
                    }
                }

                if (valid && pos == len && result.size() >= 3) {
                    return result;
                }
            }
        }
        return new ArrayList<>();
    }
}

import java.util.Arrays;

class Solution {
    public boolean reorderedPowerOf2(int n) {
        String s = Integer.toString(n);
        int len = s.length();
        char[] arr = s.toCharArray();
        Arrays.sort(arr);
        String sortedN = new String(arr);

        long power = 1;
        while (true) {
            String powerStr = Long.toString(power);
            int currentLen = powerStr.length();
            if (currentLen > len) {
                break;
            }
            if (currentLen == len) {
                char[] powerArr = powerStr.toCharArray();
                Arrays.sort(powerArr);
                String sortedPower = new String(powerArr);
                if (sortedPower.equals(sortedN)) {
                    return true;
                }
            }
            power *= 2;
        }
        return false;
    }
}

