import java.util.*;

class Solution {
    public boolean possibleBipartition(int n, int[][] dislikes) {
        List<List<Integer>> adj = new ArrayList<>(n + 1);
        for (int i = 0; i <= n; i++) {
            adj.add(new ArrayList<>());
        }
        for (int[] dislike : dislikes) {
            int a = dislike[0];
            int b = dislike[1];
            adj.get(a).add(b);
            adj.get(b).add(a);
        }

        int[] color = new int[n + 1];
        Arrays.fill(color, -1);

        for (int i = 1; i <= n; i++) {
            if (color[i] == -1) {
                Queue<Integer> queue = new LinkedList<>();
                queue.add(i);
                color[i] = 0;
                while (!queue.isEmpty()) {
                    int u = queue.poll();
                    for (int v : adj.get(u)) {
                        if (color[v] == -1) {
                            color[v] = 1 - color[u];
                            queue.add(v);
                        } else if (color[v] == color[u]) {
                            return false;
                        }
                    }
                }
            }
        }
        return true;
    }
}

import java.util.HashMap;
import java.util.Map;
import java.util.PriorityQueue;

class FreqElement implements Comparable<FreqElement> {
    int val;
    int freq;
    int ts;

    public FreqElement(int val, int freq, int ts) {
        this.val = val;
        this.freq = freq;
        this.ts = ts;
    }

    @Override
    public int compareTo(FreqElement other) {
        if (this.freq != other.freq) {
            return Integer.compare(other.freq, this.freq);
        } else {
            return Integer.compare(other.ts, this.ts);
        }
    }
}

class FreqStack {

    private Map<Integer, Integer> freqMap;
    private Map<Integer, Integer> lastOccurrence;
    private int counter;
    private PriorityQueue<FreqElement> pq;

    public FreqStack() {
        freqMap = new HashMap<>();
        lastOccurrence = new HashMap<>();
        counter = 0;
        pq = new PriorityQueue<>();
    }

    public void push(int val) {
        counter++;
        int currentFreq = freqMap.getOrDefault(val, 0) + 1;
        freqMap.put(val, currentFreq);
        lastOccurrence.put(val, counter);
        pq.add(new FreqElement(val, currentFreq, counter));
    }

    public int pop() {
        while (!pq.isEmpty()) {
            FreqElement elem = pq.poll();
            int currentFreq = freqMap.getOrDefault(elem.val, 0);
            int lastTs = lastOccurrence.get(elem.val);
            if (currentFreq == elem.freq && lastTs == elem.ts) {
                freqMap.put(elem.val, currentFreq - 1);
                if (currentFreq - 1 == 0) {
                    freqMap.remove(elem.val);
                }
                return elem.val;
            }
        }
        return -1; // As per problem statement, this line should never be reached
    }
}

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.ArrayList;
import java.util.List;

class StockSpanner {

    private Deque<Integer> stack;
    private List<Integer> prices;

    public StockSpanner() {
        stack = new ArrayDeque<>();
        stack.push(-1);
        prices = new ArrayList<>();
    }

    public int next(int price) {
        int currentIdx = prices.size();
        prices.add(price);
        while (!stack.isEmpty() && stack.peek() != -1 && prices.get(stack.peek()) <= price) {
            stack.pop();
        }
        int span = currentIdx - stack.peek();
        stack.push(currentIdx);
        return span;
    }
}

