            if (y != 1) {
                while (true) {
                    long next = current * y;
                    if (next > bound - 1) {
                        break;
                    }
                    current = next;
                    yPowers.add((int) current);
                }
            }
        }

        Set<Integer> result = new HashSet<>();
        for (int a : xPowers) {
            for (int b : yPowers) {
                int sum = a + b;
                if (sum <= bound) {
                    result.add(sum);
                }
            }
        }

        return new ArrayList<>(result);
    }
