        vowels.add('e');
        vowels.add('i');
        vowels.add('o');
        vowels.add('u');

        int maxCount = 0;
        int currentCount = 0;

        // Initialize the count for the first window
        for (int i = 0; i < k; i++) {
            if (vowels.contains(s.charAt(i))) {
                currentCount++;
            }
