        Arrays.fill(secretTime, Integer.MAX_VALUE);
        secretTime[0] = 0;
        secretTime[firstPerson] = 0;

        Arrays.sort(meetings, (a, b) -> Integer.compare(a[2], b[2]));

        for (int[] meeting : meetings) {
            int x = meeting[0];
            int y = meeting[1];
            int t = meeting[2];
            if (secretTime[x] <= t || secretTime[y] <= t) {
                if (secretTime[x] > t) {
                    secretTime[x] = t;
                }
                if (secretTime[y] > t) {
                    secretTime[y] = t;
                }
            }
        }

        List<Integer> result = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            if (secretTime[i] != Integer.MAX_VALUE) {
                result.add(i);
            }
        }
        return result;
    }
}

import java.util.*;

class Solution {
    public int[][] validArrangement(int[][] pairs) {
        // Build the graph
        Map<Integer, Deque<Integer>> graph = new HashMap<>();
        for (int[] pair : pairs) {
            int a = pair[0];
            int b = pair[1];
            graph.computeIfAbsent(a, k -> new ArrayDeque<>()).add(b);
        }

        // Compute in-degree and out-degree
        Map<Integer, Integer> outDegree = new HashMap<>();
        Map<Integer, Integer> inDegree = new HashMap<>();
        for (int[] pair : pairs) {
            int a = pair[0];
            int b = pair[1];
            outDegree.put(a, outDegree.getOrDefault(a, 0) + 1);
            inDegree.put(b, inDegree.getOrDefault(b, 0) + 1);
        }

        // Find the starting node
        int startNode = -1;
        for (Map.Entry<Integer, Integer> entry : outDegree.entrySet()) {
            int key = entry.getKey();
            int out = entry.getValue();
            int in = inDegree.getOrDefault(key, 0);
            if (out - in == 1) {
                startNode = key;
                break;
            }
        }
        if (startNode == -1) {
            for (Map.Entry<Integer, Integer> entry : outDegree.entrySet()) {
                if (entry.getValue() > 0) {
                    startNode = entry.getKey();
                    break;
                }
            }
        }

        // Hierholzer's algorithm to find the Eulerian trail
        Stack<Integer> stack = new Stack<>();
        stack.push(startNode);
        List<Integer> circuit = new ArrayList<>();
        while (!stack.isEmpty()) {
            int current = stack.peek();
            Deque<Integer> nexts = graph.get(current);
            if (nexts != null && !nexts.isEmpty()) {
                int next = nexts.pollFirst();
                stack.push(next);
            } else {
                stack.pop();
                circuit.add(current);
            }
        }
        Collections.reverse(circuit);

        // Build the result
        List<int[]> result = new ArrayList<>();
        for (int i = 0; i < circuit.size() - 1; i++) {
            int a = circuit.get(i);
            int b = circuit.get(i + 1);
            result.add(new int[]{a, b});
        }

        // Convert to array
        int[][] res = new int[result.size()][2];
        for (int i = 0; i < res.length; i++) {
            res[i] = result.get(i);
        }
        return res;
    }
}

import java.util.*;

class Solution {
    private Map<Integer, Set<Integer>> startMap;

    public int wordCount(String[] startWords, String[] targetWords) {
        startMap = new HashMap<>();
        for (String start : startWords) {
            int len = start.length();
            int mask = computeMask(start);
            if (!startMap.containsKey(len)) {
                startMap.put(len, new HashSet<>());
            }
            startMap.get(len).add(mask);
        }

        int count = 0;
        for (String target : targetWords) {
            int targetLen = target.length();
            int requiredStartLen = targetLen - 1;
            if (requiredStartLen < 0) continue;
            if (!startMap.containsKey(requiredStartLen)) continue;

            int targetMask = computeMask(target);
            int k = Integer.bitCount(targetMask);
            if (k == 0) continue;

            for (int i = 0; i < 26; i++) {
                if ((targetMask & (1 << i)) != 0) {
                    int subsetMask = targetMask & ~(1 << i);
                    if (startMap.get(requiredStartLen).contains(subsetMask)) {
                        count++;
                        break;
                    }
                }
            }
        }
        return count;
    }

    private int computeMask(String s) {
        int mask = 0;
        for (char c : s.toCharArray()) {
            mask |= 1 << (c - 'a');
        }
        return mask;
    }
}

import java.util.Arrays;

class Solution {
    public long smallestNumber(long num) {
        if (num == 0) return 0;

        boolean isNegative = num < 0;
        long absNum = isNegative ? -num : num;

        String s = Long.toString(absNum);
        char[] digits = s.toCharArray();

        if (!isNegative) {
            Arrays.sort(digits);
            int firstNonZero = -1;
            for (int i = 0; i < digits.length; i++) {
                if (digits[i] != '0') {
                    firstNonZero = i;
                    break;
                }
            }
            if (firstNonZero != -1 && firstNonZero != 0) {
                char temp = digits[0];
                digits[0] = digits[firstNonZero];
                digits[firstNonZero] = temp;
            }
        } else {
            Arrays.sort(digits);
            int i = 0, j = digits.length - 1;
            while (i < j) {
                char temp = digits[i];
                digits[i] = digits[j];
                digits[j] = temp;
                i++;
                j--;
            }
        }

        String resultStr = new String(digits);
        long result = Long.parseLong(resultStr);

        return isNegative ? -result : result;
    }
}

import java.util.ArrayList;
import java.util.List;

class Solution {
    public List<Long> maximumEvenSplit(long finalSum) {
        List<Long> result = new ArrayList<>();
        if (finalSum % 2 != 0) {
            return result;
        }
        long S = finalSum;
        long k = 0;
        long low = 1;
        long high = S;

        // Binary search to find the maximum k where k*(k+1) <= S
        while (low <= high) {
            long mid = (low + high) / 2;
            long product = mid * (mid + 1);
            if (product <= S) {
                k = mid;
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }

        long R = S - k * (k + 1);
        if (R == 0) {
            for (int i = 1; i <= k; i++) {
                result.add(2L * i);
            }
        } else {
            if (R > 2 * k) {
                for (int i = 1; i <= k; i++) {
                    result.add(2L * i);
                }
                result.add(R);
            } else {
                for (int i = 1; i < k; i++) {
                    result.add(2L * i);
                }
                result.add(2L * k + R);
            }
        }
        return result;
    }
}

