import java.util.ArrayList;
import java.util.List;

class Solution {
    public int longestSubsequence(String s, int k) {
        List<Integer> zeros = new ArrayList<>();
        List<Integer> ones = new ArrayList<>();
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) == '0') {
                zeros.add(i);
            } else {
                ones.add(i);
            }
        }

        int n = s.length();
        for (int l = n; l >= 0; l--) {
            if (l == 0) {
                return 0;
            }
            long maxVal = Math.min(k, (1L << l) - 1);
            String target = Long.toBinaryString(maxVal);
            if (target.length() < l) {
                StringBuilder sb = new StringBuilder();
                for (int i = 0; i < l - target.length(); i++) {
                    sb.append('0');
                }
                sb.append(target);
                target = sb.toString();
            } else if (target.length() > l) {
                target = target.substring(target.length() - l);
            }
            if (canForm(target, zeros, ones)) {
                return l;
            }
        }
        return 0;
    }

    private boolean canForm(String target, List<Integer> zeros, List<Integer> ones) {
        int sPtr = 0;
        int targetPtr = 0;
        int m = target.length();
        while (targetPtr < m) {
            char c = target.charAt(targetPtr);
            List<Integer> list = (c == '0') ? zeros : ones;
            if (list.isEmpty()) {
                return false;
            }
            int left = 0;
            int right = list.size() - 1;
            int res = -1;
            while (left <= right) {
                int mid = (left + right) / 2;
                if (list.get(mid) >= sPtr) {
                    res = mid;
                    right = mid - 1;
                } else {
                    left = mid + 1;
                }
            }
            if (res == -1) {
                return false;
            }
            sPtr = list.get(res) + 1;
            targetPtr++;
        }
        return true;
    }
}

