import java.util.List;

class Solution {
    public List<Integer> beautifulIndices(String s, String a, String b, int k) {
        List<Integer> A = findOccurrences(s, a);
        List<Integer> B = findOccurrences(s, b);
        List<Integer> result = new ArrayList<>();

        for (int i : A) {
            int lower = i - k;
            int upper = i + k;
            int pos = Collections.binarySearch(B, lower);
            if (pos >= 0) {
                if (B.get(pos) <= upper) {
                    result.add(i);
                }
            } else {
                int insertionPoint = (-pos - 1);
                if (insertionPoint < B.size()) {
                    if (B.get(insertionPoint) <= upper) {
                        result.add(i);
                    }
                }
            }
        }

        return result;
    }

    private List<Integer> findOccurrences(String text, String pattern) {
        List<Integer> occurrences = new ArrayList<>();
        int[] lps = computeLPS(pattern.toCharArray());
        int m = pattern.length();
        int n = text.length();
        int i = 0;
        int j = 0;

        while (i < n) {
            if (text.charAt(i) == pattern.charAt(j)) {
                i++;
                j++;
                if (j == m) {
                    occurrences.add(i - j);
                    j = lps[j - 1];
                }
            } else {
                if (j != 0) {
                    j = lps[j - 1];
                } else {
                    i++;
                }
            }
        }
        return occurrences;
    }

    private int[] computeLPS(char[] pattern) {
        int m = pattern.length;
        int[] lps = new int[m];
        int length = 0;

        for (int i = 1; i < m; i++) {
            while (length > 0 && pattern[i] != pattern[length]) {
                length = lps[length - 1];
            }
            if (pattern[i] == pattern[length]) {
                length++;
                lps[i] = length;
            } else {
                lps[i] = 0;
            }
        }
        return lps;
    }
}

import java.util.ArrayList;
import java.util.List;

class Solution {
    private static final int MOD = 1000000007;

    public int possibleStringCount(String word, int k) {
        List<Integer> runs = computeRuns(word);
        int m = runs.size();
        int s = k - 1;

        if (m == 0) {
            return 0;
        }

        if (m > s) {
            long product = 1;
            for (int r : runs) {
                product = (product * r) % MOD;
            }
            return (int) product;
        } else {
            int[] dp = new int[s + 1];
            dp[0] = 1;

            for (int r : runs) {
                int[] next = new int[s + 1];
                int[] prefix = new int[s + 1];
                prefix[0] = dp[0];

                for (int i = 1; i <= s; i++) {
                    prefix[i] = (prefix[i - 1] + dp[i]) % MOD;
                }

                for (int j = 1; j <= s; j++) {
                    int max_x = Math.min(r, j);
                    int low = j - max_x;
                    if (low < 0) {
                        low = 0;
                    }
                    int sum = (prefix[j - 1] - (low > 0 ? prefix[low - 1] : 0)) % MOD;
                    next[j] = sum;
                }

                dp = next;
            }

            int numberOfTuples = dp[s];
            long product = 1;
            for (int r : runs) {
                product = (product * r) % MOD;
            }

            int answer = (int) ((product - numberOfTuples + MOD) % MOD);
            return answer;
        }
    }

    private List<Integer> computeRuns(String word) {
        List<Integer> runs = new ArrayList<>();
        if (word.isEmpty()) {
            return runs;
        }

        char current = word.charAt(0);
        int count = 1;

        for (int i = 1; i < word.length(); i++) {
            if (word.charAt(i) == current) {
                count++;
            } else {
                runs.add(count);
                current = word.charAt(i);
                count = 1;
            }
        }
        runs.add(count);
        return runs;
    }
}

