class Solution {
    private static final int MOD = 1000000007;
    private static final int SIZE = 26;

    public int lengthAfterTransformations(String s, int t, List<Integer> nums) {
        int[][] M = new int[SIZE][SIZE];
        for (int c = 0; c < SIZE; c++) {
            int k = nums.get(c);
            for (int i = 1; i <= k; i++) {
                int d = (c + i) % SIZE;
                M[c][d]++;
            }
        }

        int[][] M_power = matrixPower(M, t, MOD);

        int[] V0 = new int[SIZE];
        for (char ch : s.toCharArray()) {
            int idx = ch - 'a';
            V0[idx]++;
        }

        int[] V = multiplyVectorMatrix(V0, M_power, MOD);

        long sum = 0;
        for (int count : V) {
            sum = (sum + count) % MOD;
        }

        return (int) sum;
    }

    private static int[][] multiply(int[][] A, int[][] B, int MOD) {
        int[][] C = new int[SIZE][SIZE];
        for (int i = 0; i < SIZE; i++) {
            for (int j = 0; j < SIZE; j++) {
                long sum = 0;
                for (int k = 0; k < SIZE; k++) {
                    sum += (long) A[i][k] * B[k][j];
                    sum %= MOD;
                }
                C[i][j] = (int) sum;
            }
        }
        return C;
    }

    private static int[][] matrixPower(int[][] M, int power, int MOD) {
        int[][] result = new int[SIZE][SIZE];
        for (int i = 0; i < SIZE; i++) {
            result[i][i] = 1;
        }
        while (power > 0) {
            if (power % 2 == 1) {
                result = multiply(result, M, MOD);
            }
            M = multiply(M, M, MOD);
            power /= 2;
        }
        return result;
    }

    private static int[] multiplyVectorMatrix(int[] V, int[][] M, int MOD) {
        int[] result = new int[SIZE];
        for (int i = 0; i < SIZE; i++) {
            long sum = 0;
            for (int k = 0; k < SIZE; k++) {
                sum += (long) V[k] * M[k][i];
                sum %= MOD;
            }
            result[i] = (int) sum;
        }
        return result;
    }
}

import java.util.ArrayList;
import java.util.List;

class Solution {
    public int longestPalindrome(String s, String t) {
        List<String> sSubs = generateSubstrings(s);
        List<String> tSubs = generateSubstrings(t);

        int maxLen = 0;
        for (String sSub : sSubs) {
            for (String tSub : tSubs) {
                String concat = sSub + tSub;
                if (isPalindrome(concat)) {
                    int currentLen = concat.length();
                    if (currentLen > maxLen) {
                        maxLen = currentLen;
                    }
                }
            }
        }
        return maxLen;
    }

    private static List<String> generateSubstrings(String str) {
        List<String> substrings = new ArrayList<>();
        substrings.add("");
        for (int i = 0; i < str.length(); i++) {
            for (int j = i; j < str.length(); j++) {
                substrings.add(str.substring(i, j + 1));
            }
        }
        return substrings;
    }

    private static boolean isPalindrome(String s) {
        int left = 0;
        int right = s.length() - 1;
        while (left < right) {
            if (s.charAt(left) != s.charAt(right)) {
                return false;
            }
            left++;
            right--;
        }
        return true;
    }
}

import java.util.*;

class Solution {
    public int maxSubstrings(String word) {
        Map<Character, List<Integer>> map = new HashMap<>();
        for (int i = 0; i < word.length(); i++) {
            char c = word.charAt(i);
            if (!map.containsKey(c)) {
                map.put(c, new ArrayList<>());
            }
            map.get(c).add(i);
        }

        int count = 0;
        int n = word.length();
        int i = 0;
        while (i < n) {
            char c = word.charAt(i);
            List<Integer> list = map.get(c);
            if (list == null || list.isEmpty()) {
                i++;
                continue;
            }
            int target = i + 3;
            int left = 0;
            int right = list.size() - 1;
            int res = -1;
            while (left <= right) {
                int mid = (left + right) / 2;
                if (list.get(mid) >= target) {
                    res = mid;
                    right = mid - 1;
                } else {
                    left = mid + 1;
                }
            }
            if (res != -1) {
                int j = list.get(res);
                count++;
                i = j + 1;
            } else {
                i++;
            }
        }
        return count;
    }
}

import java.util.ArrayList;
