class Solution {
    public String resultingString(String s) {
        List<Character> stack = new ArrayList<>();
        for (char c : s.toCharArray()) {
            if (!stack.isEmpty()) {
                char top = stack.get(stack.size() - 1);
                if (isConsecutive(top, c)) {
                    stack.remove(stack.size() - 1);
                    continue;
                }
            }
            stack.add(c);
        }
        StringBuilder sb = new StringBuilder();
        for (char c : stack) {
            sb.append(c);
        }
        return sb.toString();
    }

    private boolean isConsecutive(char a, char b) {
        return (a == 'a' && b == 'z') || (a == 'z' && b == 'a') || Math.abs(a - b) == 1;
    }
}

import java.util.HashMap;
import java.util.Map;

public class Solution {
    private boolean[] isPrime = new boolean[100001];

    public Solution() {
        // Sieve of Eratosthenes to precompute primes up to 100,000
        java.util.Arrays.fill(isPrime, true);
        isPrime[0] = isPrime[1] = false;
        for (int i = 2; i * i <= 100000; i++) {
            if (isPrime[i]) {
                for (int j = i * i; j <= 100000; j += i) {
                    isPrime[j] = false;
                }
            }
        }
    }

    public int[] maximumCount(int[] nums, int[][] queries) {
        Map<Integer, Integer> primeFreq = new HashMap<>();
        for (int num : nums) {
            if (isPrime[num]) {
                primeFreq.put(num, primeFreq.getOrDefault(num, 0) + 1);
            }
        }

        int totalDistinct = primeFreq.size();
        int countMultiple = 0;
        for (int prime : primeFreq.keySet()) {
            if (primeFreq.get(prime) >= 2) {
                countMultiple++;
            }
        }

        int[] result = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            int idx = queries[i][0];
            int newVal = queries[i][1];
            int oldVal = nums[idx];

            // Process oldVal
            if (isPrime[oldVal]) {
                int freq = primeFreq.get(oldVal);
                if (freq == 2) {
                    countMultiple--;
                }
                primeFreq.put(oldVal, freq - 1);
                if (primeFreq.get(oldVal) == 0) {
                    primeFreq.remove(oldVal);
                    totalDistinct--;
                }
            }

            // Update the array
            nums[idx] = newVal;

            // Process newVal
            if (isPrime[newVal]) {
                if (!primeFreq.containsKey(newVal)) {
                    primeFreq.put(newVal, 1);
                    totalDistinct++;
                } else {
                    int oldFreq = primeFreq.get(newVal);
                    primeFreq.put(newVal, oldFreq + 1);
                    if (oldFreq == 1) {
                        countMultiple++;
                    }
                }
            }

            result[i] = totalDistinct + countMultiple;
        }
        return result;
    }
}

import java.util.*;

class Solution {
    public long maxGCDScore(int[] nums, int k) {
        Set<Integer> divisors = new HashSet<>();
        for (int x : nums) {
            divisors.addAll(getDivisors(x));
            divisors.addAll(getDivisors(2 * x));
        }
        List<Integer> dList = new ArrayList<>(divisors);
        Collections.sort(dList, Collections.reverseOrder());

        long maxScore = 0;
        for (int d : dList) {
            int[] cost = new int[nums.length];
            for (int i = 0; i < nums.length; i++) {
                int x = nums[i];
                if (x % d == 0) {
                    cost[i] = 0;
                } else if ((2 * x) % d == 0) {
                    cost[i] = 1;
                } else {
                    cost[i] = -1;
                }
            }
            int maxLen = 0;
            int currentSum = 0;
            int left = 0;
            for (int right = 0; right < cost.length; right++) {
                if (cost[right] == -1) {
                    left = right + 1;
                    currentSum = 0;
                    continue;
                }
                if (cost[right] == 1) {
                    currentSum++;
                }
                while (currentSum > k) {
                    if (cost[left] == 1) {
                        currentSum--;
                    }
                    left++;
                }
                int windowLen = right - left + 1;
                if (windowLen > maxLen) {
                    maxLen = windowLen;
                }
            }
            long score = (long) d * maxLen;
            if (score > maxScore) {
                maxScore = score;
            }
        }
        return maxScore;
    }

    private static Set<Integer> getDivisors(int n) {
        Set<Integer> divisors = new HashSet<>();
        for (int i = 1; i <= Math.sqrt(n); i++) {
            if (n % i == 0) {
                divisors.add(i);
                divisors.add(n / i);
            }
        }
        return divisors;
    }
}

import java.util.*;

class Solution {
    public double minTime(int n, int k, int m, int[] time, double[] mul) {
        if (k == 0) return -1.0;
        if (n == 0) return 0.0;

        PriorityQueue<State> pq = new PriorityQueue<>();
        int initialSubset = (1 << n) - 1;
        pq.add(new State(0.0, 0, initialSubset));

        double[][] visited = new double[1 << n][m];
        for (int i = 0; i < (1 << n); i++) {
            for (int j = 0; j < m; j++) {
                visited[i][j] = Double.POSITIVE_INFINITY;
            }
        }
        visited[initialSubset][0] = 0.0;

        while (!pq.isEmpty()) {
            State current = pq.poll();
            double currentTime = current.time;
            int currentStage = current.stage;
            int currentSubset = current.subset;

            if (currentSubset == 0) {
                return currentTime;
            }

            if (currentTime > visited[currentSubset][currentStage]) {
                continue;
            }

            List<Integer> available = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                if ((currentSubset & (1 << i)) != 0) {
                    available.add(i);
                }
            }

            int maxGroupSize = Math.min(k, available.size());
            for (int groupSize = 1; groupSize <= maxGroupSize; groupSize++) {
                List<List<Integer>> combinations = generateCombinations(available, groupSize);
                for (List<Integer> combination : combinations) {
                    int maxTime = 0;
                    for (int i : combination) {
                        if (time[i] > maxTime) {
                            maxTime = time[i];
                        }
                    }

                    double crossingTime = maxTime * mul[currentStage];
                    int newStage = (currentStage + (int) crossingTime) % m;

                    int groupMask = 0;
                    for (int i : combination) {
                        groupMask |= (1 << i);
                    }
                    int newSubset = currentSubset & (~groupMask);

                    if (newSubset == 0) {
                        if (crossingTime < visited[newSubset][newStage]) {
                            visited[newSubset][newStage] = crossingTime;
                            pq.add(new State(crossingTime, newStage, newSubset));
                        }
                    } else {
                        for (int r : combination) {
                            double returnTime = time[r] * mul[newStage];
                            int newNewStage = (newStage + (int) returnTime) % m;
                            int newNewSubset = newSubset | (1 << r);

                            double newTotalTime = crossingTime + returnTime;
                            if (newTotalTime < visited[newNewSubset][newNewStage]) {
                                visited[newNewSubset][newNewStage] = newTotalTime;
                                pq.add(new State(newTotalTime, newNewStage, newNewSubset));
                            }
                        }
                    }
                }
            }
        }

        return -1.0;
    }

    private List<List<Integer>> generateCombinations(List<Integer> list, int groupSize) {
        List<List<Integer>> result = new ArrayList<>();
        backtrack(list, groupSize, 0, new ArrayList<>(), result);
        return result;
    }

    private void backtrack(List<Integer> list, int groupSize, int start, List<Integer> current, List<List<Integer>> result) {
        if (current.size() == groupSize) {
            result.add(new ArrayList<>(current));
            return;
        }
        for (int i = start; i < list.size(); i++) {
            current.add(list.get(i));
            backtrack(list, groupSize, i + 1, current, result);
            current.remove(current.size() - 1);
        }
    }

    private static class State implements Comparable<State> {
        double time;
        int stage;
        int subset;

        State(double time, int stage, int subset) {
            this.time = time;
            this.stage = stage;
            this.subset = subset;
        }

        @Override
        public int compareTo(State other) {
            return Double.compare(this.time, other.time);
        }
    }
}

import java.util.HashSet;
import java.util.Set;

class Solution {
    public int minStable(int[] nums, int maxC) {
        if (maxC >= nums.length) {
            return 0;
        }
        Set<Integer> divisors = new HashSet<>();
        for (int num : nums) {
            if (num == 1) continue;
            for (int d = 2; d <= Math.sqrt(num); d++) {
                if (num % d == 0) {
                    divisors.add(d);
                    while (num % d == 0) {
                        num /= d;
                    }
                }
            }
            if (num > 1) {
                divisors.add(num);
            }
        }
        if (divisors.isEmpty()) {
            return 0;
        }
        int maxStable = 0;
        for (int d : divisors) {
            int left = 0, count = 0, maxLen = 0;
            for (int right = 0; right < nums.length; right++) {
                if (nums[right] % d != 0) {
                    count++;
                }
                while (count > maxC) {
                    if (nums[left] % d != 0) {
                        count--;
                    }
                    left++;
                }
                maxLen = Math.max(maxLen, right - left + 1);
            }
            maxStable = Math.max(maxStable, maxLen);
        }
        return maxStable == 0 ? 0 : maxStable;
    }
}

