from collections import deque

class Solution:
    def removeInvalidParentheses(self, s: str) -> List[str]:
        def is_valid(s):
            balance = 0
            for c in s:
                if c == '(':
                    balance += 1
                elif c == ')':
                    balance -= 1
                    if balance < 0:
                        return False
            return balance == 0

        queue = deque([s])
        visited = set()
        result = []

        while queue:
            level_size = len(queue)
            current_level = []
            for _ in range(level_size):
                current_str = queue.popleft()
                current_level.append(current_str)

            for s in current_level:
                if s in visited:
                    continue
                visited.add(s)
                if is_valid(s):
                    result.append(s)
                else:
                    for i in range(len(s)):
                        if s[i] in '()':
                            new_s = s[:i] + s[i+1:]
                            if new_s not in visited:
                                queue.append(new_s)

            if result:
                return result

        return result

