class KthLargest:

    def __init__(self, k: int, nums: List[int]):
        self.k = k
        nums_sorted = sorted(nums)
        top_elements = nums_sorted[-self.k:] if len(nums) >= self.k else nums_sorted
        heapq.heapify(top_elements)
        self.heap = top_elements

    def add(self, val: int) -> int:
        if len(self.heap) < self.k:
            heapq.heappush(self.heap, val)
        else:
            if val > self.heap[0]:
                heapq.heappop(self.heap)
                heapq.heappush(self.heap, val)
        return self.heap[0]

class MyLinkedList:
    class Node:
        def __init__(self, val=0, next=None):
            self.val = val
            self.next = next

    def __init__(self):
        self.head = None
        self.size = 0

    def get(self, index: int) -> int:
        if index < 0 or index >= self.size:
            return -1
        current = self.head
        for _ in range(index):
            current = current.next
        return current.val

    def addAtHead(self, val: int) -> None:
        new_node = self.Node(val)
        new_node.next = self.head
        self.head = new_node
        self.size += 1

    def addAtTail(self, val: int) -> None:
        new_node = self.Node(val)
        if not self.head:
            self.head = new_node
        else:
            current = self.head
            while current.next:
                current = current.next
            current.next = new_node
        self.size += 1

    def addAtIndex(self, index: int, val: int) -> None:
        if index < 0 or index > self.size:
            return
        if index == 0:
            self.addAtHead(val)
        elif index == self.size:
            self.addAtTail(val)
        else:
            new_node = self.Node(val)
            current = self.head
            for _ in range(index - 1):
                current = current.next
            new_node.next = current.next
            current.next = new_node
            self.size += 1

    def deleteAtIndex(self, index: int) -> None:
        if index < 0 or index >= self.size:
            return
        if index == 0:
            self.head = self.head.next
        else:
            current = self.head
            for _ in range(index - 1):
                current = current.next
            current.next = current.next.next
        self.size -= 1

class RangeModule:

    def __init__(self):
        self.intervals = []

    def addRange(self, left: int, right: int) -> None:
        if left >= right:
            return
        new_intervals = []
        to_merge = []
        for interval in self.intervals:
            if interval[0] <= right and interval[1] >= left:
                to_merge.append(interval)
            else:
                new_intervals.append(interval)
        if to_merge:
            new_start = min(i[0] for i in to_merge)
            new_end = max(i[1] for i in to_merge)
            new_interval = (new_start, new_end)
            new_intervals.append(new_interval)
        else:
            new_intervals.append((left, right))
        self.intervals = new_intervals
        self.intervals.sort()

    def queryRange(self, left: int, right: int) -> bool:
        if left >= right:
            return True
        if not self.intervals:
            return False
        current = left
        for interval in self.intervals:
            if current >= right:
                return True
            if interval[0] > current:
                return False
            current = max(current, interval[1])
        return current >= right

    def removeRange(self, left: int, right: int) -> None:
        if left >= right:
            return
        new_intervals = []
        for interval in self.intervals:
            if interval[1] <= left or interval[0] >= right:
                new_intervals.append(interval)
            else:
                if interval[0] < left:
                    new_intervals.append((interval[0], left))
                if right < interval[1]:
                    new_intervals.append((right, interval[1]))
        self.intervals = new_intervals

