class Solution:
    def splitIntoFibonacci(self, num: str) -> List[int]:
        max_num = 2 ** 31 - 1
        n = len(num)
        for i in range(1, n):
            if i > n - 2:
                break
            f1_str = num[:i]
            if len(f1_str) > 1 and f1_str[0] == '0':
                continue
            if int(f1_str) > max_num:
                continue
            for j in range(i + 1, n):
