MOD = 10**9 + 7

class Solution:
    def distinctSequences(self, n: int) -> int:
        if n == 0:
            return 0
        if n == 1:
            return 6 % MOD

        # Initialize for i = 2
        current = [[0] * 6 for _ in range(6)]
        for a in range(6):
            for b in range(6):
                if a != b and math.gcd(a + 1, b + 1) == 1:
                    current[a][b] = 1

        if n == 2:
            total = sum(sum(row) for row in current)
            return total % MOD

        for i in range(3, n + 1):
            next_state = [[0] * 6 for _ in range(6)]
            for a in range(6):
                for b in range(6):
                    if current[a][b] == 0:
                        continue
                    for c in range(6):
                        if math.gcd(b + 1, c + 1) == 1 and (c + 1) != (a + 1):
                            next_state[b][c] = (next_state[b][c] + current[a][b]) % MOD
            current = next_state

        total = sum(sum(row) for row in current)
        return total % MOD

