class Solution:
    def countNumbers(self, l: str, r: str, b: int) -> int:
        MOD = 10**9 + 7

        def subtract_one(s, base):
            if s == "0":
                return "-1"
            digits = list(map(int, s))
            i = len(digits) - 1
            while i >= 0 and digits[i] == 0:
                digits[i] = base - 1
                i -= 1
            if i >= 0:
                digits[i] -= 1
            if digits[0] == 0 and len(digits) > 1:
                digits = digits[1:]
            return ''.join(map(str, digits)) if digits else "0"

        def count(s):
            digits = list(map(int, s))
            n = len(digits)

            from functools import lru_cache

            @lru_cache(maxsize=None)
            def dp(pos, prev, tight, leading_zero):
                if pos == n:
                    return 1
                res = 0
                max_d = digits[pos] if tight else (b - 1)
                for d in range(0, max_d + 1):
                    new_tight = tight and (d == max_d)
                    new_leading = leading_zero and (d == 0)
                    if leading_zero:
                        if d == 0:
                            res += dp(pos + 1, prev, new_tight, new_leading)
                        else:
                            res += dp(pos + 1, d, new_tight, False)
                    else:
                        if d >= prev:
                            res += dp(pos + 1, d, new_tight, False)
                return res

            return dp(0, -1, True, True) % MOD

        r_count = count(r)
        l_minus_1 = subtract_one(l, b)
        if l_minus_1 == "-1":
            l_count = 0
        else:
            l_count = count(l_minus_1)

        return (r_count - l_count) % MOD

class Solution:
    def maximumCount(self, nums: List[int], queries: List[List[int]]) -> List[int]:
        # Precompute primes up to 1e5 using sieve
        max_num = 10**5
        is_prime = [True] * (max_num + 1)
        is_prime[0] = is_prime[1] = False
        for i in range(2, int(max_num**0.5) + 1):
            if is_prime[i]:
                for j in range(i*i, max_num+1, i):
                    is_prime[j] = False

        res = []
        n = len(nums)
        for query in queries:
            idx, val = query
            nums[idx] = val

            # Compute prefix counts
            prefix = [0] * n
            primes_seen = set()
            for i in range(n):
                if is_prime[nums[i]]:
                    primes_seen.add(nums[i])
                prefix[i] = len(primes_seen)

            # Compute suffix counts
            suffix = [0] * n
            primes_seen = set()
            for i in range(n-1, -1, -1):
                if is_prime[nums[i]]:
                    primes_seen.add(nums[i])
                suffix[i] = len(primes_seen)

            # Find maximum sum of prefix[k-1] + suffix[k]
            max_sum = 0
            for k in range(1, n):
                current = prefix[k-1] + suffix[k]
                if current > max_sum:
                    max_sum = current
            res.append(max_sum)
        return res

