class Solution:
    def numberOfStableArrays(self, zero: int, one: int, limit: int) -> int:
        MOD = 10**9 + 7
        from functools import lru_cache

        @lru_cache(maxsize=None)
        def dp(z, o, last, run):
            if z == 0 and o == 0:
                return 1
            total = 0
            # Try adding 0
            if z > 0:
                if last == 0:
                    if run + 1 <= limit:
                        total += dp(z - 1, o, 0, run + 1)
                else:
                    total += dp(z - 1, o, 0, 1)
            # Try adding 1
            if o > 0:
                if last == 1:
                    if run + 1 <= limit:
                        total += dp(z, o - 1, 1, run + 1)
                else:
                    total += dp(z, o - 1, 1, 1)
            return total % MOD

        res = 0
        if zero > 0:
            res += dp(zero - 1, one, 0, 1)
        if one > 0:
            res += dp(zero, one - 1, 1, 1)
        return res % MOD

