    }
    bool isKPalindrome(string s, int k) {
        int left = 0;
        int right = s.size() - 1;
        while (left < right) {
            if (s[left] != s[right]) {
                return false;
            }
            left++;
            right--;
        }
        return (s % k == 0);
    }
};

class LRUCache {
    private Map<Integer, Integer> cache;
    private int capacity;
    private Deque<Integer> keyOrder;

    public LRUCache(int capacity) {
        this.capacity = capacity;
        cache = new HashMap<>();
        keyOrder = new LinkedList<>();
    }

    public int get(int key) {
        if (!cache.containsKey(key)) {
            return -1;
        }
        keyOrder.remove(Integer.valueOf(key));
        keyOrder.addFirst(key);
        return cache.get(key);
    }

    public void put(int key, int value) {
        if (cache.containsKey(key)) {
            cache.put(key, value);
            keyOrder.remove(Integer.valueOf(key));
            keyOrder.addFirst(key);
        } else {
            if (cache.size() == capacity) {
                int evictKey = keyOrder.removeLast();
                cache.remove(evictKey);
            }
            cache.put(key, value);
            keyOrder.addFirst(key);
        }
    }
}

