class Solution {
    public int peopleAwareOfSecret(int n, int delay, int forget) {
        long mod = 1000000007;
        long[] dp = new long[n + 1];
        dp[0] = 1;
        for (int i = 1; i <= n; i++) {
            dp[i] = dp[i - 1];
            if (i >= delay && i % forget != 0 && i - delay >= 0) {
                dp[i] = (dp[i] + dp[i - delay]) % mod;
            }
        }
        return (int) dp[n];
    }
}

class Solution {
    public boolean canChange(String start, String target) {
        if (start.length() != target.length()) {
            return false;
        }
        int left = 0;
        int right = start.length() - 1;
        while (left <= right) {
            if (start.charAt(left) == 'L' && target.charAt(left) == 'L' && start.charAt(left) != '_') {
                if (left > 0 && start.charAt(left - 1) == '_') {
                    left++;
                } else {
                    return false;
                }
            } else if (start.charAt(right) == 'R' && target.charAt(right) == 'R' && start.charAt(right) != '_') {
                if (right < start.length() - 1 && start.charAt(right + 1) == '_') {
                    right--;
                } else {
                    return false;
                }
            } else {
                left++;
                right--;
            }
        }
        return true;
    }
}

class Solution {
    public int countGoodStrings(int low, int high, int zero, int one) {
        long mod = 1000000007;
        long dp[][] = new long[high + 1][zero + 1];
        dp[0][0] = 1;
        for (int i = 1; i <= high; i++) {
            for (int j = 0; j <= zero; j++) {
                dp[i][j] = dp[i - 1][j];
                if (j > 0) {
                    dp[i][j] = (dp[i][j] + dp[i - 1][j - 1]) % mod;
                }
                if (i >= zero) {
                    dp[i][j] = (dp[i][j] + dp[i - zero][j]) % mod;
                }
            }
        }
        return (int) (dp[high][zero] - dp[low - 1][zero]);
    }
}

