class LFUCache:

    def __init__(self, capacity: int):
        self.capacity = capacity
        self.cache = {}
        self.freq_map = {}
        self.min_freq = 0

    def get(self, key: int) -> int:
        if key not in self.cache:
            return -1
        self.cache[key][0] += 1
        self.update_freq(key)
        return self.cache[key][1]

    def put(self, key: int, value: int) -> None:
        if key in self.cache:
            self.cache[key][0] += 1
            self.cache[key][1] = value
            self.update_freq(key)
        else:
            if len(self.cache) == self.capacity:
                lru_key = self.get_lru()
                del self.cache[lru_key]
                del self.freq_map[lru_key]
            self.cache[key] = [1, value]
            self.freq_map[key] = 1
            self.min_freq = 1

    def update_freq(self, key):
        freq = self.cache[key][0]
        if freq not in self.freq_map:
            self.freq_map[freq] = []
        self.freq_map[freq].append(key)
        if freq > self.min_freq:
            self.min_freq = freq

    def get_lru(self):
        return self.freq_map[self.min_freq][0]

class Solution:
    def canIWin(self, maxChoosableInteger: int, desiredTotal: int) -> bool:
        total = sum(range(1, maxChoosableInteger + 1))
        if desiredTotal <= total // 2:
            return True
        return self.dfs(set(range(1, maxChoosableInteger + 1)), desiredTotal, 0)

    def dfs(self, nums, target, current_sum):
        if target <= 0:
            return True
        if current_sum >= target:
            return False
        for num in nums:
            nums.remove(num)
            if not self.dfs(nums, target - num, current_sum + num):
                return True
            nums.add(num)
        return False

class Solution:
    def getMaxRepetitions(self, s1: str, n1: int, s2: str, n2: int) -> int:
        if not s1 or not s2 or n1 == 0 or n2 == 0:
            return 0
        j = 0
        count = 0
        repeatCount = [0] * (len(s1) + 1)
        nextIndex = [0] * (len(s1) + 1)
        for k in range(1, n1 + 1):
            for i in range(len(s1)):
                if s1[i] == s2[j]:
                    j += 1
                    if j == len(s2):
                        count += 1
                        j = 0
            repeatCount[k] = count
            nextIndex[k] = j
            for start in range(k):
                if nextIndex[start] == j:
                    prefixCount = repeatCount[start]
                    patternCount = (repeatCount[k] - repeatCount[start]) * ((n1 - start) // (k - start))
                    suffixCount = repeatCount[start + (n1 - start) % (k - start)] - repeatCount[start]
                    return (prefixCount + patternCount + suffixCount) // n2
        return repeatCount[n1] // n2

