class Solution:
    def minimumDeleteSum(self, s1: str, s2: str) -> int:
        n = len(s1)
        m = len(s2)
        dp = [[0 for _ in range(m + 1)] for _ in range(n + 1)]
        for i in range(n + 1):
            dp[i][0] = i * ord(s1[i - 1]) if i > 0 else 0
        for j in range(m + 1):
            dp[0][j] = j * ord(s2[j - 1]) if j > 0 else 0
        for i in range(1, n + 1):
            for j in range(1, m + 1):
                if s1[i - 1] == s2[j - 1]:
                    dp[i][j] = dp[i - 1][j - 1]
                else:
                    dp[i][j] = min(dp[i - 1][j] + ord(s1[i - 1]), dp[i][j - 1] + ord(s2[j - 1]))
        return dp[n][m]

class RangeModule:

    def __init__(self):
        self.ranges = []

    def addRange(self, left: int, right: int) -> None:
        i = 0
        while i < len(self.ranges) and self.ranges[i][1] <= left:
            i += 1
        if i == len(self.ranges) or self.ranges[i][0] > right:
            self.ranges.insert(i, [left, right])
        else:
            self.ranges[i][1] = max(self.ranges[i][1], right)

    def queryRange(self, left: int, right: int) -> bool:
        for start, end in self.ranges:
            if start < right and left < end:
                return True
        return False

    def removeRange(self, left: int, right: int) -> None:
        i = 0
        while i < len(self.ranges):
            start, end = self.ranges[i]
            if start < right and left < end:
                if start < left:
                    self.ranges[i][0] = max(self.ranges[i][0], left)
                if end > right:
                    self.ranges[i][1] = min(self.ranges[i][1], right)
                if self.ranges[i][0] == self.ranges[i][1]:
                    self.ranges.pop(i)
                else:
                    i += 1
            else:
                i += 1

class Solution:
    def countOfAtoms(self, formula: str) -> str:
        stack = []
        curr_atom = {}
        for i in range(len(formula)):
            if formula[i].isalpha():
                atom = formula[i]
                if i + 1 < len(formula) and formula[i + 1].isdigit():
                    j = i + 1
                    while j < len(formula) and formula[j].isdigit():
                        j += 1
                    atom += formula[i + 1:j]
                    i = j - 1
                if atom in curr_atom:
                    curr_atom[atom] += 1
                else:
                    curr_atom[atom] = 1
            elif formula[i] == '(':
                stack.append(curr_atom)
                curr_atom = {}
            elif formula[i] == ')':
                prev_atom = stack.pop()
                for atom, count in curr_atom.items():
                    if atom in prev_atom:
                        prev_atom[atom] += count
                    else:
                        prev_atom[atom] = count
                curr_atom = prev_atom
        result = []
        for atom, count in curr_atom.items():
            if count > 1:
                result.append(f"{atom}{count}")
            else:
                result.append(atom)
        return ''.join(sorted(result))

