class Solution:
    def possibleBipartition(self, n: int, dislikes: List[List[int]]) -> bool:
        graph = [[] for _ in range(n + 1)]
        for a, b in dislikes:
            graph[a].append(b)
            graph[b].append(a)
        colors = [0] * (n + 1)
        for i in range(1, n + 1):
            if colors[i] == 0:
                if not self.dfs(graph, colors, i, 1):
                    return False
        return True

    def dfs(self, graph, colors, node, color):
        colors[node] = color
        for neighbor in graph[node]:
            if colors[neighbor] == color:
                return False
            if colors[neighbor] == 0 and not self.dfs(graph, colors, neighbor, -color):
                return False
        return True

class FreqStack:

    def __init__(self):
        self.stack = []
        self.freq = {}

    def push(self, val: int) -> None:
        if val not in self.freq:
            self.freq[val] = 0
        self.freq[val] += 1
        self.stack.append((val, self.freq[val]))

    def pop(self) -> int:
        max_freq = max(self.freq.values())
        res = None
        for val, freq in self.stack:
            if freq == max_freq:
                res = val
                break
        self.stack.remove((res, max_freq))
        self.freq[res] -= 1
        return res

