            if '(' not in num:
                return float(num)
            int_part, decimal_part = num.split('.')
            non_repeating, repeating = decimal_part.split('(')
            repeating = repeating[:-1]
            return float(int_part + '.' + non_repeating + repeating * 10)
        return abs(to_decimal(s) - to_decimal(t)) < 1e-6

