class CombinationIterator:

    def __init__(self, characters: str, combinationLength: int):
        self.chars = characters
        self.length = len(characters)
        self.combinationLength = combinationLength
        self.combinations = []
        self.generate_combinations()

    def next(self) -> str:
        combination = self.combinations.pop(0)
        return combination

    def hasNext(self) -> bool:
        return len(self.combinations) > 0

    def generate_combinations(self):
        if self.combinationLength == 1:
            for i in range(self.length):
                self.combinations.append(self.chars[i])
            return

        for i in range(self.length - self.combinationLength + 1):
            substring = self.chars[i:i + self.combinationLength]
            self.combinations.append(substring)
            self.generate_combinations_recursive(substring, i + 1)

    def generate_combinations_recursive(self, current_combination, start_index):
        for i in range(start_index, self.length - self.combinationLength + 1):
            new_combination = current_combination + self.chars[i]
            self.combinations.append(new_combination)
            self.generate_combinations_recursive(new_combination, i + 1)

