            graph[y].append(x)
        visited = [False] * n
        queue = [firstPerson]
        visited[firstPerson] = True
        while queue:
            person = queue.pop(0)
            for neighbor in graph[person]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    queue.append(neighbor)
        return [i for i, v in enumerate(visited) if v]

