        n = len(s)
        dp = [[float('inf')] * (k + 1) for _ in range(n + 1)]
        dp[0][0] = 0
        for i in range(1, n + 1):
            for j in range(1, min(i, k) + 1):
                for l in range(i):
                    left_changes = 0
                    for m in range(l, i, j):
                        if s[m - 1] != s[m]:
                            left_changes += 1
                    right_changes = 0
                    for m in range(l + j, i, j):
                        if s[m - 1] != s[m]:
