        def backtrack(index, current):
            if index == len(word):
                return current
            for i in range(index + 1, len(word) + 1, numFriends):
                current += word[index:i]
                result = backtrack(i, current)
                if result:
                    return result
                current = current[:-len(word[index:i])]
            return None
        return backtrack(0, "")

