        result = []
        for query in queries:
            idx, val = query
            nums[idx] = val
            prefix_sum = 0
            distinct_primes_prefix = set()
            for i in range(len(nums)):
                if nums[i] > 1:
                    is_prime = True
                    for j in range(2, int(nums[i]**0.5) + 1):
                        if nums[i] % j == 0:
