            for j in range(1, min(i, k) + 1):
                for l in range(i):
                    if s[l:i] == s[l:i][::-1] and dp[l][j - 1] != float('inf'):
                        dp[i][j] = min(dp[i][j], dp[l][j - 1])
                dp[i][j] = min(dp[i][j], dp[i - 1][j] + 1)
        return dp[n][k]

class Solution:
    def subtractProductAndSum(self, n: int) -> int:
        product = 1
        sum = 0
        for digit in str(n):
            product *= int(digit)
            sum += int(digit)
        return product - sum

class Solution:
    def numberOfSubstrings(self, s: str) -> int:
        count = 0
        for i in range(len(s)):
            for j in range(i, len(s)):
                if 'a' in s[i:j+1] and 'b' in s[i:j+1] and 'c' in s[i:j+1]:
                    count += 1
        return count

class Solution:
    def countLargestGroup(self, n: int) -> int:
        groups = [0] * (10)
        for i in range(1, n + 1):
            groups[sum(int(digit) for digit in str(i))] += 1
        return max(groups)

class Solution:
    def maxScore(self, s: str) -> int:
        max_score = 0
        left_zeros = 0
        for i in range(len(s)):
            left_zeros += int(s[i] == '0')
            right_ones = sum(int(c == '1') for c in s[i + 1:])
            max_score = max(max_score, left_zeros + right_ones)
        return max_score

class Solution:
    def canBeEqual(self, target: List[int], arr: List[int]) -> bool:
        return sorted(target) == sorted(arr)

class Solution:
    def findMaxK(self, nums: List[int]) -> int:
        nums_set = set(nums)
        max_k = -1
        for num in nums_set:
            if -num in nums_set and abs(num) > max_k:
                max_k = abs(num)
        return max_k

class Solution:
    def bestClosingTime(self, customers: str) -> int:
        n = len(customers)
        min_penalty = float('inf')
        best_time = 0
        for i in range(n):
            penalty = 0
            for j in range(i + 1):
                if customers[j] == 'Y' and j >= i:
                    penalty += 1
            for j in range(i + 1, n):
                if customers[j] == 'N':
                    penalty += 1
            if penalty < min_penalty:
                min_penalty = penalty
                best_time = i
        return best_time

class Solution:
    def distanceTraveled(self, mainTank: int, additionalTank: int) -> int:
        distance = 0
        while mainTank > 0 or additionalTank >= 1:
            if mainTank > 0:
                mainTank -= 5
                distance += 50
            if additionalTank >= 1 and mainTank < 0:
                mainTank += 1
                additionalTank -= 1
        return distance

class Solution {
public:
    int minSteps(int n) {
        int steps = 0, copied = 1;
        while (copied < n) {
            steps++;
            copied += copied;
        }
        return steps + 1;
    }
};

