class Solution:
    def removeInvalidParentheses(self, s: str) -> List[str]:
        def is_valid(s):
            cnt = 0
            for c in s:
                if c == '(': cnt += 1
                elif c == ')': cnt -= 1
                if cnt < 0: return False
            return cnt == 0

        queue = deque([s])
        visited = set([s])
        found = False
        res = []
        while queue:
            cur = queue.popleft()
            if is_valid(cur):
                found = True
                res.append(cur)
            elif not found:
                for i in range(len(cur)):
                    if cur[i] in ['(', ')']:
                        next_s = cur[:i] + cur[i+1:]
                        if next_s not in visited:
                            queue.append(next_s)
                            visited.add(next_s)
        return res

