class Solution:
    def racecar(self, target: int) -> int:
        queue = deque([(0, 1, 0)])
        visited = set((0, 1))
        while queue:
            pos, speed, steps = queue.popleft()
            if pos == target:
                return steps
            if pos > target:
                queue.append((pos, -1, steps + 1))
                visited.add((pos, -1))
