class Solution:
    def strongPasswordChecker(self, password: str) -> int:
        missing_type = 3
        if any('a' <= c <= 'z' for c in password): missing_type -= 1
        if any('A' <= c <= 'Z' for c in password): missing_type -= 1
        if any(c.isdigit() for c in password): missing_type -= 1

        one = two = p = i = 0
        n = len(password)
        while i < n:
            length = 1
            while i + 1 < n and password[i] == password[i+1]:
                i += 1
                length += 1
            if length >= 3:
                one += length // 3
                if length % 3 == 0: one -= 1
                two += length // 3
            i += 1

        if n < 6:
            return max(6 - n, missing_type)
        elif n <= 20:
            return max(missing_type, one)
        else:
            delete = n - 20
            one -= min(delete, p)
            return delete + max(missing_type, one)

class AllOne:

    def __init__(self):
        self.d = {}
        self.max_heap = []
        self.min_heap = []

    def inc(self, key: str) -> None:
        if key not in self.d:
            self.d[key] = 1
            self.min_heap.append((1, key))
            self.max_heap.append((-1, key))
        else:
            self.d[key] += 1
            self.max_heap.append((-self.d[key], key))
            self.min_heap.append((self.d[key], key))

    def dec(self, key: str) -> None:
        self.d[key] -= 1
        if self.d[key] == 0:
            del self.d[key]

    def getMaxKey(self) -> str:
        while self.max_heap and -self.max_heap[0][0] not in [self.d[key] for key in self.d]:
            heapq.heappop(self.max_heap)
        return self.max_heap[0][1] if self.max_heap else ""

    def getMinKey(self) -> str:
        while self.min_heap and self.min_heap[0][0] not in [self.d[key] for key in self.d]:
            heapq.heappop(self.min_heap)
        return self.min_heap[0][1] if self.min_heap else ""

class Solution:
    def findKthNumber(self, n: int, k: int) -> int:
        def count_digits(cur, n):
            step = 0
            while cur <= n:
                step += min(n + 1, cur * 10) - cur
                cur *= 10
            return step

        cur = 1
        k -= 1
        while k > 0:
            step = count_digits(cur, n)
            if k >= step:
                k -= step
                cur += 1
            else:
                k -= 1
                cur *= 10
        return cur

class Solution:
    def compress(self, chars: List[str]) -> int:
        if len(chars) == 1:
            return 1
        write = anchor = 0
        for read, c in enumerate(chars):
            if read + 1 == len(chars) or chars[read + 1] != c:
                chars[write] = chars[anchor]
                write += 1
                if read > anchor:
                    for digit in str(read - anchor + 1):
                        chars[write] = digit
                        write += 1
                anchor = read + 1
        return write

