class Solution:
    def canIWin(self, maxChoosableInteger: int, desiredTotal: int) -> bool:
        if (maxChoosableInteger * (maxChoosableInteger + 1)) // 2 < desiredTotal:
            return False
        self.memo = {}
        return self.dfs(tuple(range(1, maxChoosableInteger + 1)), desiredTotal)

    def dfs(self, nums, target):
        if nums[-1] >= target:
            return True
        if (nums, target) in self.memo:
            return self.memo[(nums, target)]
        for i in range(len(nums)):
            if not self.dfs(nums[:i] + nums[i + 1:], target - nums[i]):
                self.memo[(nums, target)] = True
                return True
        self.memo[(nums, target)] = False
        return False

class Solution:
    def getMaxRepetitions(self, s1: str, n1: int, s2: str, n2: int) -> int:
        def get_next_index(s1, s2, index):
            next_index = index
            for char in s2:
                found = False
                while next_index < len(s1):
                    if s1[next_index] == char:
                        found = True
                        next_index += 1
                        break
                    next_index += 1
                if not found:
                    return -1
            return next_index

        max_repetitions = 0
        index = 0
        for _ in range(n1):
            next_index = get_next_index(s1 * n1, s2, index)
            if next_index == -1:
                break
            index = next_index
            max_repetitions += 1
        return max_repetitions // n2

