        if index < 0 or index > self.size:
            return
        if index == 0:
            self.addAtHead(val)
        elif index == self.size:
            self.addAtTail(val)
        else:
            node = ListNode(val)
            current = self.head
            for _ in range(index - 1):
                current = current.next
            node.next = current.next
            current.next = node
            self.size += 1

