class RangeModule:

    def __init__(self):
        self.ranges = []

    def addRange(self, left: int, right: int) -> None:
        new_ranges = []
        i = 0
        while i < len(self.ranges) and self.ranges[i][1] <= left:
            new_ranges.append(self.ranges[i])
            i += 1
        while i < len(self.ranges) and self.ranges[i][0] <= right:
            left = min(left, self.ranges[i][0])
            right = max(right, self.ranges[i][1])
            i += 1
        new_ranges.append([left, right])
        while i < len(self.ranges):
            new_ranges.append(self.ranges[i])
            i += 1
        self.ranges = new_ranges

    def queryRange(self, left: int, right: int) -> bool:
        for l, r in self.ranges:
            if l <= left and right <= r:
                return True
        return False

    def removeRange(self, left: int, right: int) -> None:
        new_ranges = []
        for l, r in self.ranges:
            if r <= left or l >= right:
                new_ranges.append([l, r])
            else:
                if l < left:
                    new_ranges.append([l, left])
                if r > right:
                    new_ranges.append([right, r])
        self.ranges = new_ranges

class Solution:
    def countOfAtoms(self, formula: str) -> str:
        i, n = 0, len(formula)
        stack = [{}]
        while i < n:
            if formula[i] == '(':
                stack.append({})
                i += 1
            elif formula[i] == ')':
                top = stack.pop()
                i += 1
                start = i
                while i < n and formula[i].isdigit():
                    i += 1
                multiplier = int(formula[start:i] or 1)
                for name, count in top.items():
                    stack[-1][name] = stack[-1].get(name, 0) + count * multiplier
            else:
                start = i
                i += 1
                while i < n and formula[i].islower():
                    i += 1
                name = formula[start:i]
                start = i
                while i < n and formula[i].isdigit():
                    i += 1
                count = int(formula[start:i] or 1)
                stack[-1][name] = stack[-1].get(name, 0) + count
        result = []
        for name in sorted(stack[-1]):
            result.append(name)
            if stack[-1][name] > 1:
                result.append(str(stack[-1][name]))
        return ''.join(result)

