class Solution:
    def crackSafe(self, n: int, k: int) -> str:
        result = "0" * n
        visited = set()
        for _ in range(k ** n):
            prefix = result[-(n - 1):]
            for i in range(k - 1, -1, -1):
                combination = prefix + str(i)
                if combination not in visited:
                    visited.add(combination)
                    result += str(i)
                    break
        return result

class Solution:
    def reachNumber(self, target: int) -> int:
        target = abs(target)
        low, high = 1, target
        res = 0
        while low <= high:
            mid = (low + high) // 2
            total = mid * (mid + 1) // 2
            if total >= target and (total - target) % 2 == 0:
                res = mid
                break
            elif total < target:
                low = mid + 1
            else:
                high = mid - 1
        return res

