class Solution:
    def distinctSequences(self, n: int) -> int:
        MOD = 10**9 + 7
        @lru_cache(None)
        def dp(i, prev, prev_prev):
            if i == n:
                return 1
            res = 0
            for x in range(1, 7):
                if (x != prev or i - prev > 2) and (x != prev_prev or i - prev_prev > 2) and math.gcd(x, prev) == 1:
                    res += dp(i + 1, x, prev)
            return res % MOD
        return dp(0, -1, -1)

class Solution:
    def peopleAwareOfSecret(self, n: int, delay: int, forget: int) -> int:
        MOD = 10**9 + 7
        dp = [0] * (n + 1)
        dp[1] = 1
        share = [0] * (n + 1)
        for i in range(1, n + 1):
            if i >= delay:
                share[i] = (share[i] + dp[i - delay]) % MOD
            if i > forget:
                share[i] = (share[i] - dp[i - forget]) % MOD
            dp[i] = (dp[i] + share[i]) % MOD
        return sum(dp[max(n - forget + 1, 1): n + 1]) % MOD

