class Solution:
    def minimumScore(self, s: str, t: str) -> int:
        m, n = len(s), len(t)
        dp = [[0] * (n + 1) for _ in range(m + 1)]

        for i in range(m + 1):
            for j in range(n + 1):
                if i == 0:
                    dp[i][j] = j
                elif j == 0:
                    dp[i][j] = 0
                elif s[i - 1] == t[j - 1]:
                    dp[i][j] = dp[i - 1][j - 1]
                else:
                    dp[i][j] = min(dp[i - 1][j] + 1, dp[i][j - 1] + 1)

        return dp[m][n]

class Solution:
    def repairCars(self, ranks: List[int], cars: int) -> int:
        def possible(time):
            return sum((time // (r * n**2)) for r, n in [(r, int((time / (r * n**2)) ** 0.5)) for r in ranks])

        low, high = 0, 10**14
        while low < high:
            mid = (low + high) // 2
            if possible(mid) >= cars:
                high = mid
            else:
                low = mid + 1
        return low

class Solution:
    def addMinimum(self, word: str) -> int:
        stack = []
        count = 0
        for char in word:
            if char == 'a':
                stack.append(char)
            elif char == 'b':
                if stack and stack[-1] == 'a':
                    stack.pop()
                    stack.append('ab')
                else:
                    count += 1
                    stack.append('ab')
            elif char == 'c':
                if stack and stack[-1] == 'ab':
                    stack.pop()
                else:
                    if stack and stack[-1] == 'a':
                        count += 1
                        stack.pop()
                    count += 1
        while stack:
            if stack[-1] == 'a':
                count += 2
            elif stack[-1] == 'ab':
                count += 1
            stack.pop()
        return count

class Solution:
    def maximumOr(self, nums: List[int], k: int) -> int:
        def check(x):
            cnt = 0
            for num in nums:
                t = x | num
                while t > num:
                    num <<= 1
                    cnt += 1
                    if cnt > k:
                        return False
            return cnt <= k

        l, r = 0, 2**31 - 1
        while l < r:
            mid = (l + r + 1) // 2
            if check(mid):
                l = mid
            else:
                r = mid - 1
        return l

