class Solution:
    def makeTheIntegerZero(self, num1: int, num2: int) -> int:
        if num2 == 0:
            return 1 if num1 == 0 else -1
        if num2 > 0:
            return -1 if num1 % num2 != 0 else (num1 // num2)
        operations = 0
        while num1 != 0:
            found = False
            for i in range(60):
                if num1 - (2 * i + num2) == 0:
                    operations += 1
                    num1 = 0
                    found = True
                    break
                elif num1 - (2 * i + num2) < 0 and num1 - (2 * i + num2) % num2 == 0:
                    operations += 1
                    num1 = num1 - (2 * i + num2)
                    found = True
                    break
            if not found:
                return -1
        return operations

class Solution:
    def numberOfWays(self, n: int, x: int) -> int:
        MOD = 10**9 + 7
        dp = [0] * (n + 1)
        dp[0] = 1
        for i in range(1, n + 1):
            j = 1
            while j ** x <= i:
                dp[i] = (dp[i] + dp[i - j ** x]) % MOD
                j += 1
        return dp[n]

class Solution:
    def minimumChanges(self, s: str, k: int) -> int:
        def is_semi_palindrome(substring):
            n = len(substring)
            for d in range(1, n):
                if n % d == 0:
                    groups = [[] for _ in range(d)]
                    for i in range(n):
                        groups[i % d].append(substring[i])
                    if all(self.is_palindrome(group) for group in groups):
                        return True
            return False

        def is_palindrome(s):
            return s == s[::-1]

        def min_changes_to_semi_palindrome(substring):
            n = len(substring)
            min_changes = float('inf')
            for d in range(1, n):
                if n % d == 0:
                    groups = [[] for _ in range(d)]
                    for i in range(n):
                        groups[i % d].append(substring[i])
                    changes = 0
                    for group in groups:
                        if not self.is_palindrome(group):
                            changes += sum(1 for i in range(len(group) // 2) if group[i] != group[-i - 1])
                    min_changes = min(min_changes, changes)
            return min_changes

        memo = {}
        def dp(i, k):
            if (i, k) in memo:
                return memo[(i, k)]
            if k == 0:
                return float('inf')
            if i == len(s):
                return 0
            min_changes = float('inf')
            for j in range(i + 1, len(s) + 1):
                substring = s[i:j]
                changes = min_changes_to_semi_palindrome(substring)
                min_changes = min(min_changes, changes + dp(j, k - 1))
            memo[(i, k)] = min_changes
            return min_changes

        return dp(0, k)

class Solution:
    def findMinimumOperations(self, s1: str, s2: str, s3: str) -> int:
        def common_prefix_length(s1, s2, s3):
            length = 0
            for c1, c2, c3 in zip(s1, s2, s3):
                if c1 == c2 == c3:
                    length += 1
                else:
                    break
            return length

        common_length = common_prefix_length(s1, s2, s3)
        if common_length == 0:
            return -1

        operations = len(s1) + len(s2) + len(s3) - 3 * common_length
        return operations

