                if len(set(substring)) == 1:
                    substrings.add(substring)
            return len(substrings) >= 3

        for length in range(len(s), 0, -1):
            if check(length):
                return length
        return -1

class Solution:
    def minimumOperationsToMakeEqual(self, x: int, y: int) -> int:
        from collections import deque
        queue = deque([(x, 0)])
        visited = set([x])
        while queue:
            curr, step = queue.popleft()
            if curr == y:
                return step
            if curr % 11 == 0 and curr // 11 not in visited:
                queue.append((curr // 11, step + 1))
                visited.add(curr // 11)
            if curr % 5 == 0 and curr // 5 not in visited:
                queue.append((curr // 5, step + 1))
                visited.add(curr // 5)
            if curr - 1 not in visited and curr - 1 > 0:
                queue.append((curr - 1, step + 1))
                visited.add(curr - 1)
            if curr + 1 not in visited and curr + 1 <= 10**4:
                queue.append((curr + 1, step + 1))
                visited.add(curr + 1)

class Solution:
    def beautifulIndices(self, s: str, a: str, b: str, k: int) -> List[int]:
        def find_substring_indices(s, sub):
            return [i for i in range(len(s) - len(sub) + 1) if s[i:i + len(sub)] == sub]

        a_indices = find_substring_indices(s, a)
        b_indices = find_substring_indices(s, b)
        beautiful_indices = [i for i in a_indices if any(abs(i - j) <= k for j in b_indices)]
        return beautiful_indices

class Solution:
    def findMaximumNumber(self, k: int, x: int) -> int:
        def calculate_price(num: int, x: int) -> int:
            price = 0
            i = x
            while i <= num.bit_length() * x:
                price += (num >> (i - 1)) & 1
                i += x
            return price

        def calculate_accumulated_price(num: int, x: int) -> int:
            accumulated_price = 0
            for i in range(1, num + 1):
                accumulated_price += calculate_price(i, x)
            return accumulated_price

        left, right = 1, k * 100
        while left <= right:
            mid = (left + right) // 2
            accumulated_price = calculate_accumulated_price(mid, x)
            if accumulated_price <= k:
                left = mid + 1
            else:
                right = mid - 1
        return right

