        b_indices = [i for i in range(len(s)) if s.startswith(b, i)]
        for i in a_indices:
            for j in b_indices:
                if abs(i - j) <= k:
                    indices.append(i)
                    break
        return sorted(set(indices))

class Solution:
    def unmarkedSumArray(self, nums: List[int], queries: List[List[int]]) -> List[int]:
