class Solution:
    def doesAliceWin(self, s: str) -> bool:
        vowels = set('aeiou')
        n = len(s)
        dp = [[-1] * (n + 1) for _ in range(n + 1)]

        def dfs(start, end):
            if dp[start][end] != -1:
                return dp[start][end]
            count = sum(1 for i in range(start, end) if s[i] in vowels)
            if count % 2 == 1:
                dp[start][end] = 1
                return 1
            if start == end:
                dp[start][end] = 0
                return 0
            win = False
            for i in range(start + 1, end + 1):
                if dfs(start, i - 1) == 0 or dfs(i, end) == 0:
                    win = True
                    break
            dp[start][end] = 1 if win else 0
            return dp[start][end]

        return dfs(0, n) == 1

class Solution:
    def countGoodIntegers(self, n: int, k: int) -> int:
        def is_k_palindromic(num):
            return str(num) == str(num)[::-1] and num % k == 0

        def can_be_rearranged(num):
            digits = sorted(str(num))
            for i in range(10**(n-1), 10**n):
                if is_k_palindromic(i) and sorted(str(i)) == digits:
                    return True
            return False

        count = 0
        for i in range(10**(n-1), 10**n):
            if can_be_rearranged(i):
                count += 1
        return count

class Solution:
    def validSubstringCount(self, word1: str, word2: str) -> int:
        def can_be_prefix(s):
            w2_count = {}
            for c in word2:
                w2_count[c] = w2_count.get(c, 0) + 1

            for c in s:
                if c in w2_count and w2_count[c] > 0:
                    w2_count[c] -= 1
                if all(count == 0 for count in w2_count.values()):
                    return True
            return False

        count = 0
        for i in range(len(word1)):
            for j in range(i + 1, len(word1) + 1):
                if can_be_prefix(word1[i:j]):
                    count += 1
        return count

class Solution:
    def validSequence(self, word1: str, word2: str) -> List[int]:
        def is_almost_equal(s1, s2):
            diff = 0
            for c1, c2 in zip(s1, s2):
                if c1 != c2:
                    diff += 1
                if diff > 1:
                    return False
            return True

        def get_sequence(word1, word2):
            sequence = []
            i = 0
            for c in word2:
                while i < len(word1) and word1[i] != c:
                    i += 1
                if i == len(word1):
                    return []
                sequence.append(i)
                i += 1
            return sequence

        min_sequence = []
        for i in range(len(word1)):
            for j in range(i + 1, len(word1) + 1):
                sub_word1 = ''.join([word1[k] for k in range(i, j) if word1[k] in word2])
                if len(sub_word1) == len(word2) and is_almost_equal(sub_word1, word2):
                    sequence = get_sequence(word1, word2)
                    if not min_sequence or sequence < min_sequence:
                        min_sequence = sequence
        return min_sequence

class Solution:
    def minStartingIndex(self, s: str, pattern: str) -> int:
        def is_almost_equal(s: str, pattern: str) -> bool:
            diff_count = 0
            for i in range(len(pattern)):
                if s[i] != pattern[i]:
                    diff_count += 1
                if diff_count > 1:
                    return False
            return True

        min_index = -1
        for i in range(len(s) - len(pattern) + 1):
            if is_almost_equal(s[i:i + len(pattern)], pattern):
                return i
        return min_index

class Solution:
    def numberOfWays(self, n: int, x: int, y: int) -> int:
        MOD = 10**9 + 7
        result = 0
        for i in range(1, min(n, x) + 1):
            ways_to_assign = self.assign_stages(n, i)
            ways_to_score = pow(y, i, MOD)
            result = (result + ways_to_assign * ways_to_score) % MOD
        return result

    def assign_stages(self, n, k):
        MOD = 10**9 + 7
        result = self.stirling(n, k) * pow(k, n, MOD) % MOD
        return result

    def stirling(self, n, k):
        MOD = 10**9 + 7
        if n < k or k < 1:
            return 0
        if n == k or k == 1:
            return 1
        dp = [[0] * (k + 1) for _ in range(n + 1)]
        for i in range(1, n + 1):
            dp[i][1] = 1
        for i in range(1, n + 1):
            dp[i][i] = 1
        for i in range(2, n + 1):
            for j in range(2, min(i, k) + 1):
                dp[i][j] = (j * dp[i - 1][j] + dp[i - 1][j - 1]) % MOD
        return dp[n][k]

class Solution:
    def possibleStringCount(self, word: str, k: int) -> int:
        MOD = 10**9 + 7
        n = len(word)
        dp = [[0] * (k + 1) for _ in range(n + 1)]
        dp[0][0] = 1
        for i in range(1, n + 1):
            for j in range(1, min(i, k) + 1):
                if word[i - 1] == word[i - 2]:
                    dp[i][j] = dp[i - 1][j - 1] + dp[i - 2][j - 1] + dp[i - 3][j - 1] if i >= 3 else dp[i - 1][j - 1] + dp[i - 2][j - 1] if i >= 2 else dp[i - 1][j - 1]
                else:
                    dp[i][j] = dp[i - 1][j - 1]
                dp[i][j] %= MOD
        return sum(dp[n][j] for j in range(k, k + 1)) % MOD

class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        n = int(s, 2)
        memo = {}

        def count_set_bits(x):
            return bin(x).count('1')

        def is_k_reducible(x, k):
            if x == 1:
                return True
            if k == 0:
                return False
            if (x, k) in memo:
                return memo[(x, k)]
            memo[(x, k)] = is_k_reducible(count_set_bits(x), k-1)
            return memo[(x, k)]

        count = 0
        for i in range(1, n):
            if is_k_reducible(i, k):
                count += 1
        return count % MOD

class Solution:
    def largestWord(self, word: str, numFriends: int) -> str:
        def backtrack(start, path):
            if len(path) == numFriends:
                result.add(''.join(path))
                return
            for end in range(start + 1, len(word) + 1):
                backtrack(end, path + [word[start:end]])

        result = set()
        backtrack(0, [])
        return max(result)

class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        def expand_around_center(s, left, right):
            while left >= 0 and right < len(s) and s[left] == s[right]:
                left -= 1
                right += 1
            return right - left - 1

        combined = s + t
        max_length = 0
        for i in range(len(combined)):
            length1 = expand_around_center(combined, i, i)
            length2 = expand_around_center(combined, i, i + 1)
            max_length = max(max_length, length1, length2)
        return max_length

class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        def expand_around_center(s, left, right):
            while left >= 0 and right < len(s) and s[left] == s[right]:
                left -= 1
                right += 1
            return right - left - 1

        combined = s + t
        max_length = 0
        for i in range(len(combined)):
            length = expand_around_center(combined, i, i)
            max_length = max(max_length, length)
            length = expand_around_center(combined, i, i + 1)
            max_length = max(max_length, length)
        return max_length

class Solution:
    def countNumbers(self, l: str, r: str, b: int) -> int:
        def convert_to_base10(num: str, base: int) -> int:
            result = 0
            for i, digit in enumerate(reversed(num)):
                result += int(digit) * (base ** i)
            return result

        def convert_to_base_b(num: int, base: int) -> str:
            if num == 0:
                return '0'
            result = []
            while num > 0:
                result.append(str(num % base))
                num //= base
            return ''.join(reversed(result))

        def has_non_decreasing_digits(num: str) -> bool:
            for i in range(1, len(num)):
                if num[i] < num[i - 1]:
                    return False
            return True

        def count_non_decreasing_numbers_in_range(left: str, right: str, base: int) -> int:
            left_base10 = convert_to_base10(left, base)
            right_base10 = convert_to_base10(right, base)
            count = 0
            for num in range(left_base10, right_base10 + 1):
                num_base_b = convert_to_base_b(num, base)
                if has_non_decreasing_digits(num_base_b):
                    count += 1
            return count % (10 ** 9 + 7)

        return count_non_decreasing_numbers_in_range(l, r, b)

class Solution:
    def maxSubstrings(self, word: str) -> int:
        def backtrack(start, end, count):
            if start >= len(word):
                return count
            max_count = count
            for i in range(start + 3, len(word) + 1):
                if word[start] == word[i - 1]:
                    max_count = max(max_count, backtrack(i, end, count + 1))
            return max(max_count, backtrack(start + 1, end, count))

        return backtrack(0, len(word), 0)

class Solution:
    def maximumCount(self, nums: List[int], queries: List[List[int]]) -> List[int]:
        def is_prime(n):
            if n < 2:
                return False
            for i in range(2, int(n**0.5) + 1):
                if n % i == 0:
                    return False
            return True

        result = []
        for idx, val in queries:
            nums[idx] = val
            max_count = 0
            for k in range(1, len(nums)):
                prefix = set(num for num in nums[:k] if is_prime(num))
                suffix = set(num for num in nums[k:] if is_prime(num))
                max_count = max(max_count, len(prefix) + len(suffix))
            result.append(max_count)
        return result

from math import gcd
from functools import reduce
from typing import List

class Solution:
    def maxGCDScore(self, nums: List[int], k: int) -> int:
        def get_gcd(arr):
            return reduce(gcd, arr)

        max_score = 0
        for i in range(len(nums)):
            for j in range(i, len(nums)):
                subarray = nums[i:j+1]
                for mask in range(1 << len(subarray)):
                    new_subarray = subarray[:]
                    ops_used = 0
                    for idx in range(len(subarray)):
                        if (mask & (1 << idx)) and ops_used < k:
                            new_subarray[idx] *= 2
                            ops_used += 1
                    if ops_used <= k:
                        max_score = max(max_score, len(new_subarray) * get_gcd(new_subarray))
        return max_score

