import math

class Solution:
    def minTime(self, n: int, k: int, m: int, time: List[int], mul: List[float]) -> float:
        memo = {}

        def dp(stage, mask):
            if mask == 0:
                return 0
            if (stage, mask) in memo:
                return memo[(stage, mask)]

            ans = float('inf')
            for i in range(1 << n):
                if i & mask == i:
                    group_size = bin(i).count('1')
                    if group_size > k:
                        continue
                    max_time = max(time[j] for j in range(n) if (i & (1 << j)))
                    crossing_time = max_time * mul[stage]
                    new_stage = (stage + math.floor(crossing_time) % m) % m
                    if group_size < k and n - bin(mask).count('1') > 0:
                        continue
                    if group_size == k and n - bin(mask).count('1') == 0:
                        ans = min(ans, crossing_time)
                    else:
                        return_time = time[time.index(max_time)] * mul[new_stage]
                        new_stage_return = (new_stage + math.floor(return_time) % m) % m
                        ans = min(ans, crossing_time + return_time + dp(new_stage_return, mask ^ i))
            memo[(stage, mask)] = ans
            return ans

        ans = dp(0, (1 << n) - 1)
        if ans == float('inf'):
            return -1
        return ans

class Solution:
    def maxStability(self, n: int, edges: List[List[int]], k: int) -> int:
        def find(x):
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]

        def union(x, y):
            root_x, root_y = find(x), find(y)
            if root_x != root_y:
                parent[root_x] = root_y
                return True
            return False

        edges.sort(key=lambda x: x[2])
        parent = list(range(n))
        rank = [0] * n
        must_edges = [edge for edge in edges if edge[3] == 1]
        optional_edges = [edge for edge in edges if edge[3] == 0]
        must_edges.sort(key=lambda x: x[2])
        optional_edges.sort(key=lambda x: x[2])

        for u, v, s, must in must_edges:
            union(u, v)

        if len(set(find(i) for i in range(n))) != 1:
            return -1

        for u, v, s, must in must_edges:
            edges.remove([u, v, s, must])

        edges = optional_edges
        edges.sort(key=lambda x: x[2])

        res = float('inf')
        for s in range(1, 10**5 + 1):
            parent = list(range(n))
            rank = [0] * n
            count = 0
            for u, v, strength, must in edges:
                if strength >= s:
                    if union(u, v):
                        count += 1
                elif strength * 2 >= s and k > 0:
                    if union(u, v):
                        count += 1
                        k -= 1
            if count == n - 1:
                res = min(res, s)
        return res if res != float('inf') else -1

