from functools import reduce
from typing import List

class Solution:
    def minStable(self, nums: List[int], maxC: int) -> int:
        def hcf(arr):
            return reduce(gcd, arr)

        n = len(nums)
        max_stable = 0

        for i in range(n):
            for j in range(i, n):
                subarray = nums[i:j+1]
                if hcf(subarray) >= 2:
                    max_stable = max(max_stable, len(subarray))

        if max_stable == 0:
            return 0

        min_stable = max_stable

        for i in range(n):
            for j in range(i, n):
                subarray = nums[i:j+1]
                if hcf(subarray) >= 2:
                    for k in range(maxC + 1):
                        for modified_subarray in self.generate_modified_subarrays(subarray, k):
                            if hcf(modified_subarray) < 2:
                                min_stable = min(min_stable, len(modified_subarray))

        return min_stable if min_stable > 1 else 1

    def generate_modified_subarrays(self, subarray, max_modifications):
        if max_modifications == 0:
            yield subarray
        else:
            for i in range(len(subarray)):
                for new_value in range(2, 10**9 + 1):
                    modified_subarray = subarray[:i] + [new_value] + subarray[i+1:]
                    yield from self.generate_modified_subifications(modified_subarray, max_modifications - 1)

    def generate_modified_subifications(self, subarray, max_modifications):
        if max_modifications == 0:
            yield subarray
        else:
            for i in range(len(subarray)):
                for new_value in range(2, 10**9 + 1):
                    modified_subarray = subarray[:i] + [new_value] + subarray[i+1:]
                    yield from self.generate_modified_subifications(modified_subarray, max_modifications - 1)

class Solution:
    def popcountDepth(self, nums: List[int], queries: List[List[int]]) -> List[int]:
        def popcount(x):
            count = 0
            while x:
                count += x & 1
                x >>= 1
            return count

        def popcount_depth(x):
            depth = 0
            while x > 1:
                x = popcount(x)
                depth += 1
            return depth

        answer = []
        for query in queries:
            if query[0] == 1:
                l, r, k = query[1], query[2], query[3]
                count = sum(1 for i in range(l, r + 1) if popcount_depth(nums[i]) == k)
                answer.append(count)
            elif query[0] == 2:
                idx, val = query[1], query[2]
                nums[idx] = val
        return answer

class Solution:
    def multiply(self, num1: str, num2: str) -> str:
        if num1 == "0" or num2 == "0":
            return "0"

        result = [0] * (len(num1) + len(num2))

        for i in range(len(num1) - 1, -1, -1):
            for j in range(len(num2) - 1, -1, -1):
                mul = (ord(num1[i]) - ord('0')) * (ord(num2[j]) - ord('0'))
                p1, p2 = i + j, i + j + 1
                sum = mul + result[p2]

                result[p1] += sum // 10
                result[p2] = sum % 10

        start = 0
        while start < len(result) - 1 and result[start] == 0:
            start += 1

        return ''.join(str(x) for x in result[start:])

