        char_dict = {chars[i]: vals[i] for i in range(len(chars))}
        max_cost = 0
        for i in range(len(s)):
            for j in range(i, len(s)):
                cost = 0
                for k in range(i, j + 1):
                    cost += char_dict.get(s[k], ord(s[k]) - 96)
                max_cost = max(max_cost, cost)
        return max_cost

class Solution:
    def findTheLongestBalancedSubstring(self, s: str) -> int:
        max_len = 0
        for i in range(len(s)):
            for j in range(i + 1, len(s) + 1):
                substring = s[i:j]
                if substring.count('0') == substring.count('1') and substring.find('1') >= substring.rfind('0'):
                    max_len = max(max_len, len(substring))
        return max_len

