        max_val = float('-inf')
        for i in range(len(nums)):
            for j in range(i + 1, len(nums)):
                for k in range(j + 1, len(nums)):
                    val = (nums[i] - nums[j]) * nums[k]
                    max_val = max(max_val, val)
        return max_val if max_val > 0 else 0

