class Solution:
    def kthCharacter(self, k: int, operations: List[int]) -> str:
        word = "a"
        for op in operations:
            if op == 0:
                word += word
            else:
                new_word = ""
                for c in word:
                    if c == 'z':
                        new_word += 'a'
                    else:
                        new_word += chr(ord(c) + 1)
                word += new_word
        return word[k - 1]

class Solution:
    def countWinningSequences(self, s: str) -> int:
        MOD = 10**9 + 7
        n = len(s)
        dp = [[[0]*3 for _ in range(3)] for _ in range(n+1)]
        dp[0][0][0] = 1
        for i in range(n):
            for j in range(3):
                for k in range(3):
                    if dp[i][j][k] == 0:
                        continue
                    for l in range(3):
                        if l == j:
                            continue
                        if (s[i] == 'F' and l == 2) or (s[i] == 'W' and l == 0) or (s[i] == 'E' and l == 1):
                            dp[i+1][l][k] = (dp[i+1][l][k] + dp[i][j][k]) % MOD
                        else:
                            dp[i+1][l][j] = (dp[i+1][l][j] + dp[i][j][k]) % MOD
        res = 0
        for i in range(3):
            for j in range(3):
                res = (res + dp[n][i][j]) % MOD
        return res

class Solution:
    def lengthAfterTransformations(self, s: str, t: int, nums: List[int]) -> int:
        MOD = 10**9 + 7
        dp = [1] * 26
        for _ in range(t):
            new_dp = [0] * 26
            for i in range(26):
                new_dp[(i + nums[i]) % 26] += dp[i]
            dp = new_dp
        return sum(dp[ord(c) - ord('a')] for c in s) % MOD

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        def match(s, p):
            if not p:
                return not s
            if p[0] == '*':
                return match(s, p[1:]) or (s and match(s[1:], p))
            return s and s[0] == p[0] and match(s[1:], p[1:])

        min_len = float('inf')
        for i in range(len(s)):
            for j in range(i + 1, len(s) + 1):
                if match(s[i:j], p):
                    min_len = min(min_len, j - i)
        return min_len if min_len != float('inf') else -1

