class SummaryRanges:

    def __init__(self):
        self.intervals = []

    def addNum(self, value: int) -> None:
        if not self.intervals:
            self.intervals.append([value, value])
        else:
            for i, interval in enumerate(self.intervals):
                if value < interval[0]:
                    self.intervals.insert(i, [value, value])
                    break
                elif value <= interval[1]:
                    interval[1] = value
                    break
                elif i == len(self.intervals) - 1:
                    if value == interval[1] + 1:
                        interval[1] = value
                    else:
                        self.intervals.append([value, value])
                    break
                elif value == interval[1] + 1:
                    interval[1] = value
                    if i + 1 < len(self.intervals) and value + 1 == self.intervals[i + 1][0]:
                        interval[1] = self.intervals[i + 1][1]
                        del self.intervals[i + 1]
                    break

    def getIntervals(self) -> List[List[int]]:
        return self.intervals

class AllOne:
    def __init__(self):
        self.d = {}
        self.max_heap = []
        self.min_heap = []

    def inc(self, key: str) -> None:
        if key not in self.d:
            self.d[key] = 1
            heapq.heappush(self.max_heap, (-1, key))
            heapq.heappush(self.min_heap, (1, key))
        else:
            self.d[key] += 1
            self.max_heap.remove((-self.d[key] + 1, key))
            self.min_heap.remove((self.d[key] - 1, key))
            heapq.heappush(self.max_heap, (-self.d[key], key))
            heapq.heappush(self.min_heap, (self.d[key], key))

    def dec(self, key: str) -> None:
        self.d[key] -= 1
        if self.d[key] == 0:
            del self.d[key]
            self.max_heap.remove((-1, key))
            self.min_heap.remove((1, key))
            heapq.heapify(self.max_heap)
            heapq.heapify(self.min_heap)
        else:
            self.max_heap.remove((-self.d[key] - 1, key))
            self.min_heap.remove((self.d[key] + 1, key))
            heapq.heappush(self.max_heap, (-self.d[key], key))
            heapq.heappush(self.min_heap, (self.d[key], key))

    def getMaxKey(self) -> str:
        if not self.max_heap:
            return ""
        return self.max_heap[0][1]

    def getMinKey(self) -> str:
        if not self.min_heap:
            return ""
        return self.min_heap[0][1]

class Codec:

    def serialize(self, root: Optional[TreeNode]) -> str:
        """Encodes a tree to a single string.
        """
        def dfs(node):
            if node:
                vals.append(str(node.val))
                dfs(node.left)
                dfs(node.right)
            else:
                vals.append('#')
        vals = []
        dfs(root)
        return ' '.join(vals)

    def deserialize(self, data: str) -> Optional[TreeNode]:
        """Decodes your encoded data to tree.
        """
        def dfs():
            val = next(vals)
            if val == '#':
                return None
            node = TreeNode(int(val))
            node.left = dfs()
            node.right = dfs()
            return node
        vals = iter(data.split())
        return dfs()

class LFUCache:
    def __init__(self, capacity: int):
        self.capacity = capacity
        self.key_value = {}
        self.key_count = {}
        self.least_count = 0
        self.count_freq = defaultdict(list)

    def get(self, key: int) -> int:
        if key not in self.key_value:
            return -1
        count = self.key_count[key]
        del self.count_freq[count][key]
        if not self.count_freq[count]:
            del self.count_freq[count]
        self.key_count[key] += 1
        self.count_freq[count + 1].append(key)
        return self.key_value[key]

    def put(self, key: int, value: int) -> None:
        if not self.capacity:
            return
        if key in self.key_value:
            self.key_value[key] = value
            self.get(key)
            return
        if len(self.key_value) == self.capacity:
            k, _ = self.count_freq[self.least_count][0]
            del self.key_value[k]
            del self.key_count[k]
            del self.count_freq[self.least_count][0]
            if not self.count_freq[self.least_count]:
                del self.count_freq[self.least_count]
                self.least_count += 1
        self.key_value[key] = value
        self.key_count[key] = 1
        self.count_freq[1].append(key)
        self.least_count = 1

import random

class Solution:

    def __init__(self, m: int, n: int):
        self.m, self.n = m, n
        self.total = m * n
        self.mat = [[0]*n for _ in range(m)]

    def flip(self) -> List[int]:
        idx = random.randint(0, self.total - 1)
        self.total -= 1
        m, n = idx // self.n, idx % self.n
        while self.mat[m][n] == 1:
            idx = (idx + 1) % (self.m * self.n)
            m, n = idx // self.n, idx % self.n
        self.mat[m][n] = 1
        return [m, n]

    def reset(self) -> None:
        self.total = self.m * self.n
        for i in range(self.m):
            for j in range(self.n):
                self.mat[i][j] = 0

