class Solution:
    def maxScore(self, nums: List[int]) -> int:
        @lru_cache(None)
        def dfs(mask):
            if mask == 0:
                return 0
            res = 0
            for i, j in combinations(range(len(nums)), 2):
                if (mask >> i) & 1 and (mask >> j) & 1:
                    res = max(res, dfs(mask ^ (1 << i) ^ (1 << j)) + gcd(nums[i], nums[j]) * ((mask.bit_count() + 1) // 2))
            return res
        return dfs((1 << len(nums)) - 1)

