        parent = list(range(26))
        def find(x):
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]
        def union(x, y):
            rootx, rooty = find(x), find(y)
            if rootx != rooty:
                parent[rootx] = rooty
        for a, b in zip(s1, s2):
            union(ord(a) - ord('a'), ord(b) - ord('a'))
        res = []
        for c in baseStr:
