class MyLinkedList {
    private Node head;
    private int size;

    public MyLinkedList() {
        head = null;
        size = 0;
    }

    public int get(int index) {
        if (index < 0 || index >= size) {
            return -1;
        }
        Node current = head;
        for (int i = 0; i < index; i++) {
            current = current.next;
        }
        return current.val;
    }

    public void addAtHead(int val) {
        head = new Node(val, head);
        size++;
    }

    public void addAtTail(int val) {
        if (head == null) {
            head = new Node(val);
        } else {
            Node current = head;
            while (current.next != null) {
                current = current.next;
            }
            current.next = new Node(val);
        }
        size++;
    }

    public void addAtIndex(int index, int val) {
        if (index > size) {
            return;
        }
        if (index == 0) {
            addAtHead(val);
        } else {
            Node current = head;
            for (int i = 0; i < index - 1; i++) {
                current = current.next;
            }
            current.next = new Node(val, current.next);
            size++;
        }
    }

    public void deleteAtIndex(int index) {
        if (index < 0 || index >= size) {
            return;
        }
        if (index == 0) {
            head = head.next;
        } else {
            Node current = head;
            for (int i = 0; i < index - 1; i++) {
                current = current.next;
            }
            current.next = current.next.next;
        }
        size--;
    }

    private static class Node {
        int val;
        Node next;

        Node(int val) {
            this.val = val;
        }

        Node(int val, Node next) {
            this.val = val;
            this.next = next;
        }
    }
}

class FreqStack {
    Map<Integer, Integer> freqMap;
    Map<Integer, Stack<Integer>> stackMap;

    public FreqStack() {
        freqMap = new HashMap<>();
        stackMap = new HashMap<>();
    }

    public void push(int val) {
        freqMap.put(val, freqMap.getOrDefault(val, 0) + 1);
        stackMap.computeIfAbsent(val, k -> new Stack<>()).push(val);
    }

    public int pop() {
        int maxFreq = 0;
        int res = 0;
        for (Map.Entry<Integer, Stack<Integer>> entry : stackMap.entrySet()) {
            if (entry.getValue().size() > 0 && entry.getKey() > maxFreq) {
                maxFreq = entry.getKey();
                res = entry.getValue().pop();
            }
        }
        freqMap.put(maxFreq, freqMap.get(maxFreq) - 1);
        if (freqMap.get(maxFreq) == 0) {
            stackMap.remove(maxFreq);
        }
        return res;
    }
}

