class ExamRoom:

    def __init__(self, n: int):
        self.students = set()
        self.last_seat = -1

    def seat(self) -> int:
        if not self.students:
            self.students.add(0)
            return 0
        max_dist = 0
        seat = 0
        for i in sorted(self.students):
            if i > self.last_seat:
                dist = i - self.last_seat
                if dist > max_dist:
                    max_dist = dist
                    seat = self.last_seat + (dist + 1) // 2
            self.last_seat = i
        self.students.add(seat)
        return seat

    def leave(self, p: int) -> None:
        self.students.remove(p)
        if p > 0 and p - 1 in self.students:
            self.students.remove(p - 1)
            self.students.add((p - 1 + p) // 2)
        elif p < len(self.students) - 1 and p + 1 in self.students:
            self.students.remove(p + 1)
            self.students.add((p + p + 1) // 2)

class FreqStack:

    def __init__(self):
        self.freq = {}
        self.group = {}

    def push(self, val: int) -> None:
        count = self.freq.get(val, 0)
        self.freq[val] = count + 1
        self.group.setdefault(count + 1, []).append(val)

    def pop(self) -> int:
        max_count = max(self.group.keys())
        val = self.group[max_count].pop()
        self.freq[val] -= 1
        if not self.group[max_count]:
            del self.group[max_count]
        return val

class StockSpanner:

    def __init__(self):
        self.stack = []

    def next(self, price: int) -> int:
        while self.stack and self.stack[-1][0] <= price:
            self.stack.pop()
        if not self.stack:
            self.stack.append((price, 1))
        else:
            self.stack.append((price, self.stack[-1][1] + 1))
        return self.stack[-1][1]

