class CombinationIterator:

    def __init__(self, characters: str, combinationLength: int):
        self.chars = characters
        self.length = combinationLength
        self.index = 0
        self.combinations = self.generate_combinations()

    def generate_combinations(self):
        combinations = []
        for i in range(len(self.chars)):
            if i > 0:
                combinations.extend([c + self.chars[i] for c in self.combinations[-1]])
            else:
                combinations.append(self.chars[i])
        return combinations

    def next(self) -> str:
        if self.index < len(self.combinations):
            result = self.combinations[self.index]
            self.index += 1
            return result
        return ""

    def hasNext(self) -> bool:
        return self.index < len(self.combinations)

class TweetCounts:

    def __init__(self):
        self.tweets = defaultdict(dict)

    def recordTweet(self, tweetName: str, time: int) -> None:
        if tweetName not in self.tweets:
            self.tweets[tweetName] = {}
        if time not in self.tweets[tweetName]:
            self.tweets[tweetName][time] = 1
        else:
            self.tweets[tweetName][time] += 1

    def getTweetCountsPerFrequency(self, freq: str, tweetName: str, startTime: int, endTime: int) -> List[int]:
        result = []
        if tweetName not in self.tweets:
            return result
        if freq == "minute":
            chunk_size = 60
        elif freq == "hour":
            chunk_size = 3600
        else:
            chunk_size = 86400
        for time in range(startTime, endTime + 1):
            count = 0
            while time - chunk_size >= startTime:
                if time - chunk_size in self.tweets[tweetName]:
                    count += self.tweets[tweetName][time - chunk_size]
                time -= chunk_size
            if time in self.tweets[tweetName]:
                count += self.tweets[tweetName][time]
            result.append(count)
        return result

class Solution:
    def canConstruct(self, s: str, k: int) -> bool:
        from collections import Counter
        count = Counter(s)
        odd_count = 0
        for c in count:
            if count[c] % 2 != 0:
                odd_count += 1
        return odd_count <= k

