class Solution:
    def strWithout3a3b(self, a: int, b: int) -> str:
        res = []
        while a > 0 or b > 0:
            if a >= 2 and b > 0:
                res.append('aa')
                a -= 2
                b -= 1
            elif a > 0:
                res.append('a')
                a -= 1
            elif b >= 2 and a > 0:
                res.append('bb')
                a -= 1
                b -= 2
            else:
                res.append('b')
                b -= 1
        return ''.join(res)

