class Solution:
    def maxSatisfied(self, customers: List[int], grumpy: List[int], minutes: int) -> int:
        total = sum(customers)
        max_earned = 0
        for i in range(len(customers) - minutes + 1):
            earned = sum(customers[i:i+minutes])
            max_earned = max(max_earned, earned)
        return total - max_earned + min(sum(customers[i:i+minutes]) for i in range(len(customers) - minutes + 1))

class Solution:
    def smallestEquivalentString(self, s1: str, s2: str, baseStr: str) -> str:
        parent = {}
        rank = {}
        for i in range(26):
            parent[i] = i
            rank[i] = 0
        for c1, c2 in zip(s1, s2):
            find1 = self.find(ord(c1) - ord('a'))
            find2 = self.find(ord(c2) - ord('a'))
            if find1 != find2:
                self.union(find1, find2)
        res = []
        for c in baseStr:
            res.append(chr(self.find(ord(c) - ord('a')) + ord('a')))
        return ''.join(res)

    def find(self, x):
        if parent[x] != x:
            parent[x] = self.find(parent[x])
        return parent[x]

    def union(self, x, y):
        rootX = self.find(x)
        rootY = self.find(y)
        if rootX != rootY:
            if rank[rootX] > rank[rootY]:
                parent[rootY] = rootX
            else:
                parent[rootX] = rootY
                if rank[rootX] == rank[rootY]:
                    rank[rootY] += 1

class Solution:
    def shortestAlternatingPaths(self, n: int, redEdges: List[List[int]], blueEdges: List[List[int]]) -> List[int]:
        graph = [[] for _ in range(n)]
        for edge in redEdges:
            graph[edge[0]].append((edge[1], 0))
        for edge in blueEdges:
            graph[edge[0]].append((edge[1], 1))
        distance = [float('inf')] * n
        distance[0] = 0
        queue = [(0, 0)]
        while queue:
            node, color = queue.pop(0)
            for neighbor, edge_color in graph[node]:
                if edge_color != color:
                    if distance[neighbor] > distance[node] + 1:
                        distance[neighbor] = distance[node] + 1
                        queue.append((neighbor, 1 - color))
        return [distance[i] if distance[i] != float('inf') else -1 for i in range(n)]

class Solution:
    def maxAbsValExpr(self, arr1: List[int], arr2: List[int]) -> int:
        res = 0
        for i in range(len(arr1)):
            for j in range(i, len(arr1)):
                res = max(res, abs(arr1[i] - arr1[j]) + abs(arr2[i] - arr2[j]) + abs(i - j))
        return res

class Solution:
    def longestDecomposition(self, text: str) -> int:
        n = len(text)
        k = 0
        i = 0
        while i < n:
            j = i
            while j < n and text[j] == text[n - 1 - j + i]:
                j += 1
            k += 1
            i = j
        return k

