        s = str(abs(num))
        s = sorted(s)
        if s[0] == '0':
            s[0], s[1] = s[1], s[0]
        return -int(''.join(s)) if num < 0 else int(''.join(s))

class Solution:
    def largestInteger(self, num: int) -> int:
        str_num = str(num)
        odd, even = [], []
        for char in str_num:
            if int(char) % 2:
                odd.append(char)
            else:
                even.append(char)
        odd.sort(reverse=True)
        even.sort(reverse=True)
        result = ''
        for char in str_num:
            if int(char) % 2:
                result += odd.pop(0)
            else:
                result += even.pop(0)
        return int(result)

class Solution:
    def rearrangeCharacters(self, s: str, target: str) -> int:
        from collections import Counter
        s_count = Counter(s)
        target_count = Counter(target)
        res = float('inf')
        for char, count in target_count.items():
            res = min(res, s_count[char] // count)
        return res

