class Solution {
public:
    int compareVersion(string version1, string version2) {
        int i = 0, j = 0;
        while (i < version1.size() || j < version2.size()) {
            int num1 = 0, num2 = 0;
            while (i < version1.size() && version1[i] != '.') {
                num1 = num1 * 10 + (version1[i++] - '0');
            }
            while (j < version2.size() && version2[j] != '.') {
                num2 = num2 * 10 + (version2[j++] - '0');
            }
            if (num1 < num2) return -1;
            if (num1 > num2) return 1;
            i++; j++;
        }
        return 0;
    }
};

class Solution {
public:
    int nthUglyNumber(int n) {
        vector<int> uglyNumbers(1, 1);
        int i2 = 0, i3 = 0, i5 = 0;
        while (uglyNumbers.size() < n) {
            int next2 = uglyNumbers[i2] * 2, next3 = uglyNumbers[i3] * 3, next5 = uglyNumbers[i5] * 5;
            int nextUgly = min({next2, next3, next5});
            if (nextUgly == next2) i2++;
            if (nextUgly == next3) i3++;
            if (nextUgly == next5) i5++;
            uglyNumbers.push_back(nextUgly);
        }
        return uglyNumbers.back();
    }
};

class Solution {
public:
    vector<string> removeInvalidParentheses(string s) {
        vector<string> result;
        int countLeft = 0, countRight = 0;
        for (char c : s) {
            if (c == '(') countLeft++;
            else if (c == ')') {
                if (countLeft > 0) countLeft--;
                else countRight++;
            }
        }
        dfs(s, 0, countLeft, countRight, result);
        return result;
    }

    void dfs(string s, int start, int leftRem, int rightRem, vector<string>& result) {
        if (leftRem == 0 && rightRem == 0) {
            if (isValid(s)) {
                result.push_back(s);
            }
            return;
        }
        for (int i = start; i < s.size(); i++) {
            if (i > start && s[i] == s[i-1]) continue;
            if (s[i] == '(' && leftRem > 0) {
                dfs(s.substr(0, i) + s.substr(i+1), i, leftRem-1, rightRem, result);
            }
            if (s[i] == ')' && rightRem > 0) {
                dfs(s.substr(0, i) + s.substr(i+1), i, leftRem, rightRem-1, result);
            }
        }
    }

    bool isValid(string s) {
        int count = 0;
        for (char c : s) {
            if (c == '(') count++;
            else if (c == ')') {
                count--;
                if (count < 0) return false;
            }
        }
        return count == 0;
    }
};

class Solution {
public:
    int strongPasswordChecker(string password) {
        int missingTypes = 3;
        if (any_of(password.begin(), password.end(), ::islower)) missingTypes--;
        if (any_of(password.begin(), password.end(), ::isupper)) missingTypes--;
        if (any_of(password.begin(), password.end(), ::isdigit)) missingTypes--;

        int n = password.size();
        int oneRepeating = 0, twoRepeating = 0;
        int count = 1;
        for (int i = 1; i < n; ++i) {
            if (password[i] == password[i - 1]) count++;
            else {
                if (count >= 3) {
                    int remainder = count % 3;
                    if (remainder == 0) oneRepeating++;
                    else if (remainder == 1) twoRepeating++;
                }
                count = 1;
            }
        }
        if (count >= 3) {
            int remainder = count % 3;
            if (remainder == 0) oneRepeating++;
            else if (remainder == 1) twoRepeating++;
        }

        if (n < 6) {
            return max(6 - n, missingTypes);
        } else if (n <= 20) {
            return max(missingTypes, oneRepeating + twoRepeating);
        } else {
            int deletions = n - 20;
            oneRepeating -= min(deletions, oneRepeating);
            twoRepeating -= min(max(deletions - oneRepeating, 0), twoRepeating * 2) / 2;
            return deletions + max(missingTypes, oneRepeating + twoRepeating);
        }
    }
};

class Solution {
public:
    string frequencySort(string s) {
        unordered_map<char, int> freq;
        for (char c : s) {
            freq[c]++;
        }

        auto cmp = [](const pair<char, int>& a, const pair<char, int>& b) {
            return a.second < b.second;
        };

        priority_queue<pair<char, int>, vector<pair<char, int>>, decltype(cmp)> maxHeap(cmp);
        for (auto& it : freq) {
            maxHeap.push(it);
        }

        string result;
        while (!maxHeap.empty()) {
            auto top = maxHeap.top();
            maxHeap.pop();
            result.append(top.second, top.first);
        }

        return result;
    }
};

class Solution {
public:
    string reverseWords(string s) {
        int start = 0;
        for (int i = 0; i <= s.size(); i++) {
            if (i == s.size() || s[i] == ' ') {
                reverse(s.begin() + start, s.begin() + i);
                start = i + 1;
            }
        }
        return s;
    }
};

class Solution {
public:
    int findIntegers(int n) {
        int f[31] = {0};
        f[0] = 1;
        f[1] = 2;
        for (int i = 2; i < 31; ++i) {
            f[i] = f[i - 1] + f[i - 2];
        }
        int ans = 0, pre = 0;
        for (int i = 29; i >= 0; --i) {
            if ((n >> i) & 1) {
                ans += f[i];
                if (pre == 1) {
                    return ans;
                }
                pre = 1;
            } else {
                pre = 0;
            }
        }
        return ans + 1;
    }
};

class Solution {
public:
    int minSteps(int n) {
        int dp[n + 1];
        for (int i = 1; i <= n; i++) dp[i] = i;
        dp[1] = 0;
        for (int i = 2; i <= n; i++) {
            for (int j = i - 1; j >= 1; j--) {
                if (i % j == 0) {
                    dp[i] = dp[j] + i / j;
                    break;
                }
            }
        }
        return dp[n];
    }
};

