class Solution {
public:
    string smallestSubsequence(string s) {
        int lastOccurrence[26] = {0};
        for (int i = 0; i < s.size(); i++) {
            lastOccurrence[s[i] - 'a'] = i;
        }
        bool visited[26] = {false};
        string result = "";
        for (int i = 0; i < s.size(); i++) {
            if (visited[s[i] - 'a']) continue;
            while (!result.empty() && result.back() > s[i] && i < lastOccurrence[result.back() - 'a']) {
                visited[result.back() - 'a'] = false;
                result.pop_back();
            }
            result += s[i];
            visited[s[i] - 'a'] = true;
        }
        return result;
    }
};

class Solution {
public:
    int longestCommonSubsequence(string text1, string text2) {
        int m = text1.size(), n = text2.size();
        vector<vector<int>> dp(m + 1, vector<int>(n + 1, 0));
        for (int i = 1; i <= m; ++i) {
            for (int j = 1; j <= n; ++j) {
                if (text1[i - 1] == text2[j - 1]) {
                    dp[i][j] = dp[i - 1][j - 1] + 1;
                } else {
                    dp[i][j] = max(dp[i - 1][j], dp[i][j - 1]);
                }
            }
        }
        return dp[m][n];
    }
};

class Solution {
public:
    ListNode* removeZeroSumSublists(ListNode* head) {
        ListNode dummy(0);
        dummy.next = head;
        int prefix = 0;
        unordered_map<int, ListNode*> seen;
        seen[0] = &dummy;
        while (head) {
            prefix += head->val;
            if (seen.find(prefix) != seen.end()) {
                ListNode* node = seen[prefix]->next;
                int tmp = prefix + node->val;
                seen.erase(prefix);
                while (node != head) {
                    seen.erase(tmp);
                    node = node->next;
                    tmp += node->val;
                }
                seen[prefix]->next = head->next;
            } else {
                seen[prefix] = head;
            }
            head = head->next;
        }
        return dummy.next;
    }
};

