class Solution {
public:
    int numberOfArrays(string s, int k) {
        int n = s.size();
        const int MOD = 1e9 + 7;
        vector<int> dp(n + 1, 0);
        dp[n] = 1;
        for (int i = n - 1; i >= 0; --i) {
            if (s[i] == '0') continue;
            long long num = 0;
            for (int j = i; j < n; ++j) {
                num = num * 10 + (s[j] - '0');
                if (num > k) break;
                dp[i] = (dp[i] + dp[j + 1]) % MOD;
            }
        }
        return dp[0];
    }
};

class Solution {
public:
    bool canConvertString(string s, string t, int k) {
        if (s.size() != t.size()) return false;
        vector<int> count(26, 0);
        for (int i = 0; i < s.size(); ++i) {
            int diff = (t[i] - s[i] + 26) % 26;
            count[diff]++;
        }
        int maxMove = 0;
        for (int i = 1; i < 26; ++i) {
            if (count[i]) {
                maxMove = max(maxMove, i + 26 * (count[i] - 1));
            }
        }
        return maxMove <= k;
    }
};

