            count.assign(1 << 10, 0);
            int max_cnt_local = 0;
            for (int j = i; j < n; j += k) {
                count[nums[j]]++;
                max_cnt_local = max(max_cnt_local, count[nums[j]]);
            }
            max_cnt += max_cnt_local;
        }
