    }
};

class Solution {
public:
    int maxScore(vector<int>& nums) {
        int n = nums.size() / 2;
        vector<int> state(1 << nums.size(), -1);
        return dfs(nums, state, (1 << nums.size()) - 1, n);
    }

    int dfs(vector<int>& nums, vector<int>& state, int mask, int n) {
        if (state[mask] != -1) return state[mask];
        if (n == 0) return state[mask] = 0;

        int res = 0;
        vector<int> indices;
        for (int i = 0; i < nums.size(); ++i) {
            if ((mask >> i) & 1) indices.push_back(i);
        }

        for (int i = 0; i < indices.size(); ++i) {
            for (int j = i + 1; j < indices.size(); ++j) {
                int x = nums[indices[i]], y = nums[indices[j]];
                int new_mask = mask ^ (1 << indices[i]) ^ (1 << indices[j]);
                res = max(res, n * gcd(x, y) + dfs(nums, state, new_mask, n - 1));
            }
        }
        return state[mask] = res;
    }

    int gcd(int x, int y) {
        if (y == 0) return x;
        return gcd(y, x % y);
    }
};

class Solution {
public:
    int getMinSwaps(string num, int k) {
        string target = num;
        for (int i = 0; i < k; ++i) {
            next_permutation(target.begin(), target.end());
        }
        return countSwaps(num, target);
    }

    int countSwaps(const string& num, const string& target) {
        int n = num.size();
        int res = 0;
        vector<int> pos(10, -1);
        for (int i = n - 1; i >= 0; --i) {
            int d = target[i] - '0';
            pos[d] = i;
        }
        for (int i = 0; i < n; ++i) {
            int d = num[i] - '0';
            res += abs(i - pos[d]);
            for (int j = d; j >= 0; --j) {
                --pos[j];
            }
        }
        return res;
    }

    bool next_permutation(string::iterator first, string::iterator last) {
        if (first == last) return false;
        string::iterator i = last;
        if (first == --i) return false;
        while (true) {
            string::iterator i1, i2;
            i1 = i;
            if (*--i < *i1) {
                i2 = last;
                while (!(*i < *--i2));
                iter_swap(i, i2);
                reverse(i1, last);
                return true;
            }
            if (i == first) {
                reverse(first, last);
                return false;
            }
        }
    }

    void iter_swap(string::iterator a, string::iterator b) {
        char tmp = *a;
        *a = *b;
        *b = tmp;
    }

    void reverse(string::iterator first, string::iterator last) {
        while ((first != last) && (first != --last)) {
            iter_swap(first++, last);
        }
    }
};

