    long long mostPoints(vector<vector<int>>& questions) {
        int n = questions.size();
        vector<long long> dp(n + 1, 0);
        for (int i = n - 1; i >= 0; --i) {
            int points = questions[i][0];
            int brainpower = questions[i][1];
            int next_i = min(i + brainpower + 1, n);
            dp[i] = max(dp[i + 1], points + dp[next_i]);
        }
        return dp[0];
    }
};

class Solution {
public:
    vector<int> maxScoreIndices(vector<int>& nums) {
        int n = nums.size();
        int totalOnes = accumulate(nums.begin(), nums.end(), 0);
        int maxScore = totalOnes;
        int currentScore = totalOnes;
        vector<int> result;
        result.push_back(0);

        for (int i = 0; i < n; ++i) {
            if (nums[i] == 0) {
                currentScore += 1;
            } else {
                currentScore -= 1;
            }
            if (currentScore > maxScore) {
                maxScore = currentScore;
                result.clear();
                result.push_back(i + 1);
            } else if (currentScore == maxScore) {
                result.push_back(i + 1);
            }
        }

        return result;
    }
};

class Solution {
public:
    long long smallestNumber(long long num) {
        if (num == 0) return 0;
        bool isNegative = num < 0;
        if (isNegative) num = -num;
        string str = to_string(num);
        sort(str.begin(), str.end());
        if (!isNegative) {
            int i = 0;
            while (i < str.size() && str[i] == '0') i++;
            if (i > 0 && i < str.size()) {
                swap(str[0], str[i]);
            }
            return stoll(str);
        } else {
            return -stoll(string(str.rbegin(), str.rend()));
        }
    }
};

class Solution {
public:
    int largestInteger(int num) {
        string str = to_string(num);
        vector<int> odd, even;
        for (char c : str) {
            int digit = c - '0';
            if (digit % 2 == 0) even.push_back(digit);
            else odd.push_back(digit);
        }
        sort(odd.rbegin(), odd.rend());
        sort(even.rbegin(), even.rend());
        int o = 0, e = 0;
        for (int i = 0; i < str.size(); i++) {
            int digit = str[i] - '0';
            if (digit % 2 == 0) {
                str[i] = '0' + even[e++];
            } else {
                str[i] = '0' + odd[o++];
            }
        }
        return stoi(str);
    }
};

