    long long countGoodIntegers(int n, int k) {
        long long res = 0;
        vector<int> cnt(10, 0);
        cnt[0] = 1; // to avoid leading zeros
        for (int i = 0; i < n; ++i) {
            vector<int> nxt(cnt.size(), 0);
            for (int j = 0; j < 10; ++j) {
                for (int d = 0; d < 10; ++d) {
                    int num = (j * 10 + d) % k;
                    nxt[num] += cnt[j];
                }
            }
            cnt = nxt;
        }
        return cnt[0];
    }
};

class Solution {
public:
    long long validSubstringCount(string word1, string word2) {
        int n = word1.size(), m = word2.size();
        vector<int> count(26, 0), target(26, 0);
        for (char c : word2) target[c - 'a']++;
        long long res = 0;
        int left = 0, formed = 0;
        for (int right = 0; right < n; ++right) {
            count[word1[right] - 'a']++;
            if (count[word1[right] - 'a'] == target[word1[right] - 'a']) formed++;
            while (formed == target.size() && left <= right) {
                count[word1[left] - 'a']--;
                if (count[word1[left] - 'a'] < target[word1[left] - 'a']) formed--;
                res += n - right;
                left++;
            }
        }
        return res;
    }
};

class Solution {
public:
    char kthCharacter(long long k, vector<int>& operations) {
        long long length = 1;
        int shift = 0;
        for (int i = operations.size() - 1; i >= 0; --i) {
            if (operations[i] == 0) {
                if (k > length) k -= length;
                length /= 2;
            } else {
                shift = (shift + 1) % 26;
                if (k > length) k -= length;
                length /= 2;
            }
        }
        return 'a' + (k - 1 + shift) % 26;
    }
};

class Solution {
public:
    int countWinningSequences(string s) {
        const int MOD = 1e9 + 7;
        int n = s.size();
        vector<vector<long long>> dp(n, vector<long long>(3, 0));
        for (int j = 0; j < 3; ++j) {
            if (j != s[0] - 'F') {
                dp[0][j] = 1;
            }
        }
        for (int i = 1; i < n; ++i) {
            for (int j = 0; j < 3; ++j) {
                for (int k = 0; k < 3; ++k) {
                    if (k != j) {
                        int alice = s[i] - 'F';
                        int bob = j;
                        long long score = (alice == 0 && bob == 2) || (alice == 1 && bob == 0) || (alice == 2 && bob == 1) ? 1 : -1;
                        dp[i][j] = (dp[i][j] + dp[i - 1][k] * (score == 1 ? 1 : 0) + MOD) % MOD;
                    }
                }
            }
        }
        long long aliceScore = 0, bobScore = 0;
        for (int i = 0; i < n; ++i) {
            int alice = s[i] - 'F';
            for (int j = 0; j < 3; ++j) {
                int bob = j;
                if ((alice == 0 && bob == 2) || (alice == 1 && bob == 0) || (alice == 2 && bob == 1)) {
                    bobScore += dp[i][j];
                } else if ((alice == 0 && bob == 1) || (alice == 1 && bob == 2) || (alice == 2 && bob == 0)) {
                    aliceScore += dp[i][j];
                }
            }
        }
        return (bobScore > aliceScore ? bobScore - aliceScore : 0) % MOD;
    }
};

class Solution {
public:
    int lengthAfterTransformations(string s, int t, vector<int>& nums) {
        const int MOD = 1e9 + 7;
        vector<long long> count(26, 0);
        for (char c : s) {
            count[c - 'a']++;
        }

        vector<vector<long long>> transform_matrix(26, vector<long long>(26, 0));
        for (int i = 0; i < 26; i++) {
            int num = nums[i];
            for (int j = 1; j <= num; j++) {
                transform_matrix[(i + j) % 26][i]++;
            }
        }

        vector<vector<long long>> t_matrix = matrix_power(transform_matrix, t, MOD);

        vector<long long> result(26, 0);
        for (int i = 0; i < 26; i++) {
            for (int j = 0; j < 26; j++) {
                result[i] = (result[i] + t_matrix[i][j] * count[j]) % MOD;
            }
        }

        long long total_length = 0;
        for (int i = 0; i < 26; i++) {
            total_length = (total_length + result[i]) % MOD;
        }

        return total_length;
    }

    vector<vector<long long>> matrix_multiply(vector<vector<long long>>& a, vector<vector<long long>>& b, int MOD) {
        int n = a.size();
        vector<vector<long long>> result(n, vector<long long>(n, 0));
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                for (int k = 0; k < n; k++) {
                    result[i][j] = (result[i][j] + a[i][k] * b[k][j]) % MOD;
                }
            }
        }
        return result;
    }

    vector<vector<long long>> matrix_power(vector<vector<long long>>& matrix, int n, int MOD) {
        int size = matrix.size();
        vector<vector<long long>> result(size, vector<long long>(size, 0));
        for (int i = 0; i < size; i++) {
            result[i][i] = 1;
        }

        while (n > 0) {
            if (n % 2 == 1) {
                result = matrix_multiply(result, matrix, MOD);
            }
            matrix = matrix_multiply(matrix, matrix, MOD);
            n /= 2;
        }

        return result;
    }
};

class Solution {
public:
    int maxStability(int n, vector<vector<int>>& edges, int k) {
        vector<vector<pair<int, int>>> graph(n);
        vector<int> parent(n);
        for (int i = 0; i < n; ++i) parent[i] = i;

        vector<pair<int, int>> must_edges;
        int total_must_edges = 0;

        for (auto& edge : edges) {
            int u = edge[0], v = edge[1], strength = edge[2], must = edge[3];
            if (must == 1) {
                must_edges.emplace_back(strength, u * n + v);
                total_must_edges++;
            }
        }

        sort(must_edges.begin(), must_edges.end());
        for (auto& edge : must_edges) {
            int u = edge.second / n, v = edge.second % n;
            if (!unionSet(u, v, parent)) return -1;
        }

        if (total_must_edges != n - 1) {
            for (auto& edge : edges) {
                int u = edge[0], v = edge[1], strength = edge[2], must = edge[3];
                if (must == 0) graph[u].emplace_back(v, strength);
                if (must == 0) graph[v].emplace_back(u, strength);
            }
        } else {
            for (auto& edge : edges) {
                int u = edge[0], v = edge[1], strength = edge[2], must = edge[3];
                if (findSet(u, parent) != findSet(v, parent) && must == 0) {
                    graph[u].emplace_back(v, strength);
                    graph[v].emplace_back(u, strength);
                }
            }
        }

        priority_queue<pair<int, int>> pq;
        for (int i = 0; i < n; ++i) {
            for (auto& neighbor : graph[i]) {
                pq.emplace(neighbor.second, i * n + neighbor.first);
            }
        }

        int low = 1, high = 1e5 + 1;
        while (low < high) {
            int mid = (low + high + 1) / 2;
            if (check(mid, k, pq, parent, n)) low = mid;
            else high = mid - 1;
        }
        return low;
    }

    bool check(int mid, int k, priority_queue<pair<int, int>>& pq, vector<int>& parent, int n) {
        vector<int> new_parent(n);
        for (int i = 0; i < n; ++i) new_parent[i] = i;
        int count = 0;
        priority_queue<pair<int, int>> temp = pq;
        while (!temp.empty()) {
            auto edge = temp.top();
            temp.pop();
            int u = edge.second / n, v = edge.second % n;
            if (edge.first >= mid && unionSet(u, v, new_parent)) count++;
            else if (edge.first * 2 >= mid && k > 0 && unionSet(u, v, new_parent)) {
                count++;
                k--;
            }
        }
        return count == n - 1;
    }

    int findSet(int x, vector<int>& parent) {
        if (parent[x] != x) parent[x] = findSet(parent[x], parent);
        return parent[x];
    }

    bool unionSet(int x, int y, vector<int>& parent) {
        int xs = findSet(x, parent), ys = findSet(y, parent);
        if (xs == ys) return false;
        parent[xs] = ys;
        return true;
    }
};

class Solution {
public:
    int minStable(vector<int>& nums, int maxC) {
        int n = nums.size();
        int l = 0, cnt = 0;
        for (int r = 0; r < n; ++r) {
            if (nums[r] % 2 != 0) {
                ++cnt;
            }
            while (cnt > maxC) {
                if (nums[l++] % 2 != 0) {
                    --cnt;
                }
            }
        }
        return n - l;
    }
};

