            char s = secret.charAt(i);
            char g = guess.charAt(i);
            if (s == g) {
                bulls++;
            } else {
                countSecret[s - '0']++;
                countGuess[g - '0']++;
            }
        }
        int cows = 0;
        for (int i = 0; i < 10; i++) {
            cows += Math.min(countSecret[i], countGuess[i]);
        }
        return bulls + "A" + cows + "B";
    }
}

class Solution {
    public List<String> removeInvalidParentheses(String s) {
        List<String> result = new ArrayList<>();
        int removeCount = getMinRemoveCount(s);
        bfs(s, removeCount, result);
        return result;
    }

    private int getMinRemoveCount(String s) {
        int count = 0;
        int open = 0;
        for (char c : s.toCharArray()) {
            if (c == '(') {
                open++;
            } else if (c == ')') {
                if (open == 0) {
                    count++;
                } else {
                    open--;
                }
            }
        }
        return count + open;
    }

    private void bfs(String s, int removeCount, List<String> result) {
        Queue<String> queue = new LinkedList<>();
        Set<String> visited = new HashSet<>();
        queue.offer(s);
        visited.add(s);
        boolean found = false;
        while (!queue.isEmpty()) {
            String current = queue.poll();
            if (isValid(current)) {
                found = true;
                result.add(current);
            }
            if (found) {
                continue;
            }
            for (int i = 0; i < current.length(); i++) {
                if (current.charAt(i) != '(' && current.charAt(i) != ')') {
                    continue;
                }
                String next = current.substring(0, i) + current.substring(i + 1);
                if (!visited.contains(next)) {
                    queue.offer(next);
                    visited.add(next);
                }
            }
        }
    }

    private boolean isValid(String s) {
        int count = 0;
        for (char c : s.toCharArray()) {
            if (c == '(') {
                count++;
            } else if (c == ')') {
                count--;
                if (count < 0) {
                    return false;
                }
            }
        }
        return count == 0;
    }
}

