        int left = 0;
        for (int right = 0; right <= chars.length; right++) {
            if (right == chars.length || chars[right] == ' ') {
                int l = left, r = right - 1;
                while (l < r) {
                    char temp = chars[l];
                    chars[l++] = chars[r];
                    chars[r--] = temp;
                }
                left = right + 1;
            }
        }
        return new String(chars);
    }
}

class Solution {
    public int findUnsortedSubarray(int[] nums) {
        int[] sortedNums = nums.clone();
        Arrays.sort(sortedNums);
        int start = nums.length, end = 0;
        for (int i = 0; i < nums.length; i++) {
            if (nums[i] != sortedNums[i]) {
                start = Math.min(start, i);
                end = Math.max(end, i);
            }
        }
        return end - start >= 0 ? end - start + 1 : 0;
    }
}

class Solution {
    public int findIntegers(int n) {
        int[] f = new int[31];
        f[0] = 1;
        f[1] = 1;
        for (int i = 2; i < 31; ++i) {
            f[i] = f[i - 1] + f[i - 2];
        }
        int ans = 0, pre = 0;
        for (int i = 29; i >= 0; --i) {
            int val = 1 << i;
            if ((n & val) != 0) {
                ans += f[i + 1];
                if (pre == 1) {
                    return ans;
                }
                pre = 1;
            } else {
                pre = 0;
            }
        }
        return ans + 1;
    }
}

class Solution {
    public String solveEquation(String equation) {
        String[] parts = equation.split("=");
        int[] left = calculate(parts[0]);
        int[] right = calculate(parts[1]);
        int a = left[0] - right[0];
        int b = right[1] - left[1];
        if (a == 0) {
            if (b == 0) return "Infinite solutions";
            else return "No solution";
        }
        int x = b / a;
        return "x=" + x;
    }

    private int[] calculate(String s) {
        int coefficient = 0, constant = 0;
        int sign = 1;
        int num = 0;
        boolean hasX = false;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (Character.isDigit(c)) {
                num = num * 10 + c - '0';
            } else if (c == 'x') {
                if (num == 0 && !hasX) num = 1;
                coefficient += sign * num;
                num = 0;
                hasX = true;
            } else if (c == '+') {
                constant += sign * num;
                num = 0;
                sign = 1;
                hasX = false;
            } else if (c == '-') {
                constant += sign * num;
                num = 0;
                sign = -1;
                hasX = false;
            }
        }
        constant += sign * num;
        return new int[] {coefficient, constant};
    }
}

