class Solution {
    public int minSwapsCouples(int[] row) {
        int n = row.length;
        int[] partner = new int[n];
        int[] pos = new int[n];
        for (int i = 0; i < n; i++) {
            partner[i] = i % 2 == 0 ? i + 1 : i - 1;
            pos[row[i]] = i;
        }
        int swaps = 0;
        for (int i = 0; i < n; i += 2) {
            if (row[i + 1] != partner[row[i]]) {
                int x = pos[partner[row[i]]];
                int temp = row[i + 1];
                row[i + 1] = row[x];
                row[x] = temp;
                pos[temp] = x;
                pos[row[i + 1]] = i + 1;
                swaps++;
            }
        }
        return swaps;
    }
}

class Solution {
    public boolean canTransform(String start, String result) {
        if (!start.replace("X", "").equals(result.replace("X", ""))) {
            return false;
        }
        int n = start.length();
        int i = 0, j = 0;
        while (i < n && j < n) {
            while (i < n && start.charAt(i) == 'X') i++;
            while (j < n && result.charAt(j) == 'X') j++;
            if (i == n || j == n) return i == n && j == n;
            if (start.charAt(i) != result.charAt(j)) return false;
            if ((start.charAt(i) == 'L' && i < j) || (start.charAt(i) == 'R' && i > j)) return false;
            i++; j++;
        }
        return true;
    }
}

class Solution {
    public int racecar(int target) {
        int[] dp = new int[target + 1];
        for (int i = 1; i <= target; i++) {
            dp[i] = Integer.MAX_VALUE;
            int m = 1, p = 1;
            for (int j = 0; p < i; j++, m *= 2, p += m) {
                dp[i] = Math.min(dp[i], j + 1 + (i - p > 0 ? dp[i - p] : 0));
                if (p > i) {
                    dp[i] = Math.min(dp[i], j + 1 + dp[p - i] + 1);
                }
            }
        }
        return dp[target];
    }
}

