class Solution {
    public int leastOpsExpressTarget(int x, int target) {
        if (x == target) return 0;
        if (x > target) return Math.min(2, target);
        long cur = x;
        int count = 0;
        while (cur < target) {
            cur *= x;
            count++;
        }
        if (cur == target) return count;
        long pre = cur / x;
        long diff1 = cur - target;
        long diff2 = target - pre;
        int res1 = count + (int) Math.ceil((double) diff1 / x);
        int res2 = count - 1 + (int) Math.ceil((double) diff2 / x);
        return Math.min(res1, res2);
    }
}

class Solution {
    public int[] numsSameConsecDiff(int n, int k) {
        List<Integer> result = new ArrayList<>();
        for (int i = 1; i <= 9; i++) {
            dfs(n - 1, i, k, result);
        }
        int[] res = new int[result.size()];
        for (int i = 0; i < result.size(); i++) {
            res[i] = result.get(i);
        }
        return res;
    }

    private void dfs(int n, int num, int k, List<Integer> result) {
        if (n == 0) {
            result.add(num);
            return;
        }
        int lastDigit = num % 10;
        if (lastDigit + k <= 9) {
            dfs(n - 1, num * 10 + lastDigit + k, k, result);
        }
        if (k != 0 && lastDigit - k >= 0) {
            dfs(n - 1, num * 10 + lastDigit - k, k, result);
        }
    }
}

class Solution {
    public boolean isRationalEqual(String s, String t) {
        return normalize(s).equals(normalize(t));
    }

    private String normalize(String s) {
        int i = s.indexOf('(');
        if (i != -1) {
            String repeating = s.substring(i + 1, s.length() - 1);
            s = s.substring(0, i) + repeating.repeat(20);
        }
        while (s.length() > 10 && s.charAt(s.length() - 1) == '0') {
            s = s.substring(0, s.length() - 1);
        }
        if (s.endsWith(".")) {
            s = s.substring(0, s.length() - 1);
        }
        return s;
    }
}

class Solution {
    public String strWithout3a3b(int a, int b) {
        StringBuilder sb = new StringBuilder();
        while (a > 0 || b > 0) {
            if (a > b) {
                if (a >= 2 && b > 0) {
                    sb.append("aab");
                    a -= 2;
                    b -= 1;
                } else {
                    sb.append('a');
                    a -= 1;
                }
            } else {
                if (b >= 2 && a > 0) {
                    sb.append("bba");
                    b -= 2;
                    a -= 1;
                } else {
                    sb.append('b');
                    b -= 1;
                }
            }
        }
        return sb.toString();
    }
}

class Solution {
    public int clumsy(int n) {
        if (n <= 2) return n;
        int result = n;
        n--;
        int count = 0;
        while (n > 0) {
            if (count % 4 == 0) {
                result *= n;
            } else if (count % 4 == 1) {
                result /= n;
            } else if (count % 4 == 2) {
                result += n;
            } else {
                result -= n;
            }
            count++;
            n--;
        }
        return result;
    }
}

