        while (j < n) {
            int k = 0;
            while (j + k < n && s.charAt(i + k) == s.charAt(j + k)) k++;
            if (j + k < n && s.charAt(i + k) < s.charAt(j + k)) i = (i + k + 1 > j) ? j : i + k + 1;
            j = (j + k + 1 > i) ? j + k + 1 : j + 1;
        }
        return s.substring(i);
    }
}

class Solution {
    public ListNode removeZeroSumSublists(ListNode head) {
        ListNode dummy = new ListNode(0);
        dummy.next = head;
        int prefix = 0;
        Map<Integer, ListNode> seen = new HashMap<>();
        seen.put(0, dummy);
        while (head != null) {
            prefix += head.val;
            if (seen.containsKey(prefix)) {
                ListNode node = seen.get(prefix);
                ListNode tmp = node.next;
                int tmpPrefix = prefix + tmp.val;
                while (tmp != head) {
                    seen.remove(tmpPrefix);
                    tmp = tmp.next;
                    tmpPrefix += tmp.val;
                }
                node.next = head.next;
            } else {
                seen.put(prefix, head);
            }
            head = head.next;
        }
        return dummy.next;
    }
}

class Solution {
    public String reverseParentheses(String s) {
        java.util.Stack<StringBuilder> stack = new java.util.Stack<>();
        StringBuilder res = new StringBuilder();
        for (char c : s.toCharArray()) {
            if (c == '(') {
                stack.push(res);
                res = new StringBuilder();
            } else if (c == ')') {
                res.reverse();
                res = stack.pop().append(res);
            } else {
                res.append(c);
            }
        }
        return res.toString();
    }
}

