            while (count[0] > 0 && count[1] > 0 && count[2] > 0) {
                res += s.length() - right;
                count[s.charAt(left++) - 'a']--;
            }
        }
        return res;
    }
}

class Solution {
    public String sortString(String s) {
        int[] count = new int[26];
        for (char c : s.toCharArray()) {
            count[c - 'a']++;
        }
        StringBuilder result = new StringBuilder();
        while (result.length() < s.length()) {
            for (int i = 0; i < 26; i++) {
                if (count[i] > 0) {
                    result.append((char) ('a' + i));
                    count[i]--;
                }
            }
            for (int i = 25; i >= 0; i--) {
                if (count[i] > 0) {
                    result.append((char) ('a' + i));
                    count[i]--;
                }
            }
        }
        return result.toString();
    }
}

class Solution {
    public int countLargestGroup(int n) {
        int[] count = new int[37]; // maximum sum of digits for n <= 10^4 is 9*4 = 36
        int maxCount = 0, result = 0;
        for (int i = 1; i <= n; i++) {
            int sum = 0, num = i;
            while (num > 0) {
                sum += num % 10;
                num /= 10;
            }
            count[sum]++;
            if (count[sum] > maxCount) {
                maxCount = count[sum];
                result = 1;
            } else if (count[sum] == maxCount) {
                result++;
            }
        }
        return result;
    }
}

class Solution {
    public boolean canConstruct(String s, int k) {
        int[] count = new int[26];
        for (char c : s.toCharArray()) {
            count[c - 'a']++;
        }
        int oddCount = 0;
        for (int i : count) {
            if (i % 2 != 0) {
                oddCount++;
            }
        }
        return oddCount <= k && s.length() >= k;
    }
}

class Solution {
    public int numberOfArrays(String s, int k) {
        int MOD = (int) (1e9 + 7);
        int n = s.length();
        long[] dp = new long[n + 1];
        dp[0] = 1;
        for (int i = 1; i <= n; i++) {
            long cur = 0;
            for (int j = i; j >= 1 && i - j + 1 <= String.valueOf(k).length(); j--) {
                if (s.charAt(j - 1) == '0') break;
                long num = Long.parseLong(s.substring(j - 1, i));
                if (num <= k) cur = (cur + dp[j - 1]) % MOD;
            }
            dp[i] = cur;
        }
        return (int) dp[n];
    }
}

class Solution {
    public int maxScore(String s) {
        int ones = 0;
        for (char c : s.toCharArray()) {
            if (c == '1') ones++;
        }
        int maxScore = 0, zeros = 0;
        for (int i = 0; i < s.length() - 1; i++) {
            if (s.charAt(i) == '0') zeros++;
            else ones--;
            maxScore = Math.max(maxScore, zeros + ones);
        }
        return maxScore;
    }
}

