class Solution {
    public boolean canConvertString(String s, String t, int k) {
        if (s.length() != t.length()) return false;
        int[] count = new int[26];
        for (int i = 0; i < s.length(); i++) {
            int diff = (t.charAt(i) - s.charAt(i) + 26) % 26;
            count[diff]++;
        }
        for (int i = 1; i < 26; i++) {
            if (count[i] > 0) {
                int requiredMoves = i + (count[i] - 1) * 26;
                if (requiredMoves > k) return false;
            }
        }
        return true;
    }
}

class Solution {
    public int minInsertions(String s) {
        int count = 0, open = 0;
        for (char c : s.toCharArray()) {
            if (c == '(') {
                open++;
            } else {
                if (open == 0) count++;
                else open--;
                if (count % 2 == 1) {
                    count++;
                }
            }
        }
        return count + 2 * open;
    }
}

