            if (Character.isDigit(c)) {
                digits.append(c);
            }
        }
        StringBuilder result = new StringBuilder();
        while (digits.length() > 4) {
            result.append(digits.substring(0, 3)).append("-");
            digits.delete(0, 3);
        }
        if (digits.length() == 4) {
            result.append(digits.substring(0, 2)).append("-").append(digits.substring(2));
        } else {
            result.append(digits);
        }
        return result.toString();
    }
}

class Solution {
    public String maximumBinaryString(String binary) {
        int countZero = 0, firstZeroIndex = -1;
        char[] chars = binary.toCharArray();
        for (int i = 0; i < chars.length; i++) {
            if (chars[i] == '0') {
                countZero++;
                if (firstZeroIndex == -1) {
                    firstZeroIndex = i;
                }
            }
        }
        if (countZero == 0) {
            return binary;
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < chars.length; i++) {
            if (i < firstZeroIndex) {
                sb.append('1');
            } else if (i >= firstZeroIndex && i < firstZeroIndex + countZero - 1) {
                sb.append('1');
            } else if (i == firstZeroIndex + countZero - 1) {
                sb.append('0');
            } else if (i > firstZeroIndex + countZero - 1) {
                sb.append(chars[i]);
            }
        }
        return sb.toString();
    }
}

class Solution {
    public int minimumLength(String s) {
        int left = 0, right = s.length() - 1;
        while (left < right && s.charAt(left) == s.charAt(right)) {
            char c = s.charAt(left);
            while (left <= right && s.charAt(left) == c) left++;
            while (left <= right && s.charAt(right) == c) right--;
        }
        return right - left + 1;
    }
}

class Solution {
    public String largestMerge(String word1, String word2) {
        StringBuilder merge = new StringBuilder();
        while (!word1.isEmpty() || !word2.isEmpty()) {
            if (!word1.isEmpty() && !word2.isEmpty()) {
                if (word1.compareTo(word2) > 0) {
                    merge.append(word1.charAt(0));
                    word1 = word1.substring(1);
                } else {
                    merge.append(word2.charAt(0));
                    word2 = word2.substring(1);
                }
            } else if (!word1.isEmpty()) {
                merge.append(word1);
                word1 = "";
            } else {
                merge.append(word2);
                word2 = "";
            }
        }
        return merge.toString();
    }
