class Solution {
    public boolean[] friendRequests(int n, int[][] restrictions, int[][] requests) {
        UnionFind uf = new UnionFind(n);
        boolean[] result = new boolean[requests.length];
        for (int i = 0; i < requests.length; i++) {
            int u = requests[i][0], v = requests[i][1];
            boolean valid = true;
            for (int[] r : restrictions) {
                int x = r[0], y = r[1];
                if ((uf.find(u) == uf.find(x) && uf.find(v) == uf.find(y)) ||
                    (uf.find(u) == uf.find(y) && uf.find(v) == uf.find(x))) {
                    valid = false;
                    break;
                }
            }
            result[i] = valid;
            if (valid) uf.union(u, v);
        }
        return result;
    }

    class UnionFind {
        int[] parent;
        public UnionFind(int n) {
            parent = new int[n];
            for (int i = 0; i < n; i++) parent[i] = i;
        }
        public int find(int x) {
            if (parent[x] != x) parent[x] = find(parent[x]);
            return parent[x];
        }
        public void union(int x, int y) {
            int rootX = find(x), rootY = find(y);
            if (rootX != rootY) parent[rootX] = rootY;
        }
    }
}

class Solution {
    public List<Integer> findAllPeople(int n, int[][] meetings, int firstPerson) {
        Arrays.sort(meetings, (a, b) -> a[2] - b[2]);
        UnionFind uf = new UnionFind(n);
        uf.union(0, firstPerson);
        int i = 0;
        while (i < meetings.length) {
            int time = meetings[i][2];
            List<int[]> peopleAtTime = new ArrayList<>();
            while (i < meetings.length && meetings[i][2] == time) {
                peopleAtTime.add(meetings[i]);
                i++;
            }
            for (int[] meeting : peopleAtTime) {
                uf.union(meeting[0], meeting[1]);
            }
            for (int[] meeting : peopleAtTime) {
                if (!uf.connected(0, meeting[0])) {
                    uf.reset(meeting[0]);
                    uf.reset(meeting[1]);
                }
            }
        }
        List<Integer> result = new ArrayList<>();
        for (int j = 0; j < n; j++) {
            if (uf.connected(0, j)) {
                result.add(j);
            }
        }
        return result;
    }

    class UnionFind {
        int[] parent;
        int[] rank;

        public UnionFind(int n) {
            parent = new int[n];
            rank = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
            }
        }

        public int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }

        public void union(int x, int y) {
            int rootX = find(x);
            int rootY = find(y);
            if (rootX != rootY) {
                if (rank[rootX] > rank[rootY]) {
                    parent[rootY] = rootX;
                } else if (rank[rootX] < rank[rootY]) {
                    parent[rootX] = rootY;
                } else {
                    parent[rootY] = rootX;
                    rank[rootX]++;
                }
            }
        }

        public boolean connected(int x, int y) {
            return find(x) == find(y);
        }

        public void reset(int x) {
            parent[x] = x;
        }
    }
}

class Solution {
    public int wordCount(String[] startWords, String[] targetWords) {
        Set<Integer> startWordSet = new HashSet<>();
        for (String word : startWords) {
            int mask = 0;
            for (char c : word.toCharArray()) {
                mask |= 1 << (c - 'a');
            }
            startWordSet.add(mask);
        }

        int count = 0;
        for (String word : targetWords) {
            int mask = 0;
            for (char c : word.toCharArray()) {
                mask |= 1 << (c - 'a');
            }
            for (char c : word.toCharArray()) {
                if (startWordSet.contains(mask ^ (1 << (c - 'a')))) {
                    count++;
                    break;
                }
            }
        }
        return count;
    }
}

class Solution {
    public long mostPoints(int[][] questions) {
        int n = questions.length;
        long[] dp = new long[n + 1];
        for (int i = n - 1; i >= 0; i--) {
            int points = questions[i][0];
            int brainpower = questions[i][1];
            int next = Math.min(i + brainpower + 1, n);
            dp[i] = Math.max(dp[i + 1], points + dp[next]);
        }
        return dp[0];
    }
}

class Solution {
    public List<Integer> maxScoreIndices(int[] nums) {
        int n = nums.length;
        int totalOnes = 0;
        for (int num : nums) {
            totalOnes += num;
        }
        int maxScore = totalOnes;
        int currentScore = totalOnes;
        List<Integer> result = new ArrayList<>();
        result.add(0);
        for (int i = 0; i < n; i++) {
            if (nums[i] == 0) {
                currentScore++;
            } else {
                currentScore--;
            }
            if (currentScore > maxScore) {
                maxScore = currentScore;
                result.clear();
                result.add(i + 1);
            } else if (currentScore == maxScore) {
                result.add(i + 1);
            }
        }
        return result;
    }
}

class Solution {
    public int countOperations(int num1, int num2) {
        int count = 0;
        while (num1 != 0 && num2 != 0) {
            if (num1 >= num2) {
                count += num1 / num2;
                num1 %= num2;
            } else {
                count += num2 / num1;
                num2 %= num1;
            }
        }
        return count;
    }
}

class Solution {
    public List<Long> maximumEvenSplit(long finalSum) {
        List<Long> result = new ArrayList<>();
        if (finalSum % 2 != 0) return result;
        long sum = 0;
        long num = 2;
        while (sum + num <= finalSum) {
            sum += num;
            result.add(num);
            num += 2;
        }
        long diff = finalSum - sum;
        result.set(result.size() - 1, result.get(result.size() - 1) + diff);
        return result;
    }
}

class Solution {
    public int countEven(int num) {
        int count = 0;
        for (int i = 1; i <= num; i++) {
            int sum = 0;
            int n = i;
            while (n > 0) {
                sum += n % 10;
                n /= 10;
            }
            if (sum % 2 == 0) {
                count++;
            }
        }
        return count;
    }
}

