class Solution {
    public int peopleAwareOfSecret(int n, int delay, int forget) {
        long[] dp = new long[n + 1];
        dp[1] = 1;
        long sum = 0;
        long mod = (long) (1e9 + 7);
        for (int i = 2; i <= n; i++) {
            if (i >= forget) {
                sum = (sum - dp[i - forget + 1] + mod) % mod;
            }
            if (i >= delay + 1) {
                sum = (sum + dp[i - delay]) % mod;
            }
            dp[i] = sum;
        }
        long res = 0;
        for (int i = n - forget + 1; i <= n; i++) {
            res = (res + dp[i]) % mod;
        }
        return (int) res;
    }
}

class Solution {
    public int latestTimeCatchTheBus(int[] buses, int[] passengers, int capacity) {
        Arrays.sort(buses);
        Arrays.sort(passengers);
        int i = 0, j = 0;
        while (i < buses.length && j < passengers.length) {
            if (passengers[j] <= buses[i]) {
                j++;
                if (j % capacity == 0) i++;
            } else {
                i++;
            }
        }
        int latest = (i < buses.length) ? buses[i] : buses[buses.length - 1];
        while (j > 0 && passengers[j - 1] == latest) {
            j--;
            latest--;
        }
        return latest;
    }
}

class Solution {
    public long minSumSquareDiff(int[] nums1, int[] nums2, int k1, int k2) {
        int n = nums1.length;
        long[] diffs = new long[n];
        for (int i = 0; i < n; i++) {
            diffs[i] = Math.abs((long) nums1[i] - nums2[i]);
        }
        Arrays.sort(diffs);
        long total = k1 + k2;
        long res = 0;
        for (int i = n - 1; i >= 0; i--) {
            long d = diffs[i];
            if (total >= d) {
                total -= d;
                res += d * d;
            } else {
                res += (d - total) * (d - total);
                break;
            }
        }
        return res;
    }
}

