class Solution {
    public boolean equalFrequency(String word) {
        int[] freq = new int[26];
        for (char c : word.toCharArray()) {
            freq[c - 'a']++;
        }
        int count = 0;
        int maxFreq = 0, minFreq = word.length();
        int maxCount = 0, minCount = 0;
        for (int f : freq) {
            if (f > 0) {
                count++;
                maxFreq = Math.max(maxFreq, f);
                minFreq = Math.min(minFreq, f);
            }
        }
        for (int f : freq) {
            if (f == maxFreq) maxCount++;
            if (f == minFreq && f > 0) minCount++;
        }
        return (maxFreq - minFreq == 1 && maxCount == 1) || (minFreq == 1 && minCount == 1) || (count == 1);
    }
}

class Solution {
    public int minimizeXor(int num1, int num2) {
        int setBitsNum2 = Integer.bitCount(num2);
        int result = 0;
        for (int i = 30; i >= 0; i--) {
            int mask = 1 << i;
            if ((num1 & mask) != 0) {
                if (setBitsNum2 > 0) {
                    result |= mask;
                    setBitsNum2--;
                }
            } else {
                if (setBitsNum2 > 0) {
                    result |= mask;
                    setBitsNum2--;
                }
            }
        }
        return result;
    }
}

class Solution {
    public int hardestWorker(int n, int[][] logs) {
        int maxTime = 0;
        int minId = n;
        int prevTime = 0;
        for (int[] log : logs) {
            int id = log[0];
            int time = log[1];
            int duration = time - prevTime;
            if (duration > maxTime || (duration == maxTime && id < minId)) {
                maxTime = duration;
                minId = id;
            }
            prevTime = time;
        }
        return minId;
    }
}

class Solution {
    public String robotWithString(String s) {
        int n = s.length();
        char[] arr = s.toCharArray();
        char[] minArr = new char[n];
        minArr[n - 1] = arr[n - 1];
        for (int i = n - 2; i >= 0; i--) {
            minArr[i] = (char) Math.min(arr[i], minArr[i + 1]);
        }
        StringBuilder sb = new StringBuilder();
        java.util.Stack<Character> stack = new java.util.Stack<>();
        for (int i = 0; i < n; i++) {
            stack.push(arr[i]);
            while (!stack.isEmpty() && stack.peek() <= minArr[i]) {
                sb.append(stack.pop());
            }
        }
        return sb.toString();
    }
}

class Solution {
    public int findMaxK(int[] nums) {
        Arrays.sort(nums);
        int left = 0, right = nums.length - 1;
        while (left < right) {
            int sum = nums[left] + nums[right];
            if (sum == 0) return nums[right];
            else if (sum < 0) left++;
            else right--;
        }
        return -1;
    }
}

class Solution {
