        int start1 = toMinutes(event1[0]);
        int end1 = toMinutes(event1[1]);
        int start2 = toMinutes(event2[0]);
        int end2 = toMinutes(event2[1]);
        return !(end1 < start2 || end2 < start1);
    }

    private int toMinutes(String time) {
        String[] parts = time.split(":");
        return Integer.parseInt(parts[0]) * 60 + Integer.parseInt(parts[1]);
    }
}

class Solution {
    public int countGoodStrings(int low, int high, int zero, int one) {
        int MOD = (int) (1e9 + 7);
        int[] dp = new int[high + 1];
        dp[0] = 1;
        int result = 0;
        for (int i = 1; i <= high; i++) {
            if (i >= zero) {
                dp[i] = (dp[i] + dp[i - zero]) % MOD;
            }
            if (i >= one) {
                dp[i] = (dp[i] + dp[i - one]) % MOD;
            }
            if (i >= low) {
                result = (result + dp[i]) % MOD;
            }
        }
        return result;
    }
}

class Solution {
    public int maxPalindromes(String s, int k) {
        int n = s.length();
        boolean[][] dp = new boolean[n][n];
        for (int i = 0; i < n; i++) {
            dp[i][i] = true;
        }
        for (int length = 2; length <= n; length++) {
            for (int i = 0; i <= n - length; i++) {
                int j = i + length - 1;
                if (length == 2) {
                    dp[i][j] = s.charAt(i) == s.charAt(j);
                } else {
                    dp[i][j] = s.charAt(i) == s.charAt(j) && dp[i + 1][j - 1];
                }
            }
        }
        int[] f = new int[n + 1];
        for (int i = 0; i < n; i++) {
            f[i + 1] = f[i];
            if (i >= k - 1 && dp[i - k + 1][i]) {
                f[i + 1] = Math.max(f[i + 1], f[i - k + 1] + 1);
            }
            if (i > 0) {
                f[i + 1] = Math.max(f[i + 1], f[i]);
            }
        }
        return f[n];
    }
}

class Solution {
    public int bestClosingTime(String customers) {
        int n = customers.length();
        int[] prefixSum = new int[n + 1];
        for (int i = 0; i < n; i++) {
            prefixSum[i + 1] = prefixSum[i] + (customers.charAt(i) == 'Y' ? 1 : 0);
        }
        int minPenalty = Integer.MAX_VALUE;
        int bestHour = -1;
        for (int i = 0; i <= n; i++) {
            int penalty = (prefixSum[n] - prefixSum[i]) + (i - prefixSum[i]);
            if (penalty < minPenalty) {
                minPenalty = penalty;
                bestHour = i;
            }
        }
        return bestHour;
    }
}

class Solution {
    public int appendCharacters(String s, String t) {
