}

class Solution {
    public int smallestValue(int n) {
        while (true) {
            int sum = 0, temp = n;
            for (int i = 2; i * i <= temp; i++) {
                while (temp % i == 0) {
                    sum += i;
                    temp /= i;
                }
            }
            if (temp > 1) sum += temp;
            if (sum == n) return n;
            n = sum;
        }
    }
}

class Solution {
    public String categorizeBox(int length, int width, int height, int mass) {
        boolean isBulky = (long)length >= Math.pow(10, 4) || (long)width >= Math.pow(10, 4) || (long)height >= Math.pow(10, 4) || (long)length * width * height >= Math.pow(10, 9);
        boolean isHeavy = mass >= 100;
        if (isBulky && isHeavy) return "Both";
        if (isBulky) return "Bulky";
        if (isHeavy) return "Heavy";
        return "Neither";
    }
}

class Solution {
    public int alternateDigitSum(int n) {
        int sum = 0;
        boolean isPositive = true;
        while (n > 0) {
            int digit = n % 10;
            sum += isPositive ? digit : -digit;
            isPositive = !isPositive;
            n /= 10;
        }
        return isPositive ? -sum : sum;
    }
}

class Solution {
