class Solution {
    public int[] evenOddBit(int n) {
        int even = 0, odd = 0;
        int index = 0;
        while (n > 0) {
            if ((n & 1) == 1) {
                if (index % 2 == 0) even++;
                else odd++;
            }
            n >>= 1;
            index++;
        }
        return new int[] {even, odd};
    }
}

class Solution {
    public int maximumCostSubstring(String s, String chars, int[] vals) {
        int[] charVals = new int[26];
        for (int i = 0; i < 26; i++) {
            charVals[i] = i + 1;
        }
        for (int i = 0; i < chars.length(); i++) {
            charVals[chars.charAt(i) - 'a'] = vals[i];
        }
        int maxCost = 0, currCost = 0;
        for (char c : s.toCharArray()) {
            currCost = Math.max(charVals[c - 'a'], currCost + charVals[c - 'a']);
            maxCost = Math.max(maxCost, currCost);
        }
        return maxCost;
    }
}

class Solution {
    public int findTheLongestBalancedSubstring(String s) {
        int maxLength = 0;
        for (int i = 0; i < s.length(); i++) {
            int zeros = 0, ones = 0;
            for (int j = i; j < s.length(); j++) {
                if (s.charAt(j) == '0') {
                    zeros++;
                } else {
                    ones++;
                }
                if (zeros == ones) {
                    maxLength = Math.max(maxLength, ones + zeros);
                } else if (ones > zeros) {
                    break;
                }
            }
        }
        return maxLength;
    }
}

class Solution {
    public int addMinimum(String word) {
        int count = 0, state = 0;
        for (char c : word.toCharArray()) {
            if (c == 'a') {
                if (state == 2) count += 2;
                else if (state == 1) count += 1;
                state = 1;
            } else if (c == 'b') {
                if (state == 0) count += 1;
                else if (state == 2) count += 2;
                state = 2;
            } else {
                if (state != 2) count += (2 - state);
                state = 0;
            }
        }
        return count + state;
    }
}

class Solution {
    public long maximumOr(int[] nums, int k) {
        long res = 0, mask = 0;
        for (int num : nums) {
            mask |= num;
        }
        for (int i = 0; i < nums.length; i++) {
            res = Math.max(res, (long) (nums[i] << k) | (mask & ~nums[i]));
        }
        return res;
    }
}

class Solution {
