class Solution {
    public int makeTheIntegerZero(int num1, int num2) {
        long n1 = num1;
        long n2 = num2;
        for (int i = 0; i <= 30; i++) {
            if ((n1 - i * n2) >= i && (n1 - i * n2) >= 0 && (Long.bitCount(n1 - i * n2) <= i)) {
                return i;
            }
        }
        return -1;
    }
}

class Solution {
    public int numberOfWays(int n, int x) {
        int mod = (int) (1e9 + 7);
        int[] dp = new int[n + 1];
        dp[0] = 1;
        for (int i = 1; (int) Math.pow(i, x) <= n; i++) {
            int num = (int) Math.pow(i, x);
            for (int j = n; j >= num; j--) {
                dp[j] = (dp[j] + dp[j - num]) % mod;
            }
        }
        return dp[n];
    }
}

