class Solution {
    public int numberOfWays(int n, int x, int y) {
        final int MOD = (int) (1e9 + 7);
        int[][] dp = new int[n + 1][x + 1];
        dp[0][0] = 1;
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= x; j++) {
                dp[i][j] = (int) ((dp[i][j - 1] + (long) dp[i - 1][j - 1] * j) % MOD);
            }
        }
        int totalWays = (int) ((long) dp[n][x] * pow(y, x, MOD) % MOD);
        return totalWays;
    }

    private int pow(int base, int exponent, int mod) {
        int result = 1;
        while (exponent > 0) {
            if ((exponent & 1) == 1) {
                result = (int) ((long) result * base % mod);
            }
            base = (int) ((long) base * base % mod);
            exponent >>= 1;
        }
        return result;
    }
}

class Solution {
    public int countWinningSequences(String s) {
        int n = s.length();
        int MOD = (int) (1e9 + 7);
        long[][] dp = new long[n][3];
        int prev = -1;
        for (int i = 0; i < n; i++) {
            int curr = getState(s.charAt(i));
            if (i == 0) {
                dp[i][0] = dp[i][1] = dp[i][2] = 1;
            } else {
                for (int j = 0; j < 3; j++) {
                    for (int k = 0; k < 3; k++) {
                        if (k == prev) continue;
                        if (getWinner(curr, k) == 1) {
                            dp[i][k] = (dp[i][k] + dp[i - 1][j]) % MOD;
                        }
                    }
                }
            }
            prev = curr;
        }
        long alice = 0, bob = 0;
        for (int i = 0; i < n; i++) {
            int aliceMove = getState(s.charAt(i));
            for (int bobMove = 0; bobMove < 3; bobMove++) {
                int winner = getWinner(aliceMove, bobMove);
                if (winner == 1) bob++;
                else if (winner == -1) alice++;
            }
        }
        long total = 0;
        for (int i = 0; i < 3; i++) {
            total = (total + dp[n - 1][i]) % MOD;
        }
        long ans = (total + MOD - pow(2, n, MOD)) % MOD;
        return (int) ans;
    }

    private int getState(char c) {
        if (c == 'F') return 0;
        if (c == 'W') return 1;
        return 2;
    }

    private int getWinner(int alice, int bob) {
        if (alice == bob) return 0;
        if ((alice == 0 && bob == 2) || (alice == 1 && bob == 0) || (alice == 2 && bob == 1)) return -1;
        return 1;
    }

    private long pow(int x, int n, int mod) {
        long res = 1;
        long a = x;
        while (n > 0) {
            if ((n & 1) == 1) res = (res * a) % mod;
            a = (a * a) % mod;
            n >>= 1;
        }
        return res;
    }
}

class Solution {
    public int possibleStringCount(String word, int k) {
        int n = word.length();
        int MOD = (int) (1e9 + 7);
        long res = 1;
        int count = 1;
        for (int i = 1; i < n; i++) {
            if (word.charAt(i) == word.charAt(i - 1)) {
                count++;
            } else {
                res = res * Math.max(1, count - 1) % MOD;
                count = 1;
            }
        }
        res = res * Math.max(1, count - 1) % MOD;
        long ans = 0;
        for (int i = k; i <= n; i++) {
            ans = (ans + comb(n - i + countSegments(word) - 1, countSegments(word) - 1, MOD)) % MOD;
        }
        return (int) ans;
    }

    private int countSegments(String word) {
        int count = 1;
        for (int i = 1; i < word.length(); i++) {
            if (word.charAt(i) != word.charAt(i - 1)) {
                count++;
            }
        }
        return count;
    }

    private long comb(int n, int k, int MOD) {
        if (k > n) return 0;
        long res = 1;
        for (int i = 0; i < k; i++) {
            res = res * (n - i) % MOD;
            res = res * modInverse(i + 1, MOD) % MOD;
        }
        return res;
    }

    private long modInverse(int a, int m) {
        long m0 = m;
        long y = 0, x = 1;
        if (m == 1) return 0;
        while (a > 1) {
            long q = a / m;
            long t = m;
            m = a % m;
            a = t;
            t = y;
            y = x - q * y;
            x = t;
        }
        if (x < 0) x += m0;
        return x;
    }
}

class Solution {
    public int lengthAfterTransformations(String s, int t, List<Integer> nums) {
        int MOD = (int) 1e9 + 7;
        int[] count = new int[26];
        for (char c : s.toCharArray()) {
            count[c - 'a']++;
        }

        int[][] transformMatrix = new int[26][26];
        for (int i = 0; i < 26; i++) {
            int nextCount = nums.get(i);
            int nextStart = (i + 1) % 26;
            for (int j = 0; j < nextCount; j++) {
                transformMatrix[i][(nextStart + j) % 26]++;
            }
        }

        int[][] powerMatrix = matrixPower(transformMatrix, t, MOD);
        int totalLength = 0;
        for (int i = 0; i < 26; i++) {
            int sum = 0;
            for (int j = 0; j < 26; j++) {
                sum = (sum + (int) ((long) powerMatrix[j][i] * count[j]) % MOD) % MOD;
            }
            totalLength = (totalLength + sum) % MOD;
        }

        return totalLength;
    }

    private int[][] matrixMultiply(int[][] a, int[][] b, int MOD) {
        int[][] result = new int[26][26];
        for (int i = 0; i < 26; i++) {
            for (int j = 0; j < 26; j++) {
                for (int k = 0; k < 26; k++) {
                    result[i][j] = (result[i][j] + (int) ((long) a[i][k] * b[k][j]) % MOD) % MOD;
                }
            }
        }
        return result;
    }

    private int[][] matrixPower(int[][] matrix, int n, int MOD) {
        int[][] result = new int[26][26];
        for (int i = 0; i < 26; i++) {
            result[i][i] = 1;
        }
        while (n > 0) {
            if (n % 2 == 1) {
                result = matrixMultiply(result, matrix, MOD);
            }
            matrix = matrixMultiply(matrix, matrix, MOD);
            n /= 2;
        }
        return result;
    }
}

class Solution {
    private static final int MOD = (int) (1e9 + 7);
    private int[][] memo;

    public int countKReducibleNumbers(String s, int k) {
        int n = s.length();
        memo = new int[n + 1][1 << (k + 1)];
        for (int[] row : memo) {
            Arrays.fill(row, -1);
        }
        int num = Integer.parseInt(s, 2);
        return dfs(s, k, 0, 0, true);
    }

    private int dfs(String s, int k, int index, int count, boolean isLimit) {
        if (index == s.length()) {
            return countK(count, k);
        }
        if (!isLimit && memo[index][count] != -1) {
            return memo[index][count];
        }
        int res = 0;
        int up = isLimit ? s.charAt(index) - '0' : 1;
        for (int d = 0; d <= up; d++) {
            res = (res + dfs(s, k, index + 1, count + d, isLimit && d == up)) % MOD;
        }
        if (!isLimit) {
            memo[index][count] = res;
        }
        return res;
    }

    private int countK(int x, int k) {
        for (int i = 0; i < k; i++) {
            x = Integer.bitCount(x);
            if (x == 1) {
                return 1;
            }
        }
        return x == 1 ? 1 : 0;
    }
}

