class Solution {
    public int[] maximumCount(int[] nums, int[][] queries) {
        int n = nums.length;
        int[] primeCount = new int[n];
        boolean[] isPrime = new boolean[100001];
        for (int i = 0; i <= 100000; i++) {
            isPrime[i] = true;
        }
        isPrime[0] = isPrime[1] = false;
        for (int i = 2; i * i <= 100000; i++) {
            if (isPrime[i]) {
                for (int j = i * i; j <= 100000; j += i) {
                    isPrime[j] = false;
                }
            }
        }
        for (int i = 0; i < n; i++) {
            primeCount[i] = isPrime[nums[i]] ? 1 : 0;
        }
        int[] prefixSum = new int[n + 1];
        for (int i = 0; i < n; i++) {
            prefixSum[i + 1] = prefixSum[i] + primeCount[i];
        }
        int[] result = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            int idx = queries[i][0];
            int val = queries[i][1];
            int oldVal = nums[idx];
            nums[idx] = val;
            int newPrimeCount = isPrime[val] ? 1 : 0;
            int oldPrimeCount = isPrime[oldVal] ? 1 : 0;
            prefixSum[idx + 1] += newPrimeCount - oldPrimeCount;
            for (int j = idx + 2; j <= n; j++) {
                prefixSum[j] += newPrimeCount - oldPrimeCount;
            }
            int maxCount = 0;
            for (int k = 1; k < n; k++) {
                int leftCount = prefixSum[k];
                int rightCount = prefixSum[n] - prefixSum[k];
                maxCount = Math.max(maxCount, leftCount + rightCount);
            }
            result[i] = maxCount;
        }
        return result;
    }
}

class Solution {
    public int[] popcountDepth(long[] nums, long[][] queries) {
        int[] depthCount = new int[nums.length];
        for (int i = 0; i < nums.length; i++) {
            depthCount[i] = getPopcountDepth(nums[i]);
        }

        int[] answers = new int[queries.length];
        int j = 0;
        for (long[] query : queries) {
            if (query[0] == 1) {
                int count = 0;
                for (int i = (int) query[1]; i <= query[2]; i++) {
                    if (depthCount[i] == query[3]) {
                        count++;
                    }
                }
                answers[j++] = count;
            } else {
                int idx = (int) query[1];
                long val = query[2];
                depthCount[idx] = getPopcountDepth(val);
            }
        }
        return answers;
    }

    private int getPopcountDepth(long x) {
        int depth = 0;
        while (x != 1) {
            x = Long.bitCount(x);
            depth++;
        }
        return depth;
    }
}

class Solution:
    def lengthOfLongestSubstring(self, s: str) -> int:
        char_set = set()
        left = 0
        max_length = 0
        for right in range(len(s)):
            while s[right] in char_set:
