class Solution:
    def findSubstring(self, s: str, words: List[str]) -> List[int]:
        if not words or not s:
            return []

        word_count = len(words)
        word_length = len(words[0])
        total_length = word_count * word_length
        word_dict = Counter(words)
        result = []

        for i in range(len(s) - total_length + 1):
            temp_dict = {}
            for j in range(word_count):
                word = s[i + j * word_length: i + (j + 1) * word_length]
                if word not in word_dict:
                    break
                temp_dict[word] = temp_dict.get(word, 0) + 1
                if temp_dict[word] > word_dict[word]:
                    break
            else:
                result.append(i)

        return result

class Solution:
    def multiply(self, num1: str, num2: str) -> str:
        if num1 == "0" or num2 == "0":
            return "0"

        n1, n2 = len(num1), len(num2)
        pos = [0] * (n1 + n2)

        for i in range(n1 - 1, -1, -1):
            for j in range(n2 - 1, -1, -1):
                mul = (ord(num1[i]) - ord('0')) * (ord(num2[j]) - ord('0'))
                p1, p2 = i + j, i + j + 1
                sum = mul + pos[p2]

                pos[p2] = sum % 10
                pos[p1] += sum // 10

        res = ''.join(str(x) for x in pos)
        return res.lstrip('0') if res[0] == '0' else res

class Solution:
    def minWindow(self, s: str, t: str) -> str:
        from collections import Counter
        t_count = Counter(t)
        required_chars = len(t_count)
        formed_chars = 0
        window_counts = {}
        min_len = float("inf")
        min_window = ""
        left = 0
        for right in range(len(s)):
            character = s[right]
            window_counts[character] = window_counts.get(character, 0) + 1
            if character in t_count and window_counts[character] == t_count[character]:
                formed_chars += 1
            while left <= right and formed_chars == required_chars:
                character = s[left]
                if right - left + 1 < min_len:
                    min_len = right - left + 1
                    min_window = s[left:right + 1]
                window_counts[character] -= 1
                if character in t_count and window_counts[character] < t_count[character]:
                    formed_chars -= 1
                left += 1
        return min_window

class Solution:
    def combine(self, n: int, k: int) -> List[List[int]]:
        def backtrack(start, path):
            if len(path) == k:
                result.append(path[:])
                return
            for i in range(start, n + 1):
                path.append(i)
                backtrack(i + 1, path)
                path.pop()

        result = []
        backtrack(1, [])
        return result

