        left, right = 0, len(self.intervals) - 1
        while left <= right:
            mid = (left + right) // 2
            start, end = self.intervals[mid]
            if start <= value <= end:
                return
            elif value < start:
                right = mid - 1
            else:
                left = mid + 1
        idx = left
