class Solution:
    def canIWin(self, maxChoosableInteger: int, desiredTotal: int) -> bool:
        if (maxChoosableInteger * (maxChoosableInteger + 1)) // 2 < desiredTotal:
            return False
        self.memo = {}
        return self.dfs((1 << (maxChoosableInteger + 1)) - 2, desiredTotal, maxChoosableInteger)

    def dfs(self, mask, total, maxChoosableInteger):
        if mask in self.memo:
            return self.memo[mask]
        for i in range(maxChoosableInteger, 0, -1):
            if (mask >> i) & 1:
                if i >= total or not self.dfs(mask ^ (1 << i), total - i, maxChoosableInteger):
                    self.memo[mask] = True
                    return True
        self.memo[mask] = False
        return False

class Solution:
    def getMaxRepetitions(self, s1: str, n1: int, s2: str, n2: int) -> int:
        repeat_count = [0] * (len(s2) + 1)
        next_index = [0] * (len(s2) + 1)
        j, count = 0, 0
        for i in range(n1):
            for k in range(len(s1)):
                if s1[k] == s2[j]:
                    j += 1
                    if j == len(s2):
                        j = 0
                        count += 1
            if j == 0:
                repeat_count[i] = count
                next_index[i] = 0
            else:
                repeat_count[i] = count
                next_index[i] = j
            if i == 0:
                init_count = count
                init_next_index = j
            if next_index[i] == init_next_index:
                loop_count = count - init_count
                loop_length = i
                break
        if j != 0:
            return 0
        ans = repeat_count[n1 % loop_length - 1] if loop_length != 0 else count
        ans += (n1 // loop_length) * loop_count if loop_length != 0 else 0
        return ans // n2

