class Solution:
    def findIntegers(self, n: int) -> int:
        MAX_BITS = 32
        f = [0] * MAX_BITS
        f[0] = 1
        f[1] = 2
        for i in range(2, MAX_BITS):
            f[i] = f[i - 1] + f[i - 2]

        ans, last_seen = 0, 0
        for i in range(MAX_BITS - 1, -1, -1):
            if (n >> i) & 1:
                ans += f[i]
                if last_seen:
                    return ans
                last_seen = 1
            else:
                last_seen = 0
        return ans + 1

