class Solution:
    def minimumDeleteSum(self, s1: str, s2: str) -> int:
        m, n = len(s1), len(s2)
        dp = [[0] * (n + 1) for _ in range(m + 1)]

        for i in range(1, m + 1):
            dp[i][0] = dp[i-1][0] + ord(s1[i-1])
        for j in range(1, n + 1):
            dp[0][j] = dp[0][j-1] + ord(s2[j-1])

        for i in range(1, m + 1):
            for j in range(1, n + 1):
                if s1[i-1] == s2[j-1]:
                    dp[i][j] = dp[i-1][j-1]
                else:
                    dp[i][j] = min(dp[i-1][j] + ord(s1[i-1]), dp[i][j-1] + ord(s2[j-1]))

        return dp[m][n]

class RangeModule:

    def __init__(self):
        self.ranges = []

    def addRange(self, left: int, right: int) -> None:
        new_ranges = []
        for start, end in self.ranges:
            if start >= right or end <= left:
                new_ranges.append((start, end))
            else:
                left = min(left, start)
                right = max(right, end)
        new_ranges.append((left, right))
        new_ranges.sort()
        merged = [new_ranges[0]]
        for start, end in new_ranges[1:]:
            if merged[-1][1] >= start:
                merged[-1] = (merged[-1][0], max(end, merged[-1][1]))
            else:
                merged.append((start, end))
        self.ranges = merged

    def queryRange(self, left: int, right: int) -> bool:
        for start, end in self.ranges:
            if start <= left and end >= right:
                return True
            if start > right:
                break
        return False

    def removeRange(self, left: int, right: int) -> None:
        new_ranges = []
        for start, end in self.ranges:
            if start >= right or end <= left:
                new_ranges.append((start, end))
            else:
                if start < left:
                    new_ranges.append((start, left))
                if end > right:
                    new_ranges.append((right, end))
        self.ranges = new_ranges

class Solution:
    def countOfAtoms(self, formula: str) -> str:
        stack = [{}]
        i = 0
        while i < len(formula):
            if formula[i] == '(':
                stack.append({})
                i += 1
            elif formula[i] == ')':
                top = stack.pop()
                i += 1
                start = i
                while i < len(formula) and formula[i].isdigit():
                    i += 1
                count = int(formula[start:i] or 1)
                for k in top:
                    top[k] *= count
                    stack[-1][k] = stack[-1].get(k, 0) + top[k]
            else:
                start = i
                i += 1
                while i < len(formula) and formula[i].islower():
                    i += 1
                name = formula[start:i]
                start = i
                while i < len(formula) and formula[i].isdigit():
                    i += 1
                count = int(formula[start:i] or 1)
                stack[-1][name] = stack[-1].get(name, 0) + count
        counts = []
        for k in sorted(stack[-1]):
            count = stack[-1][k]
            counts.append(k + (str(count) if count > 1 else ''))
        return ''.join(counts)

