import math

class Solution:
    def maxScore(self, nums: List[int]) -> int:
        n = len(nums) // 2
        memo = {}

        def backtrack(mask, i):
            if mask in memo:
                return memo[mask]
            if i > n:
                return 0

            max_score = 0
            for j in range(len(nums)):
                if (mask & (1 << j)) == 0:
                    for k in range(j + 1, len(nums)):
                        if (mask & (1 << k)) == 0:
                            new_mask = mask | (1 << j) | (1 << k)
                            score = i * math.gcd(nums[j], nums[k]) + backtrack(new_mask, i + 1)
                            max_score = max(max_score, score)
            memo[mask] = max_score
            return max_score

        return backtrack(0, 1)

class Solution:
    def maxValue(self, n: int, index: int, maxSum: int) -> int:
        def possible(val):
            total = val
            left = index
            right = index
            while left > 0 or right < n - 1:
                if left > 0:
                    left -= 1
                    if nums[left] > val - 1:
                        total += val - 1
                    else:
                        total += nums[left]
                if right < n - 1:
                    right += 1
                    if nums[right] > val - 1:
                        total += val - 1
                    else:
                        total += nums[right]
                if total > maxSum:
                    return False
            return True

        nums = [1] * n
        left, right = 1, maxSum
        while left <= right:
            mid = (left + right) // 2
            nums[index] = mid
            if possible(mid):
                left = mid + 1
            else:
                right = mid - 1
        return right

