class StockPrice:

    def __init__(self):
        self.price_map = {}
        self.max_heap = []
        self.min_heap = []
        self.latest_timestamp = 0

    def update(self, timestamp: int, price: int) -> None:
        self.price_map[timestamp] = price
        self.latest_timestamp = max(self.latest_timestamp, timestamp)
        heapq.heappush(self.max_heap, (-price, timestamp))
        heapq.heappush(self.min_heap, (price, timestamp))

    def current(self) -> int:
        return self.price_map[self.latest_timestamp]

    def maximum(self) -> int:
        while self.max_heap and self.price_map[self.max_heap[0][1]] != -self.max_heap[0][0]:
            heapq.heappop(self.max_heap)
        return -self.max_heap[0][0]

    def minimum(self) -> int:
        while self.min_heap and self.price_map[self.min_heap[0][1]] != self.min_heap[0][0]:
            heapq.heappop(self.min_heap)
        return self.min_heap[0][0]

class Solution:
    def maxTaskAssign(self, tasks: List[int], workers: List[int], pills: int, strength: int) -> int:
        tasks.sort()
        workers.sort(reverse=True)
        def possible(amt):
            need_pill = 0
            for i in range(amt):
                if workers[i] < tasks[-i-1]:
                    need_pill += 1
                    if need_pill > pills or workers[i] + strength < tasks[-i-1]:
                        return False
            return True
        lo, hi = 0, min(len(tasks), len(workers))
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if possible(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo

class Solution:
    def friendRequests(self, n: int, restrictions: List[List[int]], requests: List[List[int]]) -> List[bool]:
        parent = list(range(n))
        rank = [1] * n

        def find(x):
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]

        def union(x, y):
            px, py = find(x), find(y)
            if px != py:
                if rank[px] > rank[py]:
                    parent[py] = px
                    rank[px] += rank[py]
                else:
                    parent[px] = py
                    rank[py] += rank[px]

        res = []
        for u, v in requests:
            pu, pv = find(u), find(v)
            valid = True
            for x, y in restrictions:
                px, py = find(x), find(y)
                if {pu, pv} == {px, py}:
                    valid = False
                    break
            res.append(valid)
            if valid:
                union(u, v)
        return res

