class Solution:
    def kIncreasing(self, arr: List[int], k: int) -> int:
        def length_of_lis(nums):
            lis = []
            for num in nums:
                idx = bisect_right(lis, num)
                if idx == len(lis):
                    lis.append(num)
                else:
                    lis[idx] = num
            return len(lis)

        total_changes = 0
        for i in range(k):
            subsequence = arr[i::k]
            total_changes += len(subsequence) - length_of_lis(subsequence)
        return total_changes

