        s = list(s)
        res = 0
        n = len(s)
        left, right = 0, n - 1
        while left < right:
            if s[left] == s[right]:
                left += 1
                right -= 1
            else:
                p = right
                while s[left] != s[p] and p > left:
                    p -= 1
                if p == left:
                    s[p], s[p + 1] = s[p + 1], s[p]
                    res += 1
                else:
                    while p < right:
                        s[p], s[p + 1] = s[p + 1], s[p]
                        p += 1
                        res += 1
                    left += 1
                    right -= 1
        return res

