class Solution:
    def countGoodIntegers(self, n: int, k: int) -> int:
        count = 0
        for first_digit in range(1, 10):
            count += self.backtrack(n - 1, k, [first_digit])
        return count

    def backtrack(self, n, k, path):
        if n == 0:
            freq = [0] * 10
            for d in path:
                freq[d] += 1
            if self.is_k_palindromic(freq, k):
                return 1
            return 0
        count = 0
        for digit in range(10):
            count += self.backtrack(n - 1, k, path + [digit])
        return count

    def is_k_palindromic(self, freq, k):
        left = ''
        right = ''
        odd_count = 0
        odd_digit = -1
        for i in range(10):
            if freq[i] % 2 == 1:
                odd_count += 1
                odd_digit = i
        if odd_count > 1:
            return False
        for i in range(10):
            left += str(i) * (freq[i] // 2)
            right = str(i) * (freq[i] // 2) + right
        if odd_count == 1:
            mid = str(odd_digit)
        else:
            mid = ''
        num = int(left + mid + right)
        return num % k == 0

