class Solution:
    def maximumCount(self, nums: List[int], queries: List[List[int]]) -> List[int]:
        MAXN = 10**5
        spf = [i for i in range(MAXN+1)]
        for i in range(2, int(MAXN**0.5) + 1):
            if spf[i] == i:
                for j in range(i*i, MAXN+1, i):
                    if spf[j] == j:
                        spf[j] = i
        prime_count = [0] * (MAXN + 1)
        for num in nums:
            while num > 1:
                prime = spf[num]
                prime_count[prime] += 1
                num //= prime
        prefix_sum = [0]
        for count in prime_count[1:]:
            prefix_sum.append(prefix_sum[-1] + (1 if count > 0 else 0))
        results = []
        for idx, val in queries:
            old_val = nums[idx]
            nums[idx] = val
            while old_val > 1:
                prime = spf[old_val]
                prime_count[prime] -= 1
                if prime_count[prime] == 0:
                    prefix_sum[prime] = prefix_sum[prime-1]
                old_val //= prime
            while val > 1:
                prime = spf[val]
                prime_count[prime] += 1
                if prime_count[prime] == 1:
                    prefix_sum[prime] = prefix_sum[prime-1] + 1
                val //= prime
            results.append(prefix_sum[-1] - 1 if prefix_sum[-1] > 0 else 0)
        return results

class Solution:
    def maxGCDScore(self, nums: List[int], k: int) -> int:
        n = len(nums)
        max_score = 0
        gcd_prefix = [0] * (n + 1)
        gcd_suffix = [0] * (n + 1)
        for i in range(n):
            gcd_prefix[i + 1] = math.gcd(gcd_prefix[i], nums[i])
        for i in range(n - 1, -1, -1):
            gcd_suffix[i] = math.gcd(gcd_suffix[i + 1], nums[i])
        for i in range(n):
            left_gcd = gcd_prefix[i]
            right_gcd = gcd_suffix[i + 1]
            curr_gcd = math.gcd(left_gcd, right_gcd, nums[i] * 2)
            max_score = max(max_score, curr_gcd * 1)
            if i > 0:
                max_score = max(max_score, math.gcd(left_gcd, nums[i] * 2) * i)
            if i < n - 1:
                max_score = max(max_score, math.gcd(right_gcd, nums[i] * 2) * (n - i))
        for length in range(2, min(k + 1, n + 1)):
            for i in range(n - length + 1):
                gcd_val = nums[i]
                for j in range(i, i + length):
                    gcd_val = math.gcd(gcd_val, nums[j])
                max_score = max(max_score, gcd_val * length)
        for i in range(n):
            if k > 0:
                max_score = max(max_score, nums[i] * 2)
                k -= 1
        return max_score

from typing import List
from functools import lru_cache

class Solution:
    def minTime(self, n: int, k: int, m: int, time: List[int], mul: List[float]) -> float:
        @lru_cache(None)
        def dfs(state, stage, dest):
            if state == 0:
                return 0
            res = float('inf')
            for mask in range(1, 1 << n):
                if bin(mask).count('1') > k or (mask & state) != mask:
                    continue
                new_state = state ^ mask
                max_time = max(time[i] for i in range(n) if (mask & (1 << i)))
                cross_time = max_time * mul[stage]
                next_stage = (stage + int(cross_time) % m) % m
                if dest == 0:
                    return_time = time[next((i for i in range(n) if (mask & (1 << i))))] * mul[next_stage]
                    next_next_stage = (next_stage + int(return_time) % m) % m
                    res = min(res, cross_time + return_time + dfs(new_state, next_next_stage, 1))
                else:
                    res = min(res, cross_time + dfs(new_state, next_stage, 0))
            return res

        res = dfs((1 << n) - 1, 0, 0)
        return res if res != float('inf') else -1.0

class Solution:
    def maxStability(self, n: int, edges: List[List[int]], k: int) -> int:
        must_edges = []
        non_must_edges = []

        for u, v, s, must in edges:
            if must:
                must_edges.append((u, v, s))
            else:
                non_must_edges.append((s, u, v))

        non_must_edges.sort()

        parent = list(range(n))
        rank = [0] * n

        def find(x):
            if x != parent[x]:
                parent[x] = find(parent[x])
            return parent[x]

        def union(x, y):
            root_x, root_y = find(x), find(y)
            if root_x != root_y:
                if rank[root_x] > rank[root_y]:
                    parent[root_y] = root_x
                elif rank[root_x] < rank[root_y]:
                    parent[root_x] = root_y
                else:
                    parent[root_y] = root_x
                    rank[root_x] += 1

        for u, v, s in must_edges:
            if find(u) != find(v):
                union(u, v)
            else:
                return -1

        count = sum(1 for u, v, s in must_edges if find(u) != find(v))
        if count == n - 1:
            min_strength = min(s for u, v, s in must_edges)
        else:
            min_strength = float('inf')

        for s, u, v in non_must_edges:
            if find(u) != find(v):
                union(u, v)
                count += 1
                if count == n - 1:
                    if k > 0:
                        min_strength = max(min_strength, s * 2)
                        k -= 1
                    else:
                        min_strength = max(min_strength, s)

        return min_strength if count == n - 1 else -1

class Solution:
    def minStable(self, nums: List[int], maxC: int) -> int:
        def check(stability_factor):
            modifications = 0
            i = 0
            for j in range(len(nums)):
                if nums[j] % 2 == 1:
                    modifications += 1
                if j - i + 1 > stability_factor:
                    if nums[i] % 2 == 1:
                        modifications -= 1
                    i += 1
                if modifications > maxC:
                    return False
            return True

        even_count = sum(1 for num in nums if num % 2 == 0)
        if even_count == 0:
            return 0 if maxC == 0 else 1

        left, right = 1, len(nums)
        while left <= right:
            mid = (left + right) // 2
            if check(mid):
                left = mid + 1
            else:
                right = mid - 1
        return right if right > 0 else 0

class Solution:
    def popcountDepth(self, nums: List[int], queries: List[List[int]]) -> List[int]:
        depth = [0] * len(nums)
        for i, num in enumerate(nums):
            d = 0
            while num != 1:
                num = bin(num).count('1')
                d += 1
            depth[i] = d

        answers = []
        for query in queries:
            if query[0] == 1:
                l, r, k = query[1], query[2], query[3]
                count = sum(1 for i in range(l, r + 1) if depth[i] == k)
                answers.append(count)
            else:
                idx, val = query[1], query[2]
                d = 0
                while val != 1:
                    val = bin(val).count('1')
                    d += 1
                depth[idx] = d

        return answers

class MinStack:

    def __init__(self):
        self.stack = []
        self.min_stack = []

    def push(self, val: int) -> None:
        self.stack.append(val)
        if not self.min_stack or val <= self.min_stack[-1]:
            self.min_stack.append(val)

    def pop(self) -> None:
        if self.stack[-1] == self.min_stack[-1]:
            self.min_stack.pop()
        self.stack.pop()

    def top(self) -> int:
        return self.stack[-1]

    def getMin(self) -> int:
        return self.min_stack[-1]


