class AllOne:

    def __init__(self):
        self.key_count = {}
        self.count_keys = {}
        self.min_count = float('inf')
        self.max_count = float('-inf')

    def inc(self, key: str) -> None:
        if key in self.key_count:
            old_count = self.key_count[key]
            self.count_keys[old_count].remove(key)
            if not self.count_keys[old_count]:
                del self.count_keys[old_count]
            self.key_count[key] += 1
            new_count = self.key_count[key]
            if new_count not in self.count_keys:
                self.count_keys[new_count] = set()
            self.count_keys[new_count].add(key)
            if new_count > self.max_count:
                self.max_count = new_count
            if old_count == self.min_count and (old_count not in self.count_keys or not self.count_keys[old_count]):
                self.min_count = new_count if new_count != old_count else min(self.count_keys.keys())
        else:
            self.key_count[key] = 1
            if 1 not in self.count_keys:
                self.count_keys[1] = set()
            self.count_keys[1].add(key)
            self.min_count = min(self.min_count, 1)
            self.max_count = max(self.max_count, 1)

    def dec(self, key: str) -> None:
        old_count = self.key_count[key]
        self.count_keys[old_count].remove(key)
        if not self.count_keys[old_count]:
            del self.count_keys[old_count]
        self.key_count[key] -= 1
        if self.key_count[key] == 0:
            del self.key_count[key]
        else:
            new_count = self.key_count[key]
            if new_count not in self.count_keys:
                self.count_keys[new_count] = set()
            self.count_keys[new_count].add(key)
            self.min_count = min(self.min_count, new_count)
        if old_count == self.max_count and (old_count not in self.count_keys or not self.count_keys[old_count]):
            self.max_count = max(self.count_keys.keys()) if self.count_keys else float('-inf')

    def getMaxKey(self) -> str:
        return next(iter(self.count_keys[self.max_count])) if self.max_count != float('-inf') else ""

    def getMinKey(self) -> str:
        return next(iter(self.count_keys[self.min_count])) if self.min_count != float('inf') else ""

class Codec:

    def serialize(self, root: Optional[TreeNode]) -> str:
        def preorder_traversal(root):
            if root:
                vals.append(str(root.val))
                preorder_traversal(root.left)
                preorder_traversal(root.right)
        vals = []
        preorder_traversal(root)
        return ' '.join(vals)

    def deserialize(self, data: str) -> Optional[TreeNode]:
        def build_tree(vals, min_val, max_val):
            if vals and min_val < int(vals[0]) < max_val:
                val = int(vals.pop(0))
                node = TreeNode(val)
                node.left = build_tree(vals, min_val, val)
                node.right = build_tree(vals, val, max_val)
                return node
        vals = data.split()
        return build_tree(vals, float('-inf'), float('inf'))

