    def strangePrinter(self, s: str) -> int:
        s = ''.join([s[i] for i in range(len(s)) if i == 0 or s[i] != s[i-1]])
        n = len(s)
        dp = [[n] * n for _ in range(n)]
        for i in range(n): dp[i][i] = 1
        for i in range(n-1, -1, -1):
            for j in range(i+1, n):
                if s[i] == s[j]: dp[i][j] = dp[i][j-1]
                else: dp[i][j] = min([dp[i][k] + dp[k+1][j] for k in range(i, j)])
        return dp[0][n-1]

class Solution:
    def backspaceCompare(self, s: str, t: str) -> bool:
        def get_next_valid_char(s, i):
            backspace_count = 0
            while i >= 0:
                if s[i] == '#':
                    backspace_count += 1
                elif backspace_count > 0:
                    backspace_count -= 1
                else:
                    return i
                i -= 1
            return -1

        i, j = len(s) - 1, len(t) - 1
        while i >= 0 or j >= 0:
            i = get_next_valid_char(s, i)
            j = get_next_valid_char(t, j)
            if i >= 0 and j >= 0 and s[i] != t[j]:
                return False
            if (i >= 0) != (j >= 0):
                return False
            i -= 1
            j -= 1
        return True

