    }
}

class LFUCache {

    private int capacity;
    private Map<Integer, Node> cache;
    private Map<Integer, DoublyLinkedList> countToList;
    private int minCount;

    public LFUCache(int capacity) {
        this.capacity = capacity;
        this.cache = new HashMap<>();
        this.countToList = new HashMap<>();
        this.minCount = 0;
    }

    public int get(int key) {
        if (capacity == 0) return -1;
        if (!cache.containsKey(key)) return -1;
        Node node = cache.get(key);
        updateCountToList(node);
        return node.value;
    }

    public void put(int key, int value) {
        if (capacity == 0) return;
        if (cache.containsKey(key)) {
            Node node = cache.get(key);
            node.value = value;
            updateCountToList(node);
        } else {
            if (cache.size() == capacity) {
                removeLFUNode();
            }
            Node node = new Node(key, value, 1);
            cache.put(key, node);
            DoublyLinkedList list = countToList.getOrDefault(1, new DoublyLinkedList());
            list.add(node);
            countToList.put(1, list);
            minCount = 1;
        }
    }

    private void updateCountToList(Node node) {
        DoublyLinkedList oldList = countToList.get(node.count);
        oldList.remove(node);
        if (oldList.isEmpty() && minCount == node.count) {
            minCount++;
        }
        node.count++;
        DoublyLinkedList newList = countToList.getOrDefault(node.count, new DoublyLinkedList());
        newList.add(node);
        countToList.put(node.count, newList);
    }

    private void removeLFUNode() {
        DoublyLinkedList list = countToList.get(minCount);
        Node node = list.removeFirst();
        cache.remove(node.key);
        if (list.isEmpty()) {
            countToList.remove(minCount);
        }
    }

    private class DoublyLinkedList {
        Node head, tail;
        public DoublyLinkedList() {
            head = new Node(0, 0, 0);
            tail = new Node(0, 0, 0);
            head.next = tail;
            tail.prev = head;
        }
        public void add(Node node) {
            node.prev = head;
            node.next = head.next;
            head.next.prev = node;
            head.next = node;
        }
        public void remove(Node node) {
            node.prev.next = node.next;
            node.next.prev = node.prev;
        }
        public Node removeFirst() {
            if (isEmpty()) return null;
            Node node = head.next;
            remove(node);
            return node;
        }
        public boolean isEmpty() {
            return head.next == tail;
        }
    }
}

