    private static final int BASE_URL_LENGTH = BASE_URL.length();

    public Codec() {
        map = new HashMap<>();
    }

    // Encodes a URL to a shortened URL.
    public String encode(String longUrl) {
        String shortUrl = BASE_URL + Integer.toString(longUrl.hashCode(), 36);
        while (map.containsKey(shortUrl)) {
            shortUrl = BASE_URL + Long.toString(System.nanoTime(), 36);
        }
        map.put(shortUrl, longUrl);
        return shortUrl;
    }

