class Solution:
    def kIncreasing(self, arr: List[int], k: int) -> int:
        n = len(arr)
        dp = []
        res = 0

        for i in range(n):
            if i >= k:
                sub = dp[:]
                idx = bisect_left(sub, arr[i-k])
                if idx == len(sub):
                    sub.append(arr[i-k])
                else:
                    sub[idx] = arr[i-k]
                dp = sub

            sub = dp
            idx = bisect_left(sub, arr[i])
            if idx == len(sub):
                sub.append(arr[i])
            else:
                sub[idx] = arr[i]
            res += len(dp) - len(sub)
            dp = sub

        return res

