class Solution:
    def maximumOr(self, nums: List[int], k: int) -> int:
        bits = 30
        mask = 0
        for _ in range(k):
            mask <<= 1
            mask |= 1
        res = 0
        for i in range(bits, -1, -1):
            curr_mask = mask << (bits - i)
            can_make = False
            for x in nums:
                if (x & (curr_mask)) == curr_mask:
                    can_make = True
                    break
                if (x | curr_mask) != (x | res):
                    can_make = True
                    break
            if can_make:
                res |= 1 << (bits - i)
        return res

from collections import deque

class Solution:
    def minimumOperationsToMakeEqual(self, x: int, y: int) -> int:
        if x == y:
            return 0

        queue = deque([(x, 0)])
        visited = set([x])

        while queue:
            current, steps = queue.popleft()

            if current == y:
                return steps

            if current % 11 == 0 and current // 11 not in visited:
                queue.append((current // 11, steps + 1))
                visited.add(current // 11)

            if current % 5 == 0 and current // 5 not in visited:
                queue.append((current // 5, steps + 1))
                visited.add(current // 5)

            if current + 1 not in visited:
                queue.append((current + 1, steps + 1))
                visited.add(current + 1)

            if current - 1 not in visited:
                queue.append((current - 1, steps + 1))
                visited.add(current - 1)

