class Solution:
    def validSequence(self, word1: str, word2: str) -> List[int]:
        m, n = len(word1), len(word2)
        i, j = 0, 0
        mismatch = 0
        res = []

        while j < n:
            if i >= m:
                return []

            if word1[i] != word2[j]:
                if mismatch:
                    return []
                mismatch += 1
                while i < m and word1[i] != word2[j]:
                    i += 1
                if i == m:
                    return []

            res.append(i)
            i += 1
            j += 1

        if i < m and mismatch == 0:
            return []

        return res

