class Solution:
    def minStable(self, nums: List[int], maxC: int) -> int:
        def find_gcd(subarray):
            if len(subarray) == 1:
                return subarray[0]
            return reduce(gcd, subarray)

        n = len(nums)
        max_length = 0

        left = 0
        changes = 0

        for right in range(n):
            if nums[right] < 2:
                changes += 1

            while changes > maxC:
                if nums[left] < 2:
                    changes -= 1
                left += 1

            max_length = max(max_length, right - left + 1)

        return max_length if max_length > 1 else 0

