class Solution:
    def palindromePartition(self, s: str, k: int) -> int:
        n = len(s)
        dp = [[0]*n for _ in range(n)]
        for i in range(n-1, -1, -1):
            for j in range(i, n):
                dp[i][j] = sum(a != b for a, b in zip(s[i:j+1], s[j:i-1:-1]))

        f = [[float('inf')] * (k+1) for _ in range(n+1)]
        f[0][0] = 0
        for i in range(1, n+1):
            for j in range(1, min(i, k)+1):
                for p in range(j-1, i):
                    f[i][j] = min(f[i][j], f[p][j-1] + dp[p][i-1])
        return f[n][k]

class Solution:
    def maxFreq(self, s: str, maxLetters: int, minSize: int, maxSize: int) -> int:
        max_count = 0
        freq = {}
        for i in range(len(s) - minSize + 1):
            substr = s[i:i + minSize]
            if len(set(substr)) <= maxLetters:
                freq[substr] = freq.get(substr, 0) + 1
                max_count = max(max_count, freq[substr])
        return max_count

class Solution:
    def canConstruct(self, s: str, k: int) -> bool:
        char_count = {}
        for char in s:
            char_count[char] = char_count.get(char, 0) + 1
        odd_counts = sum(count % 2 for count in char_count.values())
        return odd_counts <= k and k <= len(s)

