import heapq

class SORTracker:

    def __init__(self):
        self.max_heap = []
        self.min_heap = []
        self.query_count = 0

    def add(self, name: str, score: int) -> None:
        heapq.heappush(self.max_heap, (-score, name))

    def get(self) -> str:
        self.query_count += 1
        while self.max_heap and (len(self.min_heap) == self.query_count - 1 or self.max_heap[0][1] >= self.min_heap[0][1]):
            heapq.heappush(self.min_heap, (-heapq.heappop(self.max_heap)[0], heapq.heappop(self.max_heap)[1]))
        best = heapq.heappop(self.min_heap)
        heapq.heappush(self.min_heap, best)
        return best[1]

class Solution:
    def largestInteger(self, num: int) -> int:
        num_str = str(num)
        odd = []
        even = []

        for digit in num_str:
            if int(digit) % 2 == 0:
                even.append(digit)
            else:
                odd.append(digit)

        odd.sort(reverse=True)
        even.sort(reverse=True)

        result = []
        odd_idx, even_idx = 0, 0

        for digit in num_str:
            if int(digit) % 2 == 0:
                result.append(even[even_idx])
                even_idx += 1
            else:
                result.append(odd[odd_idx])
                odd_idx += 1

        return int(''.join(result))

