class ExamRoom {
    int N;
    set<int> seats;
public:
    ExamRoom(int n) : N(n) {}

    int seat() {
        if (seats.empty()) {
            seats.insert(0);
            return 0;
        }
        int maxDist = *seats.begin();
        int pos = 0;
        int prev = *seats.begin();
        for (auto it = next(seats.begin()); it != seats.end(); ++it) {
            int curr = *it;
            int mid = prev + (curr - prev) / 2;
            int dist = (curr - prev) / 2;
            if (dist > maxDist) {
                maxDist = dist;
                pos = mid;
            }
            prev = curr;
        }
        int lastDist = (N - 1) - *seats.rbegin();
        if (lastDist > maxDist) {
            maxDist = lastDist;
            pos = N - 1;
        }
        seats.insert(pos);
        return pos;
    }

    void leave(int p) {
        seats.erase(p);
    }
};

