public class NestedIterator implements Iterator<Integer> {
    private Deque<Iterator<NestedInteger>> stack;

    public NestedIterator(List<NestedInteger> nestedList) {
        stack = new ArrayDeque<>();
        stack.push(nestedList.iterator());
    }

    @Override
    public Integer next() {
        if (!hasNext()) throw new NoSuchElementException();
        NestedInteger ni = stack.peek().next();
        return ni.getInteger();
    }

    @Override
    public boolean hasNext() {
        while (!stack.isEmpty()) {
            Iterator<NestedInteger> it = stack.peek();
            if (!it.hasNext()) {
                stack.pop();
                continue;
            }
            NestedInteger ni = it.next();
            if (ni.isInteger()) {
                it = new ArrayList<>(Collections.singletonList(ni)).iterator();
                stack.push(it);
                return true;
            } else {
                stack.push(ni.getList().iterator());
            }
        }
        return false;
    }
}

import java.util.*;

class LFUCache {
    private final int capacity;
    private int minFreq;
    private final Map<Integer, Node> keyMap;
    private final Map<Integer, LinkedHashSet<Node>> freqMap;

    private static class Node {
        int key, val, freq;
        Node(int k, int v) {
            key = k;
            val = v;
            freq = 1;
        }
    }

    public LFUCache(int capacity) {
        this.capacity = capacity;
        this.minFreq = 0;
        this.keyMap = new HashMap<>();
        this.freqMap = new HashMap<>();
    }

    public int get(int key) {
        if (capacity == 0) return -1;
        Node node = keyMap.get(key);
        if (node == null) return -1;
        update(node);
        return node.val;
    }

    public void put(int key, int value) {
        if (capacity == 0) return;
        Node node = keyMap.get(key);
        if (node != null) {
            node.val = value;
            update(node);
            return;
        }
        if (keyMap.size() == capacity) {
            LinkedHashSet<Node> set = freqMap.get(minFreq);
            Node toEvict = set.iterator().next();
            set.remove(toEvict);
            keyMap.remove(toEvict.key);
            if (set.isEmpty()) freqMap.remove(minFreq);
        }
        Node newNode = new Node(key, value);
        keyMap.put(key, newNode);
        freqMap.computeIfAbsent(1, k -> new LinkedHashSet<>()).add(newNode);
        minFreq = 1;
    }

    private void update(Node node) {
        LinkedHashSet<Node> oldSet = freqMap.get(node.freq);
        oldSet.remove(node);
        if (oldSet.isEmpty()) {
            freqMap.remove(node.freq);
            if (minFreq == node.freq) minFreq++;
        }
        node.freq++;
        freqMap.computeIfAbsent(node.freq, k -> new LinkedHashSet<>()).add(node);
    }
}

