class SummaryRanges:
    def __init__(self):
        self.intervals = []  # list of [start, end] disjoint and sorted

    def addNum(self, value: int) -> None:
        idx = bisect.bisect_left(self.intervals, [value, float('inf')])
        left, right = idx - 1, idx
        merge_left = left >= 0 and self.intervals[left][1] >= value - 1
        merge_right = right < len(self.intervals) and self.intervals[right][0] <= value + 1

        if merge_left and merge_right:
            self.intervals[left][1] = self.intervals[right][1]
            self.intervals.pop(right)
        elif merge_left:
            self.intervals[left][1] = max(self.intervals[left][1], value)
        elif merge_right:
            self.intervals[right][0] = min(self.intervals[right][0], value)
        elif (left >= 0 and self.intervals[left][1] == value - 1) or (right < len(self.intervals) and self.intervals[right][0] == value + 1):
            pass  # handled above
        else:
            bisect.insort(self.intervals, [value, value])

    def getIntervals(self) -> list[list[int]]:
        return self.intervals

class AllOne:
    def __init__(self):
        from collections import defaultdict
        self.key_to_cnt = {}
        self.cnt_to_bucket = defaultdict(set)
        self.min_cnt = None
        self.max_cnt = None

    def inc(self, key: str) -> None:
        if key in self.key_to_cnt:
            old_cnt = self.key_to_cnt[key]
            new_cnt = old_cnt + 1
            self.cnt_to_bucket[old_cnt].remove(key)
            if not self.cnt_to_bucket[old_cnt]:
                del self.cnt_to_bucket[old_cnt]
                if old_cnt == self.min_cnt:
                    self.min_cnt = new_cnt if old_cnt == self.max_cnt else self.min_cnt
            self.key_to_cnt[key] = new_cnt
            self.cnt_to_bucket[new_cnt].add(key)
            if self.max_cnt is None or new_cnt > self.max_cnt:
                self.max_cnt = new_cnt
            if self.min_cnt is None or new_cnt < self.min_cnt:
                self.min_cnt = new_cnt
            if old_cnt == self.min_cnt and old_cnt not in self.cnt_to_bucket:
                self.min_cnt = min(self.cnt_to_bucket.keys()) if self.cnt_to_bucket else None
        else:
            new_cnt = 1
            self.key_to_cnt[key] = new_cnt
            self.cnt_to_bucket[new_cnt].add(key)
            if self.min_cnt is None or new_cnt < self.min_cnt:
                self.min_cnt = new_cnt
            if self.max_cnt is None or new_cnt > self.max_cnt:
                self.max_cnt = new_cnt

    def dec(self, key: str) -> None:
        old_cnt = self.key_to_cnt[key]
        new_cnt = old_cnt - 1
        self.cnt_to_bucket[old_cnt].remove(key)
        if not self.cnt_to_bucket[old_cnt]:
            del self.cnt_to_bucket[old_cnt]
            if old_cnt == self.max_cnt:
                self.max_cnt = old_cnt - 1 if old_cnt - 1 in self.cnt_to_bucket else (max(self.cnt_to_bucket.keys()) if self.cnt_to_bucket else None)
            if old_cnt == self.min_cnt:
                self.min_cnt = old_cnt - 1 if old_cnt - 1 in self.cnt_to_bucket else (min(self.cnt_to_bucket.keys()) if self.cnt_to_bucket else None)
        if new_cnt == 0:
            del self.key_to_cnt[key]
        else:
            self.key_to_cnt[key] = new_cnt
            self.cnt_to_bucket[new_cnt].add(key)
            if self.min_cnt is None or new_cnt < self.min_cnt:
                self.min_cnt = new_cnt
            if self.max_cnt is None or new_cnt > self.max_cnt:
                self.max_cnt = new_cnt
        if not self.cnt_to_bucket:
            self.min_cnt = None
            self.max_cnt = None

    def getMaxKey(self) -> str:
        if self.max_cnt is None or self.max_cnt not in self.cnt_to_bucket:
            return ""
        return next(iter(self.cnt_to_bucket[self.max_cnt]))

    def getMinKey(self) -> str:
        if self.min_cnt is None or self.min_cnt not in self.cnt_to_bucket:
            return ""
        return next(iter(self.cnt_to_bucket[self.min_cnt]))

class Solution:
    def frequencySort(self, s: str) -> str:
        from collections import Counter
        counts = Counter(s)
        max_freq = max(counts.values()) if counts else 0
        buckets = [[] for _ in range(max_freq + 1)]
        for ch, freq in counts.items():
            buckets[freq].append(ch)
        res = []
        for freq in range(max_freq, 0, -1):
