from collections import defaultdict, OrderedDict

class LFUCache:

    def __init__(self, capacity: int):
        self.capacity = capacity
        self.size = 0
        self.min_freq = 0
        self.key_map = {}  # key -> (value, freq)
        self.freq_map = defaultdict(OrderedDict)  # freq -> OrderedDict[key, None]

    def _update(self, key, value=None):
        val, freq = self.key_map[key]
        if value is not None:
            val = value
        del self.freq_map[freq][key]
        if not self.freq_map[freq]:
            del self.freq_map[freq]
            if self.min_freq == freq:
                self.min_freq += 1
        new_freq = freq + 1
        self.freq_map[new_freq][key] = None
        self.key_map[key] = (val, new_freq)
        return val

    def get(self, key: int) -> int:
        if key not in self.key_map:
            return -1
        return self._update(key)

    def put(self, key: int, value: int) -> None:
        if self.capacity <= 0:
            return
        if key in self.key_map:
            self._update(key, value)
            return
        if self.size >= self.capacity:
            k, _ = self.freq_map[self.min_freq].popitem(last=False)
            del self.key_map[k]
            self.size -= 1
        self.key_map[key] = (value, 1)
        self.freq_map[1][key] = None
        self.min_freq = 1
        self.size += 1

class Solution:
    def canIWin(self, maxChoosableInteger: int, desiredTotal: int) -> bool:
        if desiredTotal <= 0:
            return True
        if maxChoosableInteger * (maxChoosableInteger + 1) // 2 < desiredTotal:
            return False

        from functools import lru_cache

        @lru_cache(None)
        def dfs(used, remaining):
            for i in range(1, maxChoosableInteger + 1):
                mask = 1 << (i - 1)
                if not (used & mask):
                    if i >= remaining or not dfs(used | mask, remaining - i):
                        return True
            return False

        return dfs(0, desiredTotal)

