class Solution:
    def checkInclusion(self, s1: str, s2: str) -> bool:
        if len(s1) > len(s2):
            return False

        from collections import Counter

        target = Counter(s1)
        window = Counter(s2[:len(s1)])

        if window == target:
            return True

        for i in range(len(s1), len(s2)):
            left_char = s2[i - len(s1)]
            right_char = s2[i]

            window[right_char] += 1
            window[left_char] -= 1

            if window[left_char] == 0:
                del window[left_char]

            if window == target:
                return True

        return False

class Solution:
    def minSteps(self, n: int) -> int:
        if n == 1:
            return 0
        res = 0
        d = 2
        while n > 1:
            while n % d == 0:
                res += d
                n //= d
            d += 1
        return res

