class Solution:
    def validSubstringCount(self, word1: str, word2: str) -> int:
        from collections import Counter

        m, n = len(word1), len(word2)
        if m < n:
            return 0

        target = Counter(word2)
        required = len(target)

        freq = Counter()
        formed = 0
        left = 0
        res = 0

        for right in range(m):
            c = word1[right]
            freq[c] += 1
            if c in target and freq[c] == target[c]:
                formed += 1

            while left <= right and formed == required:
                if right - left + 1 >= n:
                    res += m - right
                left_c = word1[left]
                if left_c in target and freq[left_c] == target[left_c]:
                    formed -= 1
                freq[left_c] -= 1
                left += 1

        return res

class Solution:
    def countWinningSequences(self, s: str) -> int:
        MOD = 10**9 + 7
        n = len(s)
        # Map Alice's move to the move Bob needs to win
        beats = {'F': 'E', 'W': 'F', 'E': 'W'}
        # Precompute delta[i][b] = 1 if Bob's move b beats Alice's move s[i], else -1 if Alice's move beats b, else 0
        delta = [[0]*3 for _ in range(n)]
        for i in range(n):
            a = s[i]
            for idx, b in enumerate(['F', 'W', 'E']):
                if b == beats[a]:
                    delta[i][idx] = 1
                elif a == beats[b]:
                    delta[i][idx] = -1
                else:
                    delta[i][idx] = 0

        # DP[i][last][score] = number of sequences up to round i ending with 'last' and total score 'score'
        # Initialize for round 0
        from collections import defaultdict
        dp = [defaultdict(int) for _ in range(3)]
        for b in range(3):
            dp[b][delta[0][b]] = 1

        for i in range(1, n):
            new_dp = [defaultdict(int) for _ in range(3)]
            for prev_last in range(3):
                for score, cnt in dp[prev_last].items():
                    for curr in range(3):
                        if curr == prev_last:
                            continue
                        new_score = score + delta[i][curr]
                        new_dp[curr][new_score] = (new_dp[curr][new_score] + cnt) % MOD
            dp = new_dp

        total = 0
        for last in range(3):
            for score, cnt in dp[last].items():
                if score > 0:
                    total = (total + cnt) % MOD
        return total

class Solution:
    def countNumbers(self, l: str, r: str, b: int) -> int:
