import math

class Solution:
    def minTime(self, n: int, k: int, m: int, time: List[int], mul: List[float]) -> float:
        if k == 1:
            return -1.0 if n > 1 else float(time[0] * mul[0])

        INF = 1e18
        full_mask = (1 << n) - 1

        # dp[mask][stage] = minimal total time
        dp = [[INF] * m for _ in range(1 << n)]
        dp[0][0] = 0.0

        for mask in range(1 << n):
            for stage in range(m):
                if dp[mask][stage] >= INF:
                    continue

                # Determine which people are on the left (base camp)
                left = [i for i in range(n) if not (mask & (1 << i))]
                if not left:
                    continue

                # Generate all possible groups to send (size 1..min(k, len(left)))
                max_group = min(k, len(left))
                for group_size in range(1, max_group + 1):
                    # Generate all combinations of group_size people from left
                    from itertools import combinations
                    for group in combinations(left, group_size):
                        # Compute crossing time
                        max_time = max(time[i] for i in group)
                        cross_time = max_time * mul[stage]
                        new_stage = (stage + int(cross_time)) % m
                        new_mask = mask
                        for i in group:
                            new_mask |= (1 << i)

                        if new_mask == full_mask:
                            if dp[new_mask][new_stage] > dp[mask][stage] + cross_time:
                                dp[new_mask][new_stage] = dp[mask][stage] + cross_time
                            continue

                        # Need to return someone
                        # People on the right are those in new_mask
                        right = [i for i in range(n) if (new_mask & (1 << i))]
                        min_return = INF
                        for r in right:
                            return_time = time[r] * mul[new_stage]
                            next_stage = (new_stage + int(return_time)) % m
                            total_time = dp[mask][stage] + cross_time + return_time
                            if dp[new_mask ^ (1 << r)][next_stage] > total_time:
                                dp[new_mask ^ (1 << r)][next_stage] = total_time

        result = min(dp[full_mask])
        return result if result < INF else -1.0

class Solution:
    def maxStability(self, n: int, edges: List[List[int]], k: int) -> int:
        import sys
        sys.setrecursionlimit(2000000)

        must_edges = []
        optional_edges = []
        for u, v, s, must in edges:
            if must == 1:
                must_edges.append((u, v, s))
            else:
                optional_edges.append((u, v, s))

        parent = list(range(n))
        rank = [0] * n

        def find(u):
            while parent[u] != u:
                parent[u] = parent[parent[u]]
                u = parent[u]
            return u

        def union(u, v):
            root_u = find(u)
            root_v = find(v)
            if root_u == root_v:
                return False
            if rank[root_u] > rank[root_v]:
                parent[root_v] = root_u
            else:
                parent[root_u] = root_v
                if rank[root_u] == rank[root_v]:
                    rank[root_v] += 1
            return True

        for u, v, s in must_edges:
            if not union(u, v):
                return -1

        components = set()
        for i in range(n):
            components.add(find(i))
        if len(components) > 1:
            return -1

        parent = list(range(n))
        rank = [0] * n

        for u, v, s in must_edges:
            union(u, v)

        optional_edges.sort(key=lambda x: -x[2])

        low = 0
        high = 0
        if optional_edges:
            high = max(s for u, v, s in optional_edges) * 2
        high = max(high, max(s for u, v, s in must_edges) if must_edges else 0)

        def is_possible(mid):
            parent_copy = parent[:]
            rank_copy = rank[:]

            def find_copy(u):
                while parent_copy[u] != u:
                    parent_copy[u] = parent_copy[parent_copy[u]]
                    u = parent_copy[u]
                return u

            def union_copy(u, v):
                root_u = find_copy(u)
                root_v = find_copy(v)
                if root_u == root_v:
                    return False
                if rank_copy[root_u] > rank_copy[root_v]:
                    parent_copy[root_v] = root_u
                else:
                    parent_copy[root_u] = root_copy[root_v]
                    if rank_copy[root_u] == rank_copy[root_v]:
                        rank_copy[root_v] += 1
                return True

            used_upgrades = 0
            for u, v, s in optional_edges:
                if find_copy(u) == find_copy(v):
                    continue
                if s >= mid:
                    union_copy(u, v)
                else:
                    if used_upgrades < k and 2 * s >= mid:
                        used_upgrades += 1
                        union_copy(u, v)
                    else:
                        pass

            roots = set()
            for i in range(n):
                roots.add(find_copy(i))
            return len(roots) == 1

        left = 0
        right = 0
        if optional_edges:
            right = max(s for u, v, s in optional_edges) * 2
        right = max(right, max(s for u, v, s in must_edges) if must_edges else 0)
        answer = -1

        while left <= right:
            mid = (left + right) // 2
            if is_possible(mid):
                answer = mid
                left = mid + 1
            else:
                right = mid - 1

        return answer

import math
from typing import List

class Solution:
    def minStable(self, nums: List[int], maxC: int) -> int:
        n = len(nums)
        if n == 0:
            return 0

        def possible(target: int) -> bool:
            dp = [0] * (n + 1)
            for i in range(1, n + 1):
                dp[i] = dp[i - 1]
                cnt = 0
                g = 0
                for j in range(i, 0, -1):
                    if g == 0:
                        g = nums[j - 1]
                    else:
                        g = math.gcd(g, nums[j - 1])
                    if g < 2:
                        cnt += 1
                    if cnt > maxC:
                        break
                    if i - j + 1 >= target:
                        dp[i] = max(dp[i], dp[j - 1] + (i - j + 1))
            return dp[n] >= n

        left, right = 1, n
        answer = 0
        while left <= right:
            mid = (left + right) // 2
            if possible(mid):
                answer = mid
                right = mid - 1
            else:
                left = mid + 1
        return answer

class MinStack:

    def __init__(self):
        self.stack = []
        self.min_stack = []

    def push(self, val: int) -> None:
        self.stack.append(val)
        if not self.min_stack or val <= self.min_stack[-1]:
            self.min_stack.append(val)

    def pop(self) -> None:
        if self.stack:
            val = self.stack.pop()
            if val == self.min_stack[-1]:
                self.min_stack.pop()

    def top(self) -> int:
        return self.stack[-1]

    def getMin(self) -> int:
        return self.min_stack[-1]


