class Solution:
    def strangePrinter(self, s: str) -> int:
        n = len(s)
        if n == 0:
            return 0
        dp = [[0] * n for _ in range(n)]
        for i in range(n - 1, -1, -1):
            dp[i][i] = 1
            for j in range(i + 1, n):
                if s[i] == s[j]:
                    dp[i][j] = dp[i][j - 1]
                else:
                    min_val = float('inf')
                    for k in range(i, j):
                        min_val = min(min_val, dp[i][k] + dp[k + 1][j])
                    dp[i][j] = min_val
        return dp[0][n - 1]

class Solution:
    def isRationalEqual(self, s: str, t: str) -> bool:
        def parse(num: str) -> float:
            if '(' not in num:
                return float(num) if '.' in num else float(num + '.0')
            dot = num.index('.')
            op = num.index('(')
            cl = num.index(')')
            int_part = num[:dot] or '0'
            nonrep = num[dot+1:op]
            rep = num[op+1:cl]
            total = int(int_part)
            frac_len = len(nonrep) + len(rep)
            frac = (int(nonrep + rep) - int(nonrep or '0')) / (10 ** len(nonrep) * (10 ** len(rep) - 1))
            return total + frac
        return abs(parse(s) - parse(t)) < 1e-10

class Solution:
    def strWithout3a3b(self, a: int, b: int) -> str:
        res = []
        while a or b:
            if a > b:
                if len(res) >= 2 and res[-1] == res[-2] == 'a':
                    res.append('b')
                    b -= 1
                else:
                    res.append('a')
                    a -= 1
            else:
                if len(res) >= 2 and res[-1] == res[-2] == 'b':
                    res.append('a')
                    a -= 1
                else:
                    res.append('b')
                    b -= 1
        return ''.join(res)

