class Solution {
    public List<Integer> beautifulIndices(String s, String a, String b, int k) {
        List<Integer> listA = findIndices(s, a);
        List<Integer> listB = findIndices(s, b);
        List<Integer> result = new ArrayList<>();
        for (Integer i : listA) {
            if (hasValidJ(listB, i, k)) {
                result.add(i);
            }
        }
        return result;
    }

    private List<Integer> findIndices(String s, String pattern) {
        int n = s.length();
        int len = pattern.length();
        List<Integer> res = new ArrayList<>();
        for (int i = 0; i <= n - len; i++) {
            boolean match = true;
            for (int j = 0; j < len; j++) {
                if (s.charAt(i + j) != pattern.charAt(j)) {
                    match = false;
                    break;
                }
            }
            if (match) {
                res.add(i);
            }
        }
        return res;
    }

    private boolean hasValidJ(List<Integer> listB, int i, int k) {
        if (listB.isEmpty()) return false;
        int target = i - k;
        int pos = Collections.binarySearch(listB, target);
        if (pos >= 0) {
            return true;
        } else {
            pos = -pos - 1;
            if (pos >= listB.size()) return false;
            return listB.get(pos) <= (i + k);
        }
    }
}

class LRUCache:

    def __init__(self, capacity: int):
        self.capacity = capacity
        self.cache = {}
        self.usage_order = []

    def get(self, key: int) -> int:
        if key in self.cache:
            self.usage_order.remove(key)
            self.usage_order.append(key)
            return self.cache[key]
        return -1

    def put(self, key: int, value: int) -> None:
        if key in self.cache:
            self.cache[key] = value
            self.usage_order.remove(key)
            self.usage_order.append(key)
        else:
            if len(self.cache) >= self.capacity:
                lru_key = self.usage_order.pop(0)
                del self.cache[lru_key]
            self.cache[key] = value
            self.usage_order.append(key)

