class Solution:
    def removeInvalidParentheses(self, s: str) -> List[str]:
        visited = set()
        queue = deque([s])
        found = False
        result = []

        def is_valid(string):
            count = 0
            for char in string:
                if char == '(':
                    count += 1
                elif char == ')':
                    count -= 1
                    if count < 0:
                        return False
            return count == 0

        while queue:
            current = queue.popleft()
            if current not in visited:
                visited.add(current)
                if is_valid(current):
                    found = True
                    result.append(current)
                elif not found:
                    for i in range(len(current)):
                        if current[i] in '()':
                            new_str = current[:i] + current[i+1:]
                            if new_str not in visited:
                                queue.append(new_str)
        return result

