class ExamRoom:

    def __init__(self, n: int):
        self.n = n
        self.seats = set()

    def seat(self) -> int:
        if not self.seats:
            self.seats.add(0)
            return 0
        max_dist = 0
        best_seat = 0
        prev = -1
        for curr in sorted(self.seats):
            if prev == -1:
                dist = curr
            else:
                dist = (curr - prev) // 2
            if dist > max_dist:
                max_dist = dist
                best_seat = prev + dist if prev != -1 else curr
            prev = curr
        if (self.n - 1 - prev) > max_dist:
            best_seat = self.n - 1
        self.seats.add(best_seat)
        return best_seat

    def leave(self, p: int) -> None:
        if p in self.seats:
            self.seats.remove(p)

