class Solution:
    def maxScore(self, nums: List[int]) -> int:
        full_mask = (1 << len(nums)) - 1

        @lru_cache(maxsize=None)
        def dfs(mask):
            if mask == full_mask:
                return 0
            used = bin(mask).count(1)
            step = (used // 2) + 1
            max_score = 0
            for i in range(len(nums)):
                if mask & (1 << i):
                    continue
                for j in range(i + 1, len(nums)):
                    if mask & (1 << j):
                        continue
                    new_mask = mask | (1 << i) | (1 << j)
                    current_gcd = math.gcd(nums[i], nums[j])
                    current_total = step * current_gcd + dfs(new_mask)
                    max_score = max(max_score, current_total)
            return max_score

        return dfs(0)

class Solution:
    def countPairs(self, nums: List[int], low: int, high: int) -> int:
        from collections import Counter

        def count_xor_less_than_threshold(threshold):
            count = 0
            freq = Counter()
            for num in nums:
                for prefix in range(threshold + 1):
                    if prefix in freq:
                        count += freq[prefix]
                mask = 0
                for i in range(16):  # since nums[i] <= 2*10^4, 16 bits are enough
                    bit = (threshold >> i) & 1
                    if bit:
                        prefix = num & ((1 << i) - 1)
                        count += freq.get(prefix, 0)
                    mask |= (num >> i) << i
                freq[mask] += 1
            return count

        return count_xor_less_than_threshold(high) - count_xor_less_than_threshold(low - 1)

