from math import gcd
from collections import defaultdict

class Solution:
    def maxGCDScore(self, nums: List[int], k: int) -> int:
        n = len(nums)
        max_score = 0

        for i in range(n):
            g = nums[i]
            max_score = max(max_score, g * 1)
            ops = 0
            for j in range(i + 1, n):
                g = gcd(g, nums[j])
                ops += 0
                max_score = max(max_score, g * (j - i + 1))
                if ops < k:
                    for l in range(i, j + 1):
                        if ops < k:
                            new_gcd = gcd(g, nums[l] * 2)
                            new_ops = ops + 1
                            max_score = max(max_score, new_gcd * (j - i + 1))
                            ops = new_ops
                            g = new_gcd
                        else:
                            break
        return max_score

class Solution:
    def maxStability(self, n: int, edges: List[List[int]], k: int) -> int:
        import heapq

        parent = list(range(n))
        rank = [1] * n

        def find(u):
            if parent[u] != u:
                parent[u] = find(parent[u])
            return parent[u]

        def union(u, v):
            u_root = find(u)
            v_root = find(v)
            if u_root == v_root:
                return False
            if rank[u_root] < rank[v_root]:
                parent[u_root] = v_root
            else:
                parent[v_root] = u_root
                if rank[u_root] == rank[v_root]:
                    rank[u_root] += 1
            return True

        must_edges = []
        optional_edges = []

        for u, v, s, m in edges:
            if m == 1:
                must_edges.append((s, u, v))
            else:
                optional_edges.append((s, u, v))

        # Sort must edges in descending order of strength
        must_edges.sort(reverse=True)

        # Add all must edges to the DSU
        for s, u, v in must_edges:
            union(u, v)

        # Check if all must edges can be added without forming a cycle
        # If not, it's impossible to form a spanning tree
        for s, u, v in must_edges:
            if find(u) == find(v):
                return -1

        # Sort optional edges in ascending order of strength
        optional_edges.sort()

        upgraded_edges = []

        # Upgrade up to k optional edges
        for i in range(min(k, len(optional_edges))):
            s, u, v = optional_edges[i]
            upgraded_edges.append((s * 2, u, v))
        for i in range(k, len(optional_edges)):
            s, u, v = optional_edges[i]
            upgraded_edges.append((s, u, v))

        # Kruskal's algorithm to find the maximum minimum edge in the spanning tree
        upgraded_edges.sort(reverse=True)
        min_strength = float('inf')

        for s, u, v in upgraded_edges:
            if union(u, v):
                min_strength = min(min_strength, s)

        # Check if all nodes are connected
        root = find(0)
        for i in range(1, n):
            if find(i) != root:
                return -1

        return min_strength

from collections import defaultdict

class Solution:
    def minWindow(self, s: str, t: str) -> str:
        if not s or not t:
            return ""

        need = {}
        for c in t:
            need[c] = need.get(c, 0) + 1

        required = len(need)
        window_counts = defaultdict(int)
        have = 0

        left = 0
        min_len = float('inf')
        result = (0, 0)  # start and end indices

        for right, char in enumerate(s):
            if char in need:
                window_counts[char] += 1
                if window_counts[char] == need[char]:
                    have += 1

            while have == required:
                current_length = right - left + 1
                if current_length < min_len:
                    min_len = current_length
                    result = (left, right)

                left_char = s[left]
                if left_char in need:
                    if window_counts[left_char] == need[left_char]:
                        have -= 1
                    window_counts[left_char] -= 1
                left += 1

        return s[result[0]:result[1]+1] if min_len != float('inf') else ""

class Solution:
    def calculate(self, s: str) -> int:
        s = s.replace(' ', '')
        stack = []
        num = 0
        sign = '+'
        for i, c in enumerate(s):
            if c.isdigit():
                num = num * 10 + int(c)
            if not c.isdigit() or i == len(s) - 1:
                if c in '+-*/' or i == len(s) - 1:
                    if sign == '+':
                        stack.append(num)
                    elif sign == '-':
                        stack.append(-num)
                    elif sign == '*':
                        stack.append(stack.pop() * num)
                    elif sign == '/':
                        prev = stack.pop()
                        if prev // num < 0 and prev % num != 0:
                            stack.append(prev // num + 1)
                        else:
                            stack.append(prev // num)
                    sign = c
                    num = 0
        return sum(stack)

