        return ''.join(s)

class Solution:
    def strangePrinter(self, s: str) -> int:
        n = len(s)
        dp = [[0] * n for _ in range(n)]

        for l in range(n - 1, -1, -1):
            dp[l][l] = 1
            for r in range(l + 1, n):
                if s[l] == s[r]:
                    dp[l][r] = dp[l][r - 1]
                else:
                    min_turns = float('inf')
                    for k in range(l, r):
                        min_turns = min(min_turns, dp[l][k] + dp[k + 1][r])
                    dp[l][r] = min_turns

        return dp[0][n - 1]

class Solution:
    def countOfAtoms(self, formula: str) -> str:
        from collections import defaultdict
        import re

        def parse_formula(formula, i):
            counts = defaultdict(int)
            element = ''
            num = ''
            while i < len(formula):
                c = formula[i]
                if c.isupper():
                    if element:
                        counts[element] += 0 if not num else int(num or 1)
                        element = ''
                        num = ''
                    element += c
                elif c.islower():
                    element += c
                elif c.isdigit():
                    num += c
                elif c == '(':
                    if element:
                        counts[element] += 0 if not num else int(num or 1)
                        element = ''
                        num = ''
                    sub_counts, i = parse_formula(formula, i + 1)
                    multiplier = ''
                    i += 1
                    while i < len(formula) and formula[i].isdigit():
                        multiplier += formula[i]
                        i += 1
                    multiplier = int(multiplier) if multiplier else 1
                    for key in sub_counts:
                        counts[key] += sub_counts[key] * multiplier
                    continue
                elif c == ')':
                    if element:
                        counts[element] += 0 if not num else int(num or 1)
                        element = ''
                        num = ''
                    return counts, i + 1
                i += 1
            if element:
                counts[element] += 0 if not num else int(num or 1)
            return counts, i

        counts, _ = parse_formula(formula, 0)
        sorted_elements = sorted(counts.items())
        result = ''
        for element, count in sorted_elements:
            result += element
            if count > 1:
                result += str(count)
        return result

