class Solution:
    def palindromePartition(self, s: str, k: int) -> int:
        n = len(s)
        cost = [[0] * n for _ in range(n)]
        for l in range(2, n + 1):
            for i in range(n - l + 1):
                j = i + l - 1
                if s[i] == s[j]:
                    cost[i][j] = cost[i + 1][j - 1]
                else:
                    cost[i][j] = cost[i + 1][j - 1] + 1
        INF = float('inf')
        dp = [[INF] * (k + 1) for _ in range(n + 1)]
        dp[0][0] = 0
        for i in range(1, n + 1):
            for m in range(1, k + 1):
                for j in range(i):
                    if dp[j][m - 1] != INF:
                        dp[i][m] = min(dp[i][m], dp[j][m - 1] + cost[j][i - 1])
        return dp[n][k]

class Solution:
    def maxFreq(self, s: str, maxLetters: int, minSize: int, maxSize: int) -> int:
        from collections import defaultdict, Counter

        substr_count = defaultdict(int)
        unique_char_count = defaultdict(set)

        n = len(s)
        for i in range(n - minSize + 1):
            substr = s[i:i + minSize]
            unique_chars = set(substr)
            if len(unique_chars) <= maxLetters:
                substr_count[substr] += 1
                unique_char_count[substr] = unique_chars

        max_occurrence = 0
        for substr, count in substr_count.items():
            if len(unique_char_count[substr]) <= maxLetters:
                max_occurrence = max(max_occurrence, count)

        return max_occurrence

class Solution:
    def findBestValue(self, arr: List[int], target: int) -> int:
        arr.sort()
        n = len(arr)
        prefix_sum = [0] * (n + 1)
        for i in range(n):
            prefix_sum[i + 1] = prefix_sum[i] + arr[i]

        left, right = 0, max(arr)
        result = (float('inf'), float('inf'))

        while left <= right:
            mid = (left + right) // 2
            idx = self.find_index(arr, mid)
            total = prefix_sum[idx] + mid * (n - idx)
            diff = abs(total - target)
            if diff < result[0] or (diff == result[0] and mid < result[1]):
                result = (diff, mid)
            if total < target:
                left = mid + 1
            else:
                right = mid - 1

        return result[1]

    def find_index(self, arr: List[int], value: int) -> int:
        left, right = 0, len(arr) - 1
        while left <= right:
            mid = (left + right) // 2
            if arr[mid] < value:
                left = mid + 1
            else:
                right = mid - 1
        return left

