    def numberOfSubstrings(self, s: str) -> int:
        last_a = -1
        last_b = -1
        last_c = -1
        total = 0
        for i, char in enumerate(s):
            if char == 'a':
                last_a = i
            elif char == 'b':
                last_b = i
            else:
                last_c = i
            if last_a != -1 and last_b != -1 and last_c != -1:
                m = min(last_a, last_b, last_c)
                total += (m + 1)
        return total

class Solution:
    def sortString(self, s: str) -> str:
        from collections import Counter

        count = Counter(s)
        result = []
        unique_chars = sorted(count.keys())

        while len(result) < len(s):
            # Step 1-3: Append smallest characters in increasing order
            for ch in unique_chars:
                if count[ch] > 0:
                    result.append(ch)
                    count[ch] -= 1
            # Step 4-6: Append largest characters in decreasing order
            for ch in reversed(unique_chars):
                if count[ch] > 0:
                    result.append(ch)
                    count[ch] -= 1

        return ''.join(result)

