        while i < n and j < m:
            c = str1[i]
            target = str2[j]
            next_c = chr((ord(c) - ord('a') + 1) % 26 + ord('a'))
            if c == target or next_c == target:
                j += 1
            i += 1
        return j == m

import heapq

class Solution:
    def minimizeStringValue(self, s: str) -> str:
        original_counts = [0] * 26
        for c in s:
            if c != '?':
                original_counts[ord(c) - ord('a')] += 1

        heap = []
        for i in range(26):
            heapq.heappush(heap, (original_counts[i], chr(ord('a') + i)))

        m = s.count('?')
        added_letters = []
        for _ in range(m):
            count, char = heapq.heappop(heap)
            added_letters.append(char)
            heapq.heappush(heap, (count + 1, char))

        added_letters.sort()

        res = []
        added_idx = 0
        for c in s:
            if c == '?':
                res.append(added_letters[added_idx])
                added_idx += 1
            else:
                res.append(c)
        return ''.join(res)

class Solution:
    def numberOfStableArrays(self, zero: int, one: int, limit: int) -> int:
        MOD = 10**9 + 7

        from functools import lru_cache

        @lru_cache(None)
        def dp(z, o, last, count):
            if z == 0 and o == 0:
                return 1
            res = 0
            if z > 0 and (last != 0 or count < limit):
                res += dp(z - 1, o, 0, count + 1)
            if o > 0 and (last != 1 or count < limit):
                res += dp(z, o - 1, 1, count + 1)
            return res % MOD

        return dp(zero, one, -1, 0)
